writeNewRepair("tools/cp-testrig/portal_auth.py", "al\",\n                               \"message\": \"API keys are read-only.\"}}),\n            403,\n        )\n    return None", false,
    "\"\"\"\nOmniFlow Control Plane — portal request authentication (customer Bearer tokens).\n\nPortal extension endpoints authenticate the customer by asking the MAIN\nControl Plane app itself: an in-process WSGI call to GET /api/v1/auth/me —\nthe exact same endpoint the website BFF uses. This means token/session\nvalidation is NEVER re-implemented here and can never drift from the\nplatform's own rules.\n\n`ofk_...` tokens are customer-generated PORTAL API KEYS (portal_api_keys\ntable, SHA-256 stored). They authenticate as the tenant but are READ-ONLY:\nmutation endpoints call ensure_human_principal() which rejects them with 403.\n\napp.py binds the composite root application once at import time\n(bind_root_application). No network hop, no extra dependencies.\n\"\"\"\n\nimport hashlib\nimport io\nimport json\nimport logging\nimport sys\nimport threading\nfrom typing import Any, Dict, Optional\n\nfrom flask import jsonify, request\n\nimport portal_db\n\n\nlogger = logging.getLogger(\"omniflow.portal-auth\")\n\n_ROOT_APP = None\n_BIND_LOCK = threading.Lock()\n\n\ndef bind_root_application(app: Any) -> None:\n    \"\"\"Called by app.py AFTER the composite WSGI app is assembled.\"\"\"\n    global _ROOT_APP\n    with _BIND_LOCK:\n        _ROOT_APP = app\n\n\nclass PortalAuthUnavailable(RuntimeError):\n    \"\"\"Token verification itself failed (not a plain 401).\"\"\"\n\n\ndef _wsgi_environ(token: str) -> Dict[str, Any]:\n    return {\n        \"REQUEST_METHOD\": \"GET\",\n        \"PATH_INFO\": \"/api/v1/auth/me\",\n        \"QUERY_STRING\": \"\",\n        \"SERVER_NAME\": \"localhost\",\n        \"SERVER_PORT\": \"443\",\n        \"SERVER_PROTOCOL\": \"HTTP/1.1\",\n        \"CONTENT_LENGTH\": \"0\",\n        \"CONTENT_TYPE\": \"\",\n        \"wsgi.version\": (1, 0),\n        \"wsgi.url_scheme\": \"https\",\n        \"wsgi.input\": io.BytesIO(b\"\"),\n        \"wsgi.errors\": sys.stderr,\n        \"wsgi.multithread\": True,\n        \"wsgi.multiprocess\": True,\n        \"wsgi.run_once\": False,\n        \"HTTP_AUTHORIZATION\": \"Bearer \" + token,\n    }\n\n\ndef _api_key_principal(token: str) -> Optional[Dict[str, Any]]:\n    \"\"\"Validate an ofk_ portal API key against portal_api_keys (SHA-256).\"\"\"\n    token_hash = hashlib.sha256(token.encode(\"utf-8\")).hexdigest()\n    portal_db.ensure_tables()\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"SELECT id, client_id, created_by FROM \"\n                + portal_db._q(portal_db.APIKEY_TABLE) +\n                \" WHERE token_hash = %s AND revoked_at IS NULL\"\n                \" ORDER BY id DESC LIMIT 1\",\n                (token_hash,),\n            )\n            found = portal_db.rows(cur)\n            if found:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(portal_db.APIKEY_TABLE) +\n                    \" SET last_used_at = NOW() WHERE id = %s\",\n                    (found[0][\"id\"],),\n                )\n        conn.commit()\n    finally:\n        conn.close()\n    if not found:\n        return None\n    return {\n        \"session_id\": \"\",\n        \"user_id\": found[0].get(\"created_by\"),\n        \"client_id\": found[0][\"client_id\"],\n        \"role\": \"api_key\",\n        \"email\": \"\",\n        \"display_name\": None,\n        \"via_api_key\": True,\n    }\n\n\ndef authenticate_portal_request() -> Optional[Dict[str, Any]]:\n    \"\"\"\n    Validate the request's Authorization: Bearer token.\n\n    Returns a principal dict {session_id, user_id, client_id, role, email,\n    display_name, [via_api_key]}, or None when the token is\n    missing/invalid/expired (401). Raises PortalAuthUnavailable when\n    verification itself fails (map to 503).\n    \"\"\"\n    header = request.headers.get(\"Authorization\", \"\")\n    if not header.lower().startswith(\"bearer \"):\n        return None\n    token = header[7:].strip()\n    if not token:\n        return None\n    if token.startswith(\"ofk_\"):\n        try:\n            return _api_key_principal(token)\n        except PortalAuthUnavailable:\n            raise\n        except Exception:\n            logger.exception(\"portal api-key lookup failed\")\n            raise PortalAuthUnavailable(\"api-key verification failed\")\n    if _ROOT_APP is None:\n        raise PortalAuthUnavailable(\"root application not bound\")\n\n    captured: Dict[str, Any] = {}\n\n    def start_response(status, headers, exc_info=None):\n        captured[\"status\"] = status\n        captured[\"headers\"] = headers\n        return lambda chunk: None\n\n    body_chunks = []\n    try:\n        for chunk in _ROOT_APP(_wsgi_environ(token), start_response):\n            body_chunks.append(chunk)\n    except Exception:\n        logger.exception(\"in-process /auth/me verification call failed\")\n        raise PortalAuthUnavailable(\"principal verification crashed\")\n\n    body = b\"\".join(body_chunks)\n    status_code = 500\n    try:\n        status_code = int(str(captured.get(\"status\", \"500\")).split(\" \")[0])\n    except (TypeError, ValueError):\n        pass\n\n    if status_code in (401, 403):\n        return None\n    if status_code != 200:\n        logger.warning(\"/auth/me verification returned HTTP %s\", status_code)\n        raise PortalAuthUnavailable(\"principal verification returned \" + str(status_code))\n\n    try:\n        payload = json.loads(body.decode(\"utf-8\"))\n    except Exception:\n        raise PortalAuthUnavailable(\"/auth/me returned a non-JSON body\")\n    if not isinstance(payload, dict):\n        raise PortalAuthUnavailable(\"/auth/me payload was not an object\")\n\n    user_id = payload.get(\"user_id\")\n    client_id = payload.get(\"client_id\")\n    if isinstance(user_id, bool) or isinstance(client_id, bool):\n        raise PortalAuthUnavailable(\"/auth/me ids malformed\")\n    if not isinstance(user_id, int) or not isinstance(client_id, int):\n        raise PortalAuthUnavailable(\"/auth/me payload missing user_id/client_id\")\n\n    return {\n        \"session_id\": str(payload.get(\"session_id\", \"\")),\n        \"user_id\": user_id,\n        \"client_id\": client_id,\n        \"role\": str(payload.get(\"role\", \"\")),\n        \"email\": str(payload.get(\"email\", \"\")),\n        \"display_name\": (\n            payload.get(\"display_name\")\n            if isinstance(payload.get(\"display_name\"), str)\n            else None\n        ),\n    }\n\n\ndef ensure_human_principal(principal: Optional[Dict[str, Any]]) -> Optional[Any]:\n    \"\"\"\n    Mutation guard: portal API keys (ofk_) are READ-ONLY.\n\n    Returns a (json, 403) response when the principal is an API key,\n    None for human (session) principals. Usage:\n\n        principal = authenticate_portal_request()\n        ...\n        forbidden = ensure_human_principal(principal)\n        if forbidden:\n            return forbidden\n    \"\"\"\n    if principal is not None and principal.get(\"via_api_key\"):\n        return (\n            jsonify({\"error\": {\"code\": \"read_only_principal\",\n                               \"message\": \"API keys are read-only.\"}}),\n            403,\n        )\n    return None\n");

writeNewRepair("tools/cp-testrig/portal_conversations.py", "tal_db.portal_unavailable(error, \"customer merge\")[0]), 503\n    return jsonify({\"ok\": True, \"moved\": merge_chats}), 200", false,
    "\"\"\"Portal conversations API (multi-tenant, human + API-key principals).\n\nTest-rig reconstruction of the laptop Control Plane file, conversations\nendpoints only (list+counts, detail, message paging, bulk, export). Regions\nare verbatim from the shipped patchers; see HANDOFF section 54.\n\"\"\"\nimport os\nfrom typing import Any, Optional\n\nimport csv\nimport io\nimport re\n\nfrom flask import Blueprint, jsonify, request, Response\n\nimport portal_db\nfrom portal_auth import authenticate_portal_request, ensure_human_principal\n\nbp = Blueprint(\"portal_conversations\", __name__, url_prefix=\"/api/v1/portal\")\n\nMESSAGE_PAGE_SIZE = 200\nBULK_MAX_IDS = 50\nEXPORT_LIMIT = 500\nALLOWED_STATUS = (\"all\", \"open\", \"closed\")\nMAX_TAGS_PER_CONVERSATION = 6\nMAX_TAG_LENGTH = 24\nMAX_TAG_SUMMARY = 30\n\ntry:\n    OVERDUE_HOURS = max(1, min(72, int(os.environ.get(\"OF_SLA_HOURS\", \"4\"))))\nexcept (TypeError, ValueError):\n    OVERDUE_HOURS = 4\n\n_STAR_COLUMN_READY = False\n\n\ndef _ensure_star_column(conn) -> None:\n    \"\"\"Lazy migration: older databases miss the starred flag (runs once).\"\"\"\n    global _STAR_COLUMN_READY\n    if _STAR_COLUMN_READY:\n        return\n    with conn.cursor() as cur:\n        cur.execute(\n            \"ALTER TABLE \" + portal_db._q(portal_db.CONV_TABLE) +\n            \" ADD COLUMN IF NOT EXISTS starred BOOLEAN NOT NULL DEFAULT FALSE\"\n        )\n        cur.execute(\n            \"CREATE INDEX IF NOT EXISTS idx_portal_messages_conv_dir\"\n            \" ON \" + portal_db._q(portal_db.MSGS_TABLE) +\n            \" (conversation_id, direction, id)\"\n        )\n    conn.commit()\n    _STAR_COLUMN_READY = True\n\n\ndef _iso(value: Any) -> Optional[str]:\n    if value is None:\n        return None\n    try:\n        return value.isoformat()\n    except AttributeError:\n        return None\n\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except Exception:\n        principal = None\n    if not principal:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}), 401)\n    return principal, None\n\n\ndef _conversation_public(row: Any) -> dict:\n    return {\n        \"id\": row.get(\"id\"),\n        \"channel\": row.get(\"channel\") or \"whatsapp\",\n        \"contact_id\": row.get(\"contact_id\"),\n        \"contact_name\": row.get(\"contact_name\"),\n        \"status\": row.get(\"status\") or \"open\",\n        \"last_message_at\": _iso(row.get(\"last_message_at\")),\n        \"last_message_preview\": row.get(\"last_message_preview\"),\n        \"created_at\": _iso(row.get(\"created_at\")),\n        \"unread\": bool(row.get(\"unread\")),\n        \"needs_reply\": bool(row.get(\"needs_reply\")),\n        \"last_intent\": row.get(\"last_intent\"),\n        \"lead_score\": int(row.get(\"lead_score\") or 0),\n        \"lead_temp\": row.get(\"lead_temp\") or \"cold\",\n        \"assigned_to\": row.get(\"assigned_to\"),\n        \"assignee_name\": row.get(\"assignee_name\"),\n        \"starred\": bool(row.get(\"starred\")),\n    }\n\n\ndef _message_public(row: Any) -> dict:\n    return {\n        \"id\": row.get(\"id\"),\n        \"direction\": row.get(\"direction\") or \"in\",\n        \"body\": row.get(\"body\") or \"\",\n        \"status\": row.get(\"status\") or \"received\",\n        \"intent\": row.get(\"intent\"),\n        \"created_at\": _iso(row.get(\"created_at\")),\n    }\n\n\nVIP_THRESHOLD = 3  # paid orders that turn a contact into a VIP\n\n\ndef _paid_order_counts(cur, client_id, contact_ids):\n    \"\"\"contact_id -> paid order count ({} when the links table is absent).\"\"\"\n    ids = sorted({str(cid).strip() for cid in contact_ids\n                  if cid and str(cid).strip()})\n    if not ids:\n        return {}\n    try:\n        cur.execute(\"SELECT to_regclass(%s) AS oid\",\n                    (\"portal_checkout_links\",))\n        rows = portal_db.rows(cur)\n        if not rows or not rows[0].get(\"oid\"):\n            return {}\n        cur.execute(\n            \"SELECT contact_id, COUNT(*) AS orders FROM portal_checkout_links\"\n            \" WHERE client_id = %s AND status = 'paid'\"\n            \" AND contact_id = ANY(%s)\"\n            \" GROUP BY contact_id\",\n            (client_id, ids),\n        )\n        return {str(row.get(\"contact_id\") or \"\"): int(row.get(\"orders\") or 0)\n                for row in portal_db.rows(cur)}\n    except Exception:\n        return {}\n\n\ndef _tags_map(cur, client_id, conversation_ids) -> dict:\n    \"\"\"Return {conversation_id: [tag, ...]} for the given conversations.\"\"\"\n    ids = [int(cid) for cid in conversation_ids if cid is not None]\n    if not ids:\n        return {}\n    cur.execute(\n        \"SELECT id, conversation_id, tag FROM \" + portal_db._q(portal_db.CONV_TAGS_TABLE) +\n        \" WHERE client_id = %s AND conversation_id = ANY(%s) ORDER BY id\",\n        (client_id, ids),\n    )\n    mapping = {}\n    for row in portal_db.rows(cur):\n        mapping.setdefault(row.get(\"conversation_id\"), []).append(\n            str(row.get(\"tag\") or \"\")\n        )\n    return mapping\n\n\n@bp.get(\"/conversations\")\ndef list_conversations():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n\n    status = (request.args.get(\"status\") or \"all\").strip().lower()\n    if status not in ALLOWED_STATUS:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"status must be all, open, or closed.\"}}), 400\n    raw_limit = request.args.get(\"limit\", \"\")\n    try:\n        limit = int(raw_limit) if raw_limit else 50\n    except (TypeError, ValueError):\n        limit = 50\n    limit = max(1, min(50, limit))\n    raw_page = request.args.get(\"page\") or \"\"\n    try:\n        page = int(raw_page) if raw_page else 1\n    except (TypeError, ValueError):\n        page = 1\n    page = max(1, page)\n\n    search = (request.args.get(\"q\") or \"\").strip()\n    if len(search) > 100:\n        search = search[:100]\n    sort_order = (request.args.get(\"sort\") or \"\").strip().lower()\n    if sort_order not in (\"\", \"oldest\"):\n        sort_order = \"\"\n    assigned_filter = (request.args.get(\"assigned\") or \"\").strip().lower()\n    if assigned_filter not in (\"\", \"unassigned\", \"me\"):\n        assigned_filter = \"\"\n    days_filter = (request.args.get(\"days\") or \"\").strip()\n    if days_filter not in (\"\", \"1\", \"7\", \"30\"):\n        days_filter = \"\"\n    unread_filter = (request.args.get(\"unread\") or \"\").strip()\n    if unread_filter != \"1\":\n        unread_filter = \"\"\n    include_counts = (request.args.get(\"include\") or \"\").strip().lower() == \"counts\"\n    include_raw = (request.args.get(\"include\") or \"\").strip().lower()\n    include_vip = \"vip\" in include_raw.split(\",\")\n    starred_filter = (request.args.get(\"starred\") or \"\").strip()\n    if starred_filter != \"1\":\n        starred_filter = \"\"\n\n    sql = (\n        \"SELECT c.id, c.channel, c.contact_id, c.contact_name, c.status,\"\n        \" c.last_message_at, c.last_message_preview, c.created_at, c.last_intent,\"\n        \" c.lead_score, c.lead_temp, c.assigned_to, c.starred, tm.name AS assignee_name,\"\n        \" EXISTS (\"\n        \" SELECT 1 FROM \" + portal_db._q(portal_db.MSGS_TABLE) +\n        \" m WHERE m.conversation_id = c.id AND m.direction = 'in'\"\n        \" AND m.created_at > COALESCE(c.last_read_at, TO_TIMESTAMP(0))\"\n        \" ) AS unread, EXISTS (\"\n        \" SELECT 1 FROM \" + portal_db._q(portal_db.MSGS_TABLE) +\n        \" lr WHERE lr.conversation_id = c.id\"\n        \" GROUP BY lr.conversation_id\"\n        \" HAVING COALESCE(MAX(CASE WHEN lr.direction = 'in' THEN lr.id END), 0)\"\n        \" > COALESCE(MAX(CASE WHEN lr.direction = 'out' THEN lr.id END), 0)\"\n        \" ) AS needs_reply FROM \"\n        + portal_db._q(portal_db.CONV_TABLE) + \" c\"\n        \" LEFT JOIN \" + portal_db._q(portal_db.TEAM_TABLE) + \" tm\"\n        \" ON tm.client_id = c.client_id AND tm.email = c.assigned_to\"\n        \" WHERE c.client_id = %s\"\n    )\n    params = [principal[\"client_id\"]]\n    if status != \"all\":\n        sql += \" AND c.status = %s\"\n        params.append(status)\n    intent_filter = (request.args.get(\"intent\") or \"\").strip().lower()\n    if intent_filter and intent_filter != \"all\":\n        sql += \" AND c.last_intent = %s\"\n        params.append(intent_filter[:40])\n    channel_filter = (request.args.get(\"channel\") or \"\").strip().lower()\n    if channel_filter in (\"whatsapp\", \"website\"):\n        sql += \" AND c.channel = %s\"\n        params.append(channel_filter)\n    tag_filter = (request.args.get(\"tag\") or \"\").strip()[:MAX_TAG_LENGTH]\n    if tag_filter:\n        sql += (\n            \" AND EXISTS (SELECT 1 FROM \" + portal_db._q(portal_db.CONV_TAGS_TABLE) +\n            \" ct WHERE ct.conversation_id = c.id AND ct.client_id = c.client_id\"\n            \" AND LOWER(ct.tag) = LOWER(%s))\"\n        )\n        params.append(tag_filter)\n    if assigned_filter == \"unassigned\":\n        sql += \" AND c.assigned_to IS NULL\"\n    elif assigned_filter == \"me\":\n        sql += \" AND c.assigned_to = %s\"\n        params.append(principal[\"email\"])\n\n    if days_filter:\n        sql += \" AND c.last_message_at >= NOW() - make_interval(days => %s)\"\n        params.append(int(days_filter))\n    if unread_filter == \"1\":\n        sql += (\n            \" AND EXISTS (SELECT 1 FROM \" + portal_db._q(portal_db.MSGS_TABLE) +\n            \" nb WHERE nb.conversation_id = c.id\"\n            \" AND nb.created_at > COALESCE(c.last_read_at, TO_TIMESTAMP(0)))\"\n        )\n    if starred_filter == \"1\":\n        sql += \" AND c.starred = TRUE\"\n\n    needs_reply_filter = (request.args.get(\"needs_reply\") or \"\").strip()\n    if needs_reply_filter in (\"1\", \"overdue\"):\n        sql += (\n            \" AND EXISTS (SELECT 1 FROM \" + portal_db._q(portal_db.MSGS_TABLE) +\n            \" nr WHERE nr.conversation_id = c.id\"\n            \" GROUP BY nr.conversation_id\"\n            \" HAVING COALESCE(MAX(CASE WHEN nr.direction = 'in' THEN nr.id END), 0)\"\n            \" > COALESCE(MAX(CASE WHEN nr.direction = 'out' THEN nr.id END), 0)\"\n        )\n        if needs_reply_filter == \"overdue\":\n            sql += (\n                \" AND MAX(CASE WHEN nr.direction = 'in' THEN nr.created_at END)\"\n                \" < NOW() - make_interval(hours => %s)\"\n            )\n            params.append(OVERDUE_HOURS)\n        sql += \")\"\n    if search:\n        like = \"%\" + search.replace(\"\\\\\", \"\\\\\\\\\").replace(\"%\", \"\\\\%\").replace(\"_\", \"\\\\_\") + \"%\"\n        sql += (\n            \" AND (c.contact_name ILIKE %s OR c.contact_id ILIKE %s\"\n            \" OR EXISTS (SELECT 1 FROM \" + portal_db._q(portal_db.MSGS_TABLE) +\n            \" sm WHERE sm.conversation_id = c.id AND sm.body ILIKE %s))\"\n        )\n        params.extend([like, like, like])\n    if sort_order == \"oldest\":\n        sql += \" ORDER BY c.starred DESC, c.last_message_at ASC NULLS LAST, c.id ASC LIMIT %s\"\n    else:\n        sql += \" ORDER BY c.starred DESC, c.last_message_at DESC NULLS LAST, c.id DESC LIMIT %s\"\n    params.append(limit)\n    if page > 1:\n        sql += \" OFFSET %s\"\n        params.append((page - 1) * limit)\n\n    tags_map = {}\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        _ensure_star_column(conn)\n        try:\n            with conn.cursor() as cur:\n                cur.execute(sql, tuple(params))\n                found = portal_db.rows(cur)\n                tags_map = _tags_map(cur, principal[\"client_id\"],\n                                     [row.get(\"id\") for row in found])\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"conversations read\")[0]), 503\n\n    conversations = []\n    for row in found:\n        item = _conversation_public(row)\n        item[\"tags\"] = tags_map.get(row.get(\"id\"), [])\n        conversations.append(item)\n\n    if include_vip:\n        vip_map = {}\n        try:\n            portal_db.ensure_tables()\n            conn = portal_db._conn()\n            try:\n                with conn.cursor() as cur:\n                    vip_map = _paid_order_counts(\n                        cur, principal[\"client_id\"],\n                        [row.get(\"contact_id\") for row in found])\n            finally:\n                conn.close()\n        except Exception:\n            vip_map = {}\n        for item in conversations:\n            orders = int(vip_map.get(str(item.get(\"contact_id\") or \"\"), 0))\n            item[\"paid_orders\"] = orders\n            item[\"vip\"] = orders >= VIP_THRESHOLD\n\n    counts = {\"needs_reply\": 0, \"overdue\": 0, \"unassigned\": 0, \"unread\": 0}\n    if include_counts:\n        counts_sql = (\n            \" WITH recent AS (\"\n            \" SELECT m.conversation_id,\"\n            \" COALESCE(MAX(CASE WHEN m.direction = 'in' THEN m.id END), 0) AS last_in,\"\n            \" MAX(CASE WHEN m.direction = 'in' THEN m.created_at END) AS last_in_at,\"\n            \" COALESCE(MAX(CASE WHEN m.direction = 'out' THEN m.id END), 0) AS last_out\"\n            \" FROM \" + portal_db._q(portal_db.MSGS_TABLE) + \" m\"\n            \" JOIN \" + portal_db._q(portal_db.CONV_TABLE) + \" oc\"\n            \" ON oc.id = m.conversation_id\"\n            \" WHERE oc.client_id = %s AND oc.status = 'open'\"\n            \" GROUP BY m.conversation_id\"\n            \" )\"\n            \" SELECT COUNT(*) FILTER (WHERE recent.last_in > recent.last_out) AS needs_reply,\"\n            \" COUNT(*) FILTER (WHERE recent.last_in > recent.last_out\"\n            \" AND recent.last_in_at < NOW() - make_interval(hours => %s)) AS overdue,\"\n            \" COUNT(*) FILTER (WHERE recent.last_in_at > COALESCE(c.last_read_at, TO_TIMESTAMP(0))) AS unread,\"\n            \" COUNT(*) FILTER (WHERE c.assigned_to IS NULL) AS unassigned\"\n            \" FROM \" + portal_db._q(portal_db.CONV_TABLE) + \" c\"\n            \" LEFT JOIN recent ON recent.conversation_id = c.id\"\n            \" WHERE c.client_id = %s AND c.status = 'open'\"\n        )\n        try:\n            portal_db.ensure_tables()\n            conn = portal_db._conn()\n            try:\n                with conn.cursor() as cur:\n                    cur.execute(counts_sql, (principal[\"client_id\"], OVERDUE_HOURS, principal[\"client_id\"]))\n                    summary = portal_db.rows(cur)\n                    if summary:\n                        counts = {\n                            \"needs_reply\": int(summary[0].get(\"needs_reply\") or 0),\n                            \"overdue\": int(summary[0].get(\"overdue\") or 0),\n                            \"unassigned\": int(summary[0].get(\"unassigned\") or 0),\n                            \"unread\": int(summary[0].get(\"unread\") or 0),\n                        }\n            finally:\n                conn.close()\n        except Exception:\n            counts = {\"needs_reply\": 0, \"overdue\": 0, \"unassigned\": 0, \"unread\": 0}\n\n    response_payload = {\"conversations\": conversations}\n    if include_counts:\n        response_payload[\"counts\"] = counts\n    return jsonify(response_payload), 200\n\n\n@bp.get(\"/conversations/<int:conversation_id>\")\ndef conversation_detail(conversation_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        _ensure_star_column(conn)\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT id, channel, contact_id, contact_name, status,\"\n                    \" last_message_at, last_message_preview, created_at,\"\n                    \" c.lead_score, c.lead_temp, c.assigned_to, c.starred,\"\n                    \" tm.name AS assignee_name FROM \"\n                    + portal_db._q(portal_db.CONV_TABLE) + \" c\"\n                    \" LEFT JOIN \" + portal_db._q(portal_db.TEAM_TABLE) + \" tm\"\n                    \" ON tm.client_id = c.client_id AND tm.email = c.assigned_to\"\n                    \" WHERE c.id = %s AND c.client_id = %s LIMIT 1\",\n                    (conversation_id, principal[\"client_id\"]),\n                )\n                found = portal_db.rows(cur)\n                if not found:\n                    # Other tenant's (or unknown) conversation -> plain 404.\n                    return jsonify({\"error\": {\"code\": \"not_found\",\n                                              \"message\": \"Conversation not found.\"}}), 404\n                cur.execute(\n                    \"SELECT id, direction, body, status, intent, created_at FROM \"\n                    + portal_db._q(portal_db.MSGS_TABLE) +\n                    \" WHERE conversation_id = %s ORDER BY id DESC LIMIT %s\",\n                    (conversation_id, MESSAGE_PAGE_SIZE + 1),\n                )\n                msgs = portal_db.rows(cur)\n                has_more = len(msgs) > MESSAGE_PAGE_SIZE\n                if has_more:\n                    msgs = msgs[:MESSAGE_PAGE_SIZE]\n                detail_tags = _tags_map(\n                    cur, principal[\"client_id\"], [conversation_id]\n                ).get(conversation_id, [])\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(portal_db.CONV_TABLE) +\n                    \" SET last_read_at = NOW()\"\n                    \" WHERE id = %s AND client_id = %s\",\n                    (conversation_id, principal[\"client_id\"]),\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"conversation detail\")[0]), 503\n\n    conversation_public = _conversation_public(found[0])\n    conversation_public[\"tags\"] = detail_tags\n    vip_map = {}\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                vip_map = _paid_order_counts(\n                    cur, principal[\"client_id\"],\n                    [found[0].get(\"contact_id\")])\n        finally:\n            conn.close()\n    except Exception:\n        vip_map = {}\n    vip_orders = int(vip_map.get(str(found[0].get(\"contact_id\") or \"\"), 0))\n    conversation_public[\"paid_orders\"] = vip_orders\n    conversation_public[\"vip\"] = vip_orders >= VIP_THRESHOLD\n    return jsonify({\n        \"conversation\": conversation_public,\n        \"messages\": [_message_public(m) for m in reversed(msgs)],\n        \"has_more\": has_more,\n    }), 200\n\n\n@bp.get(\"/conversations/<int:conversation_id>/messages\")\ndef conversation_messages(conversation_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n\n    raw_before = request.args.get(\"before_id\") or \"\"\n    try:\n        before_id = int(raw_before) if raw_before else 0\n    except (TypeError, ValueError):\n        before_id = 0\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT 1 FROM \" + portal_db._q(portal_db.CONV_TABLE) +\n                    \" WHERE id = %s AND client_id = %s LIMIT 1\",\n                    (conversation_id, principal[\"client_id\"]),\n                )\n                if not portal_db.rows(cur):\n                    return jsonify({\"error\": {\"code\": \"not_found\",\n                                              \"message\": \"Conversation not found.\"}}), 404\n                if before_id > 0:\n                    cur.execute(\n                        \"SELECT id, direction, body, status, intent, created_at FROM \"\n                        + portal_db._q(portal_db.MSGS_TABLE) +\n                        \" WHERE conversation_id = %s AND id < %s\"\n                        \" ORDER BY id DESC LIMIT %s\",\n                        (conversation_id, before_id, MESSAGE_PAGE_SIZE + 1),\n                    )\n                else:\n                    cur.execute(\n                        \"SELECT id, direction, body, status, intent, created_at FROM \"\n                        + portal_db._q(portal_db.MSGS_TABLE) +\n                        \" WHERE conversation_id = %s\"\n                        \" ORDER BY id DESC LIMIT %s\",\n                        (conversation_id, MESSAGE_PAGE_SIZE + 1),\n                    )\n                msgs = portal_db.rows(cur)\n                has_more = len(msgs) > MESSAGE_PAGE_SIZE\n                if has_more:\n                    msgs = msgs[:MESSAGE_PAGE_SIZE]\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"conversation messages\")[0]), 503\n    return jsonify({\n        \"messages\": [_message_public(m) for m in reversed(msgs)],\n        \"has_more\": has_more,\n    }), 200\n\n\n@bp.post(\"/conversations/<int:conversation_id>/star\")\ndef toggle_conversation_star(conversation_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        _ensure_star_column(conn)\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(portal_db.CONV_TABLE) +\n                    \" SET starred = NOT COALESCE(starred, FALSE)\"\n                    \" WHERE id = %s AND client_id = %s\"\n                    \" RETURNING starred\",\n                    (conversation_id, principal[\"client_id\"]),\n                )\n                updated = portal_db.rows(cur)\n                if updated:\n                    portal_db.log_action(\n                        cur,\n                        principal[\"client_id\"],\n                        \"conversation.star_toggled\",\n                        \"customer_user\",\n                        principal.get(\"user_id\"),\n                        conversation_id,\n                        \"Star \" + (\"on\" if updated[0].get(\"starred\") else \"off\") + \".\",\n                    )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"conversation star\")[0]), 503\n    if not updated:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Conversation not found.\"}}), 404\n    return jsonify({\"ok\": True, \"starred\": bool(updated[0].get(\"starred\"))}), 200\n\n\n@bp.post(\"/conversations/bulk\")\ndef bulk_update_conversations():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n\n    payload = request.get_json(silent=True) or {}\n    action = str(payload.get(\"action\") or \"\").strip().lower()\n    if action not in (\"close\", \"reopen\", \"assign\", \"unassign\"):\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"action must be close, reopen, assign, or unassign.\"}}), 400\n    raw_ids = payload.get(\"ids\")\n    if not isinstance(raw_ids, list):\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"ids must be a list.\"}}), 400\n    ids = []\n    for value in raw_ids[:BULK_MAX_IDS]:\n        if isinstance(value, int) and not isinstance(value, bool) and value > 0 and value not in ids:\n            ids.append(value)\n    if not ids:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"At least one conversation id is required.\"}}), 400\n\n    assignee = \"\"\n    if action == \"assign\":\n        assignee = str(payload.get(\"assignee_email\") or \"\").strip().lower()[:120]\n        if not assignee:\n            return jsonify({\"error\": {\"code\": \"bad_request\",\n                                      \"message\": \"assignee_email is required for assign.\"}}), 400\n\n    status_value = {\"close\": \"closed\", \"reopen\": \"open\"}.get(action)\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                if action == \"assign\":\n                    cur.execute(\n                        \"SELECT 1 FROM \" + portal_db._q(portal_db.TEAM_TABLE) +\n                        \" WHERE client_id = %s AND email = %s\"\n                        \" AND (status = 'active' OR status IS NULL) LIMIT 1\",\n                        (principal[\"client_id\"], assignee),\n                    )\n                    if not portal_db.rows(cur):\n                        return jsonify({\"error\": {\"code\": \"assignee_not_found\",\n                                                  \"message\": \"That teammate is not an active member.\"}}), 404\n                if status_value:\n                    cur.execute(\n                        \"UPDATE \" + portal_db._q(portal_db.CONV_TABLE) +\n                        \" SET status = %s, updated_at = NOW()\"\n                        \" WHERE client_id = %s AND id = ANY(%s) RETURNING id\",\n                        (status_value, principal[\"client_id\"], ids),\n                    )\n                elif action == \"assign\":\n                    cur.execute(\n                        \"UPDATE \" + portal_db._q(portal_db.CONV_TABLE) +\n                        \" SET assigned_to = %s, updated_at = NOW()\"\n                        \" WHERE client_id = %s AND id = ANY(%s) RETURNING id\",\n                        (assignee, principal[\"client_id\"], ids),\n                    )\n                else:\n                    cur.execute(\n                        \"UPDATE \" + portal_db._q(portal_db.CONV_TABLE) +\n                        \" SET assigned_to = NULL, updated_at = NOW()\"\n                        \" WHERE client_id = %s AND id = ANY(%s) RETURNING id\",\n                        (principal[\"client_id\"], ids),\n                    )\n                updated = portal_db.rows(cur)\n                portal_db.log_action(\n                    cur,\n                    principal[\"client_id\"],\n                    \"conversation.bulk_\" + action,\n                    \"customer_user\",\n                    principal.get(\"user_id\"),\n                    None,\n                    \"Bulk \" + action + \" on \" + str(len(updated)) + \" conversations.\",\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"conversation bulk update\")[0]), 503\n    return jsonify({\"ok\": True, \"updated\": len(updated)}), 200\n\n\nimport json\n\n_DEFAULT_BUSINESS_HOURS = {\n    \"enabled\": False,\n    \"timezone\": \"Asia/Karachi\",\n    \"days\": [\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n    ],\n    \"away_message\": \"Thanks for your message! Our team is currently offline. We will reply during business hours.\",\n}\n\n_SETTINGS_TABLE_READY = False\n\n\ndef _ensure_settings_table() -> None:\n    global _SETTINGS_TABLE_READY\n    if _SETTINGS_TABLE_READY:\n        return\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(\"client_settings\") +\n                \" (client_id BIGINT PRIMARY KEY, settings JSONB NOT NULL DEFAULT '{}'::jsonb,\"\n                \" updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())\"\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    _SETTINGS_TABLE_READY = True\n\n\ndef _validate_business_hours(config) -> list:\n    problems = []\n    if not isinstance(config, dict):\n        return [\"business_hours must be an object.\"]\n    if not isinstance(config.get(\"enabled\"), bool):\n        problems.append(\"enabled must be a boolean.\")\n    timezone = config.get(\"timezone\")\n    if not isinstance(timezone, str) or not timezone or len(timezone) > 64:\n        problems.append(\"timezone must be a short string.\")\n    days = config.get(\"days\")\n    if not isinstance(days, list) or len(days) != 7:\n        problems.append(\"days must list all seven days.\")\n    else:\n        for day in days:\n            if not isinstance(day, dict) or not isinstance(day.get(\"enabled\"), bool):\n                problems.append(\"each day needs an enabled flag.\")\n                break\n            for field in (\"start\", \"end\"):\n                value = day.get(field)\n                if (\n                    not isinstance(value, str)\n                    or len(value) != 5\n                    or value[2] != \":\"\n                    or not value[:2].isdigit()\n                    or not value[3:].isdigit()\n                ):\n                    problems.append(\"day times must be HH:MM.\")\n                    break\n    message = config.get(\"away_message\")\n    if not isinstance(message, str) or len(message) > 500:\n        problems.append(\"away_message must be at most 500 characters.\")\n    for variant_key in (\"away_message_ur\", \"away_message_roman\"):\n        variant = config.get(variant_key)\n        if variant is not None and (not isinstance(variant, str)\n                                    or len(variant) > 500):\n            problems.append(variant_key + \" must be at most 500 characters.\")\n    return problems\n\n\n@bp.get(\"/business-hours\")\ndef get_business_hours():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n\n    try:\n        _ensure_settings_table()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT settings -> 'business_hours' AS business_hours FROM \" +\n                    portal_db._q(\"client_settings\") +\n                    \" WHERE client_id = %s\",\n                    (principal[\"client_id\"],),\n                )\n                rows = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"business hours\")[0]), 503\n\n    stored = rows[0].get(\"business_hours\") if rows and rows[0] else None\n    config = stored if isinstance(stored, dict) else _DEFAULT_BUSINESS_HOURS\n    return jsonify({\"business_hours\": config}), 200\n\n\n@bp.put(\"/business-hours\")\ndef update_business_hours():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n\n    payload = request.get_json(silent=True) or {}\n    config = payload.get(\"business_hours\")\n    problems = _validate_business_hours(config)\n    if problems:\n        return jsonify({\"error\": {\"code\": \"bad_request\", \"message\": \" \".join(problems)}}), 400\n\n    try:\n        _ensure_settings_table()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(\"client_settings\") +\n                    \" (client_id, settings) VALUES (%s, %s::jsonb)\"\n                    \" ON CONFLICT (client_id) DO UPDATE SET\"\n                    \" settings = client_settings.settings || EXCLUDED.settings,\"\n                    \" updated_at = NOW()\",\n                    (principal[\"client_id\"], json.dumps({\"business_hours\": config})),\n                )\n                portal_db.log_action(\n                    cur,\n                    principal[\"client_id\"],\n                    \"business_hours.update\",\n                    \"customer_user\",\n                    principal.get(\"user_id\"),\n                    None,\n                    \"Business hours updated.\",\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"business hours update\")[0]), 503\n    return jsonify({\"ok\": True, \"business_hours\": config}), 200\n\n\n@bp.post(\"/conversations/read-all\")\ndef mark_all_conversations_read():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(portal_db.CONV_TABLE) +\n                    \" SET last_read_at = NOW()\"\n                    \" WHERE client_id = %s AND status = 'open' RETURNING id\",\n                    (principal[\"client_id\"],),\n                )\n                updated = portal_db.rows(cur)\n                portal_db.log_action(\n                    cur,\n                    principal[\"client_id\"],\n                    \"conversation.read_all\",\n                    \"customer_user\",\n                    principal.get(\"user_id\"),\n                    None,\n                    \"Marked \" + str(len(updated)) + \" conversations read.\",\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"conversation read-all\")[0]), 503\n    return jsonify({\"ok\": True, \"updated\": len(updated)}), 200\n\n\n@bp.get(\"/conversations/export\")\ndef export_conversations():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n\n    status = (request.args.get(\"status\") or \"all\").strip().lower()\n    if status not in ALLOWED_STATUS:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"status must be all, open, or closed.\"}}), 400\n    search = (request.args.get(\"q\") or \"\").strip()[:100]\n    sort_order = (request.args.get(\"sort\") or \"\").strip().lower()\n    if sort_order not in (\"\", \"oldest\"):\n        sort_order = \"\"\n    assigned_filter = (request.args.get(\"assigned\") or \"\").strip().lower()\n    if assigned_filter not in (\"\", \"unassigned\", \"me\"):\n        assigned_filter = \"\"\n    days_filter = (request.args.get(\"days\") or \"\").strip()\n    if days_filter not in (\"\", \"1\", \"7\", \"30\"):\n        days_filter = \"\"\n    unread_filter = (request.args.get(\"unread\") or \"\").strip()\n    if unread_filter != \"1\":\n        unread_filter = \"\"\n    starred_filter = (request.args.get(\"starred\") or \"\").strip()\n    if starred_filter != \"1\":\n        starred_filter = \"\"\n    raw_id_parts = (request.args.get(\"ids\") or \"\").split(\",\")\n    export_ids = []\n    for part in raw_id_parts[:100]:\n        part = part.strip()\n        if part.isdigit():\n            value = int(part)\n            if value > 0 and value not in export_ids:\n                export_ids.append(value)\n    intent_filter = (request.args.get(\"intent\") or \"\").strip().lower()\n    channel_filter = (request.args.get(\"channel\") or \"\").strip().lower()\n    tag_filter = (request.args.get(\"tag\") or \"\").strip()[:MAX_TAG_LENGTH]\n\n    sql = (\n        \"SELECT c.id, c.channel, c.contact_id, c.contact_name, c.status,\"\n        \" c.last_message_at, c.last_message_preview, c.created_at, c.last_intent,\"\n        \" c.lead_score, c.lead_temp, c.assigned_to, c.starred, tm.name AS assignee_name\"\n        \" FROM \" + portal_db._q(portal_db.CONV_TABLE) + \" c\"\n        \" LEFT JOIN \" + portal_db._q(portal_db.TEAM_TABLE) + \" tm\"\n        \" ON tm.client_id = c.client_id AND tm.email = c.assigned_to\"\n        \" WHERE c.client_id = %s\"\n    )\n    params = [principal[\"client_id\"]]\n    if status != \"all\":\n        sql += \" AND c.status = %s\"\n        params.append(status)\n    if intent_filter and intent_filter != \"all\":\n        sql += \" AND c.last_intent = %s\"\n        params.append(intent_filter[:40])\n    if channel_filter in (\"whatsapp\", \"website\"):\n        sql += \" AND c.channel = %s\"\n        params.append(channel_filter)\n    if tag_filter:\n        sql += (\n            \" AND EXISTS (SELECT 1 FROM \" + portal_db._q(portal_db.CONV_TAGS_TABLE) +\n            \" ct WHERE ct.conversation_id = c.id AND ct.client_id = c.client_id\"\n            \" AND LOWER(ct.tag) = LOWER(%s))\"\n        )\n        params.append(tag_filter)\n    if assigned_filter == \"unassigned\":\n        sql += \" AND c.assigned_to IS NULL\"\n    elif assigned_filter == \"me\":\n        sql += \" AND c.assigned_to = %s\"\n        params.append(principal[\"email\"])\n\n    if days_filter:\n        sql += \" AND c.last_message_at >= NOW() - make_interval(days => %s)\"\n        params.append(int(days_filter))\n    if unread_filter == \"1\":\n        sql += (\n            \" AND EXISTS (SELECT 1 FROM \" + portal_db._q(portal_db.MSGS_TABLE) +\n            \" nb WHERE nb.conversation_id = c.id\"\n            \" AND nb.created_at > COALESCE(c.last_read_at, TO_TIMESTAMP(0)))\"\n        )\n    if starred_filter == \"1\":\n        sql += \" AND c.starred = TRUE\"\n    if export_ids:\n        sql += \" AND c.id = ANY(%s)\"\n        params.append(export_ids)\n\n    needs_reply_filter = (request.args.get(\"needs_reply\") or \"\").strip()\n    export_reply = needs_reply_filter\n    if export_reply in (\"1\", \"overdue\"):\n        sql += (\n            \" AND EXISTS (SELECT 1 FROM \" + portal_db._q(portal_db.MSGS_TABLE) +\n            \" nr WHERE nr.conversation_id = c.id\"\n            \" GROUP BY nr.conversation_id\"\n            \" HAVING COALESCE(MAX(CASE WHEN nr.direction = 'in' THEN nr.id END), 0)\"\n            \" > COALESCE(MAX(CASE WHEN nr.direction = 'out' THEN nr.id END), 0)\"\n        )\n        if export_reply == \"overdue\":\n            sql += (\n                \" AND MAX(CASE WHEN nr.direction = 'in' THEN nr.created_at END)\"\n                \" < NOW() - make_interval(hours => %s)\"\n            )\n            params.append(OVERDUE_HOURS)\n        sql += \")\"\n    if search:\n        like = \"%\" + search.replace(\"\\\\\", \"\\\\\\\\\").replace(\"%\", \"\\\\%\").replace(\"_\", \"\\\\_\") + \"%\"\n        sql += (\n            \" AND (c.contact_name ILIKE %s OR c.contact_id ILIKE %s\"\n            \" OR EXISTS (SELECT 1 FROM \" + portal_db._q(portal_db.MSGS_TABLE) +\n            \" sm WHERE sm.conversation_id = c.id AND sm.body ILIKE %s))\"\n        )\n        params.extend([like, like, like])\n    if sort_order == \"oldest\":\n        sql += \" ORDER BY c.starred DESC, c.last_message_at ASC NULLS LAST, c.id ASC LIMIT %s\"\n    else:\n        sql += \" ORDER BY c.starred DESC, c.last_message_at DESC NULLS LAST, c.id DESC LIMIT %s\"\n    params.append(EXPORT_LIMIT)\n\n    tags_map = {}\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        _ensure_star_column(conn)\n        try:\n            with conn.cursor() as cur:\n                cur.execute(sql, tuple(params))\n                found = portal_db.rows(cur)\n                tags_map = _tags_map(cur, principal[\"client_id\"],\n                                     [row.get(\"id\") for row in found])\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"conversations export\")[0]), 503\n\n    conversations = []\n    for row in found:\n        item = _conversation_public(row)\n        item[\"tags\"] = tags_map.get(row.get(\"id\"), [])\n        conversations.append(item)\n    return jsonify({\"conversations\": conversations}), 200\n\n\n\n\n\n# ---------------------------------------------------------------------------\n# Customers (contacts aggregated across all their conversations)\n# ---------------------------------------------------------------------------\n\nCUSTOMERS_LIMIT = 100\nWARM_LEAD_SCORE = 35\n\n\ndef _normalize_pk_phone(raw: str):\n    \"\"\"Normalize PK numbers to 92xxxxxxxxxx; None when unusable.\"\"\"\n    digits = \"\".join(ch for ch in str(raw or \"\") if ch.isdigit())\n    if digits.startswith(\"0092\"):\n        digits = digits[4:]\n    elif digits.startswith(\"92\"):\n        digits = digits[2:]\n    elif digits.startswith(\"0\"):\n        digits = digits[1:]\n    if len(digits) == 10 and digits.startswith(\"3\"):\n        digits = \"92\" + digits\n    if len(digits) < 10 or len(digits) > 12 or not digits.startswith(\"92\"):\n        return None\n    if len(digits) != 12:\n        return None\n    return digits\n\n\n@bp.post(\"/customers/import\")\ndef import_customers():\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    payload = request.get_json(silent=True) or {}\n    rows = payload.get(\"customers\")\n    if not isinstance(rows, list) or not rows:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"customers list is required.\"}}), 400\n    if len(rows) > 300:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"Import at most 300 customers per request.\"}}), 400\n    prepared = {}\n    invalid = []\n    for index, row in enumerate(rows):\n        if not isinstance(row, dict):\n            invalid.append({\"row\": index + 1, \"reason\": \"not an object\"})\n            continue\n        name = str(row.get(\"name\") or \"\").strip()[:120]\n        phone = _normalize_pk_phone(row.get(\"phone\"))\n        if phone is None:\n            invalid.append({\"row\": index + 1, \"reason\": \"unusable phone number\"})\n            continue\n        prepared.setdefault(phone, name)\n    created = 0\n    merged = 0\n    if prepared:\n        try:\n            portal_db.ensure_tables()\n            conn = portal_db._conn()\n            try:\n                with conn.cursor() as cur:\n                    for phone, name in prepared.items():\n                        cur.execute(\n                            \"INSERT INTO \" + portal_db._q(portal_db.CONV_TABLE) +\n                            \" (client_id, channel, contact_id, contact_name, status)\"\n                            \" VALUES (%s, 'whatsapp', %s, %s, 'open')\"\n                            \" ON CONFLICT (client_id, channel, contact_id) DO UPDATE\"\n                            \" SET contact_name = COALESCE(NULLIF(EXCLUDED.contact_name, ''),\"\n                            \" \" + portal_db._q(portal_db.CONV_TABLE) + \".contact_name),\"\n                            \" updated_at = NOW()\"\n                            \" RETURNING (xmax = 0) AS created\",\n                            (principal[\"client_id\"], phone + \"@c.us\", name),\n                        )\n                        outcome = portal_db.rows(cur)\n                        if outcome and outcome[0].get(\"created\"):\n                            created += 1\n                        else:\n                            merged += 1\n                    portal_db.log_action(\n                        cur,\n                        principal[\"client_id\"],\n                        \"customers.imported\",\n                        \"customer_user\",\n                        principal.get(\"user_id\"),\n                        None,\n                        \"CSV import: \" + str(created) + \" new, \"\n                        + str(merged) + \" merged, \"\n                        + str(len(invalid)) + \" invalid.\",\n                    )\n                conn.commit()\n            finally:\n                conn.close()\n        except Exception as error:\n            return jsonify(portal_db.portal_unavailable(error, \"customers import\")[0]), 503\n    return jsonify({\"created\": created, \"merged\": merged,\n                    \"invalid\": invalid[:20], \"invalid_count\": len(invalid)}), 200\n\n\n@bp.get(\"/customers/export\")\ndef export_customers_csv():\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT c.contact_id,\"\n                    \" COALESCE(MAX(c.contact_name), '') AS name,\"\n                    \" COUNT(*) AS conversations,\"\n                    \" COUNT(*) FILTER (WHERE c.status = 'open') AS open_count,\"\n                    \" COALESCE(BOOL_OR(c.lead_temp = 'hot'), FALSE) AS has_hot,\"\n                    \" MAX(c.last_message_at) AS last_message_at\"\n                    \" FROM \" + portal_db._q(portal_db.CONV_TABLE) + \" c\"\n                    \" WHERE c.client_id = %s\"\n                    \" GROUP BY c.contact_id\"\n                    \" ORDER BY MAX(c.last_message_at) DESC NULLS LAST, c.contact_id\"\n                    \" LIMIT 2000\",\n                    (principal[\"client_id\"],),\n                )\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"customers export\")[0]), 503\n    buffer = io.StringIO()\n    writer = csv.writer(buffer)\n    writer.writerow([\"contact_id\", \"name\", \"conversations\", \"open_chats\",\n                     \"hot_lead\", \"last_message_at\"])\n    for row in found:\n        writer.writerow([\n            row.get(\"contact_id\"),\n            row.get(\"name\"),\n            row.get(\"conversations\"),\n            row.get(\"open_count\"),\n            \"yes\" if row.get(\"has_hot\") else \"no\",\n            row.get(\"last_message_at\").isoformat() if row.get(\"last_message_at\") else \"\",\n        ])\n    return Response(\n        buffer.getvalue(),\n        mimetype=\"text/csv\",\n        headers={\"Content-Disposition\": \"attachment; filename=omniflow-customers.csv\"},\n    )\n\n\n@bp.get(\"/customers\")\ndef list_customers():\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    search = (request.args.get(\"q\") or \"\").strip()[:100]\n    channel_filter = (request.args.get(\"channel\") or \"\").strip().lower()\n\n    sql = (\n        \"SELECT c.contact_id,\"\n        \" COALESCE(MAX(c.contact_name), '') AS contact_name,\"\n        \" COUNT(*) AS conversation_count,\"\n        \" COUNT(*) FILTER (WHERE c.status = 'open') AS open_count,\"\n        \" MAX(c.last_message_at) AS last_message_at,\"\n        \" MAX(c.last_message_preview) AS last_message_preview,\"\n        \" STRING_AGG(DISTINCT c.channel, ',') AS channels,\"\n        \" BOOL_OR(c.lead_temp = 'hot') AS has_hot,\"\n        \" MAX(c.lead_score) AS max_lead_score\"\n        \" FROM \" + portal_db._q(portal_db.CONV_TABLE) + \" c\"\n        \" WHERE c.client_id = %s\"\n    )\n    params = [principal[\"client_id\"]]\n    if channel_filter in (\"whatsapp\", \"website\"):\n        sql += \" AND c.channel = %s\"\n        params.append(channel_filter)\n    if search:\n        like = \"%\" + search.replace(\"\\\\\\\\\", \"\\\\\\\\\\\\\\\\\").replace(\"%\", \"\\\\\\\\%\").replace(\"_\", \"\\\\\\\\_\") + \"%\"\n        sql += (\n            \" GROUP BY c.contact_id\"\n            \" HAVING (COALESCE(MAX(c.contact_name), '') ILIKE %s\"\n            \" OR c.contact_id ILIKE %s)\"\n        )\n        params.extend([like, like])\n    else:\n        sql += \" GROUP BY c.contact_id\"\n    sql += (\n        \" ORDER BY MAX(c.last_message_at) DESC NULLS LAST, c.contact_id\"\n        \" LIMIT %s\"\n    )\n    params.append(CUSTOMERS_LIMIT)\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(sql, tuple(params))\n                found = portal_db.rows(cur)\n                contact_ids = [row.get(\"contact_id\") for row in found]\n                tags_map = {}\n                if contact_ids:\n                    cur.execute(\n                        \"SELECT conv.contact_id, ct.tag FROM \"\n                        + portal_db._q(portal_db.CONV_TAGS_TABLE) + \" ct\"\n                        \" JOIN \" + portal_db._q(portal_db.CONV_TABLE) + \" conv\"\n                        \" ON conv.id = ct.conversation_id\"\n                        \" WHERE ct.client_id = %s AND conv.client_id = %s\"\n                        \" AND conv.contact_id = ANY(%s) ORDER BY ct.id\",\n                        (principal[\"client_id\"], principal[\"client_id\"],\n                         contact_ids),\n                    )\n                    for row in portal_db.rows(cur):\n                        key = row.get(\"contact_id\")\n                        tag = str(row.get(\"tag\") or \"\")\n                        if key is None or not tag:\n                            continue\n                        bucket = tags_map.setdefault(key, [])\n                        if tag not in bucket:\n                            bucket.append(tag)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"customers read\")[0]), 503\n\n    customers = []\n    for row in found:\n        max_score = int(row.get(\"max_lead_score\") or 0)\n        if row.get(\"has_hot\"):\n            lead_temp = \"hot\"\n        elif max_score >= WARM_LEAD_SCORE:\n            lead_temp = \"warm\"\n        else:\n            lead_temp = \"cold\"\n        customers.append({\n            \"contact_id\": row.get(\"contact_id\"),\n            \"name\": str(row.get(\"contact_name\") or \"\"),\n            \"channels\": [\n                part for part in str(row.get(\"channels\") or \"\").split(\",\") if part\n            ],\n            \"conversation_count\": int(row.get(\"conversation_count\") or 0),\n            \"open_count\": int(row.get(\"open_count\") or 0),\n            \"last_message_at\": _iso(row.get(\"last_message_at\")),\n            \"last_message_preview\": row.get(\"last_message_preview\"),\n            \"lead_temp\": lead_temp,\n            \"tags\": tags_map.get(row.get(\"contact_id\"), []),\n        })\n    return jsonify({\"customers\": customers}), 200\n\n\ndef _profile_table_exists(cur, table: str) -> bool:\n    \"\"\"True when an optional module table exists (cod requests, sequences).\"\"\"\n    cur.execute(\"SELECT to_regclass(%s) AS oid\", (table,))\n    rows = portal_db.rows(cur)\n    return bool(rows and rows[0].get(\"oid\"))\n\n\nASSIST_STOPWORDS = frozenset((\n    \"the\", \"and\", \"you\", \"your\", \"with\", \"for\", \"from\", \"this\", \"that\",\n    \"have\", \"can\", \"are\", \"was\", \"were\", \"will\", \"would\", \"what\", \"when\",\n    \"where\", \"how\", \"does\", \"did\", \"please\", \"hey\", \"hi\", \"hello\", \"salam\",\n))\n\n\ndef _assist_tokens(text) -> set:\n    return set(re.findall(r\"[a-z0-9]{3,}\", str(text or \"\").lower())) - ASSIST_STOPWORDS\n\n\n@bp.get(\"/conversations/<int:conversation_id>/assist\")\ndef conversation_assist(conversation_id: int):\n    \"\"\"Agent assist v0: deterministic reply suggestions from the knowledge\n    base (keyword overlap), plus intent / language / linked-contact hints.\"\"\"\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    import portal_insights\n    import portal_kb\n\n    contact = None\n    inbound: list = []\n    kb_rows: list = []\n    lang_rows: list = []\n    identity_rows: list = []\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT contact_id FROM \" + portal_db._q(portal_db.CONV_TABLE) +\n                    \" WHERE id = %s AND client_id = %s\",\n                    (conversation_id, principal[\"client_id\"]),\n                )\n                found = portal_db.rows(cur)\n                if not found:\n                    return jsonify({\"error\": {\"code\": \"not_found\",\n                                              \"message\": \"Conversation not\"\n                                                         \" found.\"}}), 404\n                contact = str(found[0].get(\"contact_id\") or \"\")\n                cur.execute(\n                    \"SELECT body FROM \" + portal_db._q(portal_db.MSGS_TABLE) +\n                    \" WHERE conversation_id = %s AND client_id = %s\"\n                    \" AND direction = 'in' AND COALESCE(body, '') <> ''\"\n                    \" ORDER BY id DESC LIMIT 3\",\n                    (conversation_id, principal[\"client_id\"]),\n                )\n                inbound = portal_db.rows(cur)\n                if _profile_table_exists(cur, portal_kb.KB_TABLE):\n                    cur.execute(\n                        \"SELECT id, question, answer FROM \" +\n                        portal_db._q(portal_kb.KB_TABLE) +\n                        \" WHERE client_id = %s ORDER BY id DESC LIMIT 200\",\n                        (principal[\"client_id\"],),\n                    )\n                    kb_rows = portal_db.rows(cur)\n                if _profile_table_exists(cur, \"portal_contact_lang\"):\n                    cur.execute(\n                        \"SELECT lang FROM \" + portal_db._q(\"portal_contact_lang\") +\n                        \" WHERE client_id = %s AND contact_id = %s\",\n                        (principal[\"client_id\"], contact),\n                    )\n                    lang_rows = portal_db.rows(cur)\n                if _profile_table_exists(cur, \"portal_contact_identities\"):\n                    cur.execute(\n                        \"SELECT DISTINCT contact_id FROM \" +\n                        portal_db._q(\"portal_contact_identities\") +\n                        \" WHERE client_id = %s AND identity_key IN\"\n                        \" (SELECT identity_key FROM \" +\n                        portal_db._q(\"portal_contact_identities\") +\n                        \" WHERE client_id = %s AND contact_id = %s)\"\n                        \" ORDER BY contact_id\",\n                        (principal[\"client_id\"], principal[\"client_id\"], contact),\n                    )\n                    identity_rows = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"agent assist\")[0]), 503\n    text = \" \".join(str(row.get(\"body\") or \"\") for row in reversed(inbound))\n    tokens = _assist_tokens(text)\n    suggestions = []\n    for row in kb_rows:\n        q_tokens = _assist_tokens(str(row.get(\"question\") or \"\"))\n        overlap = tokens & q_tokens\n        if not overlap:\n            continue\n        suggestions.append({\n            \"id\": int(row.get(\"id\") or 0),\n            \"question\": str(row.get(\"question\") or \"\"),\n            \"snippet\": str(row.get(\"answer\") or \"\")[:160],\n            \"matched\": sorted(overlap)[:5],\n            \"score\": len(overlap),\n        })\n    suggestions.sort(key=lambda item: (-item[\"score\"], item[\"id\"]))\n    suggestions = suggestions[:2]\n    language = lang_rows[0].get(\"lang\") if lang_rows else None\n    linked = [str(row.get(\"contact_id\") or \"\") for row in identity_rows\n              if str(row.get(\"contact_id\") or \"\")\n              and str(row.get(\"contact_id\") or \"\") != contact]\n    return jsonify({\n        \"intent\": portal_insights.classify_intent(text[:1000]),\n        \"sentiment\": portal_insights.analyze_sentiment_smart(text[:1000]),\n        \"language\": language,\n        \"linked\": linked,\n        \"suggestions\": suggestions,\n        \"based_on\": text[:120],\n    }), 200\n\n\n@bp.get(\"/customers/profile\")\ndef customer_profile():\n    \"\"\"Everything the business knows about ONE customer, in one response.\"\"\"\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    import portal_cod\n    import portal_sequences\n\n    contact = (request.args.get(\"contact\") or \"\").strip()[:100]\n    if not contact:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"contact is required.\"}}), 400\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT COUNT(*) AS chats,\"\n                    \" COUNT(*) FILTER (WHERE status = 'open') AS open_chats,\"\n                    \" COALESCE(MAX(contact_name), '') AS name,\"\n                    \" BOOL_OR(lead_temp = 'hot') AS has_hot,\"\n                    \" MAX(lead_score) AS max_lead_score,\"\n                    \" MIN(created_at) AS first_at,\"\n                    \" MAX(last_message_at) AS last_at\"\n                    \" FROM \" + portal_db._q(portal_db.CONV_TABLE) +\n                    \" WHERE client_id = %s AND contact_id = %s\",\n                    (principal[\"client_id\"], contact),\n                )\n                summary_rows = portal_db.rows(cur)\n                summary = summary_rows[0] if summary_rows else {}\n                cur.execute(\n                    \"SELECT id, status, channel, created_at, last_message_at\"\n                    \" FROM \" + portal_db._q(portal_db.CONV_TABLE) +\n                    \" WHERE client_id = %s AND contact_id = %s\"\n                    \" ORDER BY last_message_at DESC NULLS LAST, id DESC LIMIT 20\",\n                    (principal[\"client_id\"], contact),\n                )\n                conversations = portal_db.rows(cur)\n                cur.execute(\n                    \"SELECT DISTINCT ct.tag FROM \"\n                    + portal_db._q(portal_db.CONV_TAGS_TABLE) + \" ct\"\n                    \" JOIN \" + portal_db._q(portal_db.CONV_TABLE) + \" conv\"\n                    \" ON conv.id = ct.conversation_id\"\n                    \" WHERE ct.client_id = %s AND conv.client_id = %s\"\n                    \" AND conv.contact_id = %s ORDER BY ct.tag\",\n                    (principal[\"client_id\"], principal[\"client_id\"], contact),\n                )\n                tags = [str(row.get(\"tag\") or \"\") for row in portal_db.rows(cur)\n                        if row.get(\"tag\")]\n                cod_requests = []\n                if _profile_table_exists(cur, portal_cod.COD_REQUESTS_TABLE):\n                    cur.execute(\n                        \"SELECT id, status, created_at, answered_at FROM \"\n                        + portal_db._q(portal_cod.COD_REQUESTS_TABLE) +\n                        \" WHERE client_id = %s AND contact_id = %s\"\n                        \" ORDER BY id DESC LIMIT 10\",\n                        (principal[\"client_id\"], contact),\n                    )\n                    cod_requests = portal_db.rows(cur)\n                sequence_items = []\n                if _profile_table_exists(cur, portal_sequences.SEQUENCES_TABLE):\n                    cur.execute(\n                        \"SELECT s.name AS name, e.status AS status,\"\n                        \" e.current_step AS current_step, e.enrolled_at AS enrolled_at\"\n                        \" FROM \" + portal_db._q(portal_sequences.ENROLLMENTS_TABLE) +\n                        \" e JOIN \" + portal_db._q(portal_sequences.SEQUENCES_TABLE) +\n                        \" s ON s.id = e.sequence_id\"\n                        \" WHERE e.client_id = %s AND e.contact_id = %s\"\n                        \" ORDER BY e.id DESC LIMIT 10\",\n                        (principal[\"client_id\"], contact),\n                    )\n                    sequence_items = portal_db.rows(cur)\n                cur.execute(\n                    \"SELECT n.body, n.author_email, n.created_at FROM \"\n                    + portal_db._q(portal_db.NOTES_TABLE) + \" n\"\n                    \" JOIN \" + portal_db._q(portal_db.CONV_TABLE) + \" conv\"\n                    \" ON conv.id = n.conversation_id\"\n                    \" WHERE n.client_id = %s AND conv.client_id = %s\"\n                    \" AND conv.contact_id = %s\"\n                    \" ORDER BY n.id DESC LIMIT 10\",\n                    (principal[\"client_id\"], principal[\"client_id\"], contact),\n                )\n                notes = portal_db.rows(cur)\n                if _profile_table_exists(cur, \"portal_contact_lang\"):\n                    cur.execute(\n                        \"SELECT lang FROM \" + portal_db._q(\"portal_contact_lang\") +\n                        \" WHERE client_id = %s AND contact_id = %s\",\n                        (principal[\"client_id\"], contact),\n                    )\n                    lang_rows = portal_db.rows(cur)\n                else:\n                    lang_rows = []\n                if _profile_table_exists(cur, \"portal_contact_identities\"):\n                    cur.execute(\n                        \"SELECT DISTINCT contact_id FROM \"\n                        + portal_db._q(\"portal_contact_identities\") +\n                        \" WHERE client_id = %s AND identity_key IN\"\n                        \" (SELECT identity_key FROM \"\n                        + portal_db._q(\"portal_contact_identities\") +\n                        \" WHERE client_id = %s AND contact_id = %s)\"\n                        \" ORDER BY contact_id\",\n                        (principal[\"client_id\"], principal[\"client_id\"], contact),\n                    )\n                    identity_rows = portal_db.rows(cur)\n                else:\n                    identity_rows = []\n                if _profile_table_exists(cur, \"portal_action_requests\"):\n                    cur.execute(\n                        \"SELECT id, kind, status, note, created_at FROM \"\n                        + portal_db._q(\"portal_action_requests\") +\n                        \" WHERE client_id = %s AND contact_id = %s\"\n                        \" ORDER BY id DESC LIMIT 5\",\n                        (principal[\"client_id\"], contact),\n                    )\n                    action_rows = portal_db.rows(cur)\n                else:\n                    action_rows = []\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"customer profile\")[0]), 503\n    max_score = int(summary.get(\"max_lead_score\") or 0)\n    lead_temp = \"cold\"\n    if summary.get(\"has_hot\"):\n        lead_temp = \"hot\"\n    elif max_score >= WARM_LEAD_SCORE:\n        lead_temp = \"warm\"\n    return jsonify({\n        \"contact_id\": contact,\n        \"name\": str(summary.get(\"name\") or \"\"),\n        \"lead_temp\": lead_temp,\n        \"chats\": int(summary.get(\"chats\") or 0),\n        \"open_chats\": int(summary.get(\"open_chats\") or 0),\n        \"first_seen\": _iso(summary.get(\"first_at\")),\n        \"last_seen\": _iso(summary.get(\"last_at\")),\n        \"tags\": tags,\n        \"conversations\": [\n            {\n                \"id\": int(row.get(\"id\") or 0),\n                \"status\": row.get(\"status\") or \"open\",\n                \"channel\": row.get(\"channel\") or \"whatsapp\",\n                \"last_message_at\": _iso(row.get(\"last_message_at\")),\n            }\n            for row in conversations\n        ],\n        \"cod_requests\": [\n            {\n                \"id\": int(row.get(\"id\") or 0),\n                \"status\": row.get(\"status\") or \"pending\",\n                \"created_at\": _iso(row.get(\"created_at\")),\n                \"answered_at\": _iso(row.get(\"answered_at\")),\n            }\n            for row in cod_requests\n        ],\n        \"sequences\": [\n            {\n                \"name\": row.get(\"name\") or \"\",\n                \"status\": row.get(\"status\") or \"active\",\n                \"current_step\": int(row.get(\"current_step\") or 0),\n                \"enrolled_at\": _iso(row.get(\"enrolled_at\")),\n            }\n            for row in sequence_items\n        ],\n        \"notes\": [\n            {\n                \"body\": row.get(\"body\") or \"\",\n                \"author_email\": row.get(\"author_email\") or \"\",\n                \"created_at\": _iso(row.get(\"created_at\")),\n            }\n            for row in notes\n        ],\n        \"language\": (lang_rows[0].get(\"lang\") if lang_rows else None),\n        \"linked_channels\": [\n            str(row.get(\"contact_id\") or \"\")\n            for row in identity_rows\n            if str(row.get(\"contact_id\") or \"\")\n            and str(row.get(\"contact_id\") or \"\") != contact\n        ],\n        \"actions\": [\n            {\n                \"id\": row.get(\"id\"),\n                \"kind\": row.get(\"kind\"),\n                \"status\": row.get(\"status\"),\n                \"note\": str(row.get(\"note\") or \"\"),\n                \"created_at\": _iso(row.get(\"created_at\")),\n            }\n            for row in action_rows\n        ],\n    }), 200\n\n\n\n# ---------------------------------------------------------------------------\n# Saved replies (canned response templates for the shared inbox)\n# ---------------------------------------------------------------------------\n\nMAX_SAVED_REPLIES = 30\nMAX_REPLY_BODY = 1000\nSHORTCUT_RE = re.compile(r\"^[a-z0-9_-]{1,24}$\")\n\n\ndef _clean_shortcut(value: Any) -> str:\n    \"\"\"Normalize a shortcut: trim, drop a leading slash, lowercase, cap 24.\"\"\"\n    if not isinstance(value, str):\n        return \"\"\n    shortcut = value.strip()\n    while shortcut.startswith(\"/\"):\n        shortcut = shortcut[1:]\n    shortcut = re.sub(r\"\\\\s+\", \"-\", shortcut.strip().lower())\n    shortcut = shortcut[:24]\n    if not SHORTCUT_RE.match(shortcut):\n        return \"\"\n    return shortcut\n\n\n@bp.get(\"/saved-replies\")\ndef list_saved_replies():\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_saved_usage_columns(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT id, shortcut, body, created_at,\"\n                    \" COALESCE(use_count, 0) AS use_count, last_used_at FROM \"\n                    + portal_db._q(portal_db.SAVED_REPLIES_TABLE) +\n                    \" WHERE client_id = %s ORDER BY id DESC LIMIT %s\",\n                    (principal[\"client_id\"], MAX_SAVED_REPLIES),\n                )\n                rows = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"saved replies read\")[0]), 503\n    return jsonify({\"replies\": [\n        {\n            \"id\": int(row.get(\"id\") or 0),\n            \"shortcut\": str(row.get(\"shortcut\") or \"\"),\n            \"body\": str(row.get(\"body\") or \"\"),\n            \"created_at\": _iso(row.get(\"created_at\")),\n            \"use_count\": int(row.get(\"use_count\") or 0),\n            \"last_used_at\": _iso(row.get(\"last_used_at\")),\n        }\n        for row in rows\n    ]}), 200\n\n\n@bp.post(\"/saved-replies\")\ndef create_saved_reply():\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    payload = request.get_json(silent=True) or {}\n    shortcut = _clean_shortcut(payload.get(\"shortcut\"))\n    if not shortcut:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"Shortcut can use letters, numbers, dashes and underscores (max 24).\"}}), 400\n    body_text = payload.get(\"body\")\n    body_text = body_text.strip() if isinstance(body_text, str) else \"\"\n    if not body_text:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"Message text is required.\"}}), 400\n    if len(body_text) > MAX_REPLY_BODY:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"Message must be 1000 characters or fewer.\"}}), 400\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT COUNT(*) AS total FROM \"\n                    + portal_db._q(portal_db.SAVED_REPLIES_TABLE) +\n                    \" WHERE client_id = %s\",\n                    (principal[\"client_id\"],),\n                )\n                counts = portal_db.rows(cur)\n                if counts and int(counts[0].get(\"total\") or 0) >= MAX_SAVED_REPLIES:\n                    return jsonify({\"error\": {\"code\": \"limit_reached\",\n                                              \"message\": \"Up to 30 saved replies per workspace.\"}}), 409\n                cur.execute(\n                    \"SELECT id FROM \" + portal_db._q(portal_db.SAVED_REPLIES_TABLE) +\n                    \" WHERE client_id = %s AND LOWER(shortcut) = LOWER(%s) LIMIT 1\",\n                    (principal[\"client_id\"], shortcut),\n                )\n                if portal_db.rows(cur):\n                    return jsonify({\"error\": {\"code\": \"duplicate\",\n                                              \"message\": \"A reply with this shortcut already exists.\"}}), 409\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(portal_db.SAVED_REPLIES_TABLE) +\n                    \" (client_id, shortcut, body, created_at)\"\n                    \" VALUES (%s, %s, %s, NOW()) RETURNING id, shortcut, body, created_at\",\n                    (principal[\"client_id\"], shortcut, body_text),\n                )\n                inserted = portal_db.rows(cur)\n                portal_db.log_action(\n                    cur,\n                    principal[\"client_id\"],\n                    \"saved_reply.created\",\n                    \"customer_user\",\n                    principal.get(\"user_id\"),\n                    None,\n                    (\"Saved reply added: /\" + shortcut)[:200],\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"saved reply create\")[0]), 503\n    created = inserted[0] if inserted else {}\n    return jsonify({\"ok\": True, \"reply\": {\n        \"id\": int(created.get(\"id\") or 0),\n        \"shortcut\": str(created.get(\"shortcut\") or shortcut),\n        \"body\": str(created.get(\"body\") or body_text),\n        \"created_at\": _iso(created.get(\"created_at\")),\n    }}), 200\n\n\n@bp.delete(\"/saved-replies/<int:reply_id>\")\ndef delete_saved_reply(reply_id: int):\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"DELETE FROM \" + portal_db._q(portal_db.SAVED_REPLIES_TABLE) +\n                    \" WHERE id = %s AND client_id = %s RETURNING shortcut\",\n                    (reply_id, principal[\"client_id\"]),\n                )\n                deleted = portal_db.rows(cur)\n                if not deleted:\n                    return jsonify({\"error\": {\"code\": \"not_found\",\n                                              \"message\": \"Saved reply not found.\"}}), 404\n                portal_db.log_action(\n                    cur,\n                    principal[\"client_id\"],\n                    \"saved_reply.deleted\",\n                    \"customer_user\",\n                    principal.get(\"user_id\"),\n                    None,\n                    (\"Saved reply deleted: /\"\n                     + str(deleted[0].get(\"shortcut\") or \"\"))[:200],\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"saved reply delete\")[0]), 503\n    return jsonify({\"ok\": True}), 200\n\n# ---------------------------------------------------------------------------\n# Saved replies v2 (editing + usage stats) and activity CSV export\n# ---------------------------------------------------------------------------\n\n_SAVED_USAGE_DDL_READY = False\n\n\ndef _ensure_saved_usage_columns(conn) -> None:\n    \"\"\"Usage columns landed in batch 281-295; older tables get them lazily.\"\"\"\n    global _SAVED_USAGE_DDL_READY\n    if _SAVED_USAGE_DDL_READY:\n        return\n    with conn.cursor() as cur:\n        cur.execute(\n            \"ALTER TABLE \" + portal_db._q(portal_db.SAVED_REPLIES_TABLE) +\n            \" ADD COLUMN IF NOT EXISTS use_count INT NOT NULL DEFAULT 0\"\n        )\n        cur.execute(\n            \"ALTER TABLE \" + portal_db._q(portal_db.SAVED_REPLIES_TABLE) +\n            \" ADD COLUMN IF NOT EXISTS last_used_at TIMESTAMPTZ\"\n        )\n    conn.commit()\n    _SAVED_USAGE_DDL_READY = True\n\n\n@bp.put(\"/saved-replies/<int:reply_id>\")\ndef update_saved_reply(reply_id: int):\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    payload = request.get_json(silent=True) or {}\n    shortcut = _clean_shortcut(payload.get(\"shortcut\"))\n    if not shortcut:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"Shortcut can use letters, numbers, dashes and underscores (max 24).\"}}), 400\n    body_text = payload.get(\"body\")\n    body_text = body_text.strip() if isinstance(body_text, str) else \"\"\n    if not body_text:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"Message text is required.\"}}), 400\n    if len(body_text) > MAX_REPLY_BODY:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"Message must be 1000 characters or fewer.\"}}), 400\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT id FROM \"\n                    + portal_db._q(portal_db.SAVED_REPLIES_TABLE) +\n                    \" WHERE client_id = %s AND LOWER(shortcut) = LOWER(%s)\"\n                    \" AND id <> %s LIMIT 1\",\n                    (principal[\"client_id\"], shortcut, reply_id),\n                )\n                if portal_db.rows(cur):\n                    return jsonify({\"error\": {\"code\": \"duplicate\",\n                                              \"message\": \"A reply with this shortcut already exists.\"}}), 409\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(portal_db.SAVED_REPLIES_TABLE) +\n                    \" SET shortcut = %s, body = %s\"\n                    \" WHERE id = %s AND client_id = %s\"\n                    \" RETURNING id, shortcut, body, created_at\",\n                    (shortcut, body_text, reply_id, principal[\"client_id\"]),\n                )\n                updated = portal_db.rows(cur)\n                if not updated:\n                    return jsonify({\"error\": {\"code\": \"not_found\",\n                                              \"message\": \"Saved reply not found.\"}}), 404\n                portal_db.log_action(\n                    cur,\n                    principal[\"client_id\"],\n                    \"saved_reply.updated\",\n                    \"customer_user\",\n                    principal.get(\"user_id\"),\n                    None,\n                    (\"Saved reply updated: /\" + shortcut)[:200],\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"saved reply update\")[0]), 503\n    row = updated[0]\n    return jsonify({\"ok\": True, \"reply\": {\n        \"id\": int(row.get(\"id\") or 0),\n        \"shortcut\": str(row.get(\"shortcut\") or shortcut),\n        \"body\": str(row.get(\"body\") or body_text),\n        \"created_at\": _iso(row.get(\"created_at\")),\n    }}), 200\n\n\n@bp.post(\"/saved-replies/<int:reply_id>/use\")\ndef use_saved_reply(reply_id: int):\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_saved_usage_columns(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(portal_db.SAVED_REPLIES_TABLE) +\n                    \" SET use_count = COALESCE(use_count, 0) + 1,\"\n                    \" last_used_at = NOW()\"\n                    \" WHERE id = %s AND client_id = %s RETURNING id\",\n                    (reply_id, principal[\"client_id\"]),\n                )\n                if not portal_db.rows(cur):\n                    return jsonify({\"error\": {\"code\": \"not_found\",\n                                              \"message\": \"Saved reply not found.\"}}), 404\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"saved reply use\")[0]), 503\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.get(\"/activity/export\")\ndef export_activity_csv():\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT id, created_at, action, actor_kind, note,\"\n                    \" conversation_id FROM \" + portal_db._q(\"portal_action_log\") +\n                    \" WHERE client_id = %s\"\n                    \" ORDER BY created_at DESC, id DESC LIMIT 2000\",\n                    (principal[\"client_id\"],),\n                )\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"activity export\")[0]), 503\n    buffer = io.StringIO()\n    writer = csv.writer(buffer)\n    writer.writerow([\"id\", \"created_at\", \"action\", \"actor\", \"note\",\n                     \"conversation_id\"])\n    for row in found:\n        created = row.get(\"created_at\")\n        conversation = row.get(\"conversation_id\")\n        writer.writerow([\n            row.get(\"id\"),\n            created.isoformat() if created else \"\",\n            row.get(\"action\"),\n            row.get(\"actor_kind\"),\n            str(row.get(\"note\") or \"\"),\n            conversation if conversation is not None else \"\",\n        ])\n    return Response(\n        buffer.getvalue(),\n        mimetype=\"text/csv\",\n        headers={\"Content-Disposition\": \"attachment; filename=omniflow-activity.csv\"},\n    )\n\n@bp.post(\"/customers/merge\")\ndef merge_customers():\n    \"\"\"Move one duplicate contact's history onto the kept contact.\"\"\"\n    principal, error = _principal_or_error()\n    if error is not None:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    payload = request.get_json(silent=True) or {}\n    keep = str(payload.get(\"keep\") or \"\").strip()[:100]\n    merge = str(payload.get(\"merge\") or \"\").strip()[:100]\n    if not keep or not merge:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"Both contacts are required.\"}}), 400\n    if keep == merge:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"Pick two different contacts.\"}}), 400\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT COUNT(*) AS total FROM \"\n                    + portal_db._q(portal_db.CONV_TABLE) +\n                    \" WHERE client_id = %s AND contact_id = %s\",\n                    (principal[\"client_id\"], merge),\n                )\n                counts = portal_db.rows(cur)\n                merge_chats = int(counts[0].get(\"total\") or 0) if counts else 0\n                if merge_chats == 0:\n                    return jsonify({\"error\": {\"code\": \"not_found\",\n                                              \"message\": \"The duplicate contact has no chats.\"}}), 404\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(portal_db.CONV_TABLE) +\n                    \" SET contact_id = %s\"\n                    \" WHERE client_id = %s AND contact_id = %s\",\n                    (keep, principal[\"client_id\"], merge),\n                )\n                stage_moved = 0\n                if _profile_table_exists(cur, \"portal_contact_stage\"):\n                    cur.execute(\n                        \"DELETE FROM \" + portal_db._q(\"portal_contact_stage\") +\n                        \" WHERE client_id = %s AND contact_id = %s\"\n                        \" AND EXISTS (SELECT 1 FROM \"\n                        + portal_db._q(\"portal_contact_stage\") + \" k\"\n                        \" WHERE k.client_id = \"\n                        + portal_db._q(\"portal_contact_stage\") + \".client_id\"\n                        \" AND k.contact_id = %s)\",\n                        (principal[\"client_id\"], merge, keep),\n                    )\n                    cur.execute(\n                        \"UPDATE \" + portal_db._q(\"portal_contact_stage\") +\n                        \" SET contact_id = %s\"\n                        \" WHERE client_id = %s AND contact_id = %s\",\n                        (keep, principal[\"client_id\"], merge),\n                    )\n                    stage_moved = 1\n                if _profile_table_exists(cur, \"portal_cod_requests\"):\n                    cur.execute(\n                        \"UPDATE \" + portal_db._q(\"portal_cod_requests\") +\n                        \" SET contact_id = %s\"\n                        \" WHERE client_id = %s AND contact_id = %s\",\n                        (keep, principal[\"client_id\"], merge),\n                    )\n                portal_db.log_action(\n                    cur,\n                    principal[\"client_id\"],\n                    \"customers.merged\",\n                    \"customer_user\",\n                    principal.get(\"user_id\"),\n                    None,\n                    (\"Merged \" + merge + \" into \" + keep\n                     + \" (\" + str(merge_chats) + \" chats moved).\")[:200],\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"customer merge\")[0]), 503\n    return jsonify({\"ok\": True, \"moved\": merge_chats}), 200\n");

writeNewRepair("tools/cp-testrig/portal_db.py", "(%s, %s, %s, %s, %s, %s, NOW())\",\n        (client_id, action, actor_kind, actor_user_id, conversation_id, note),\n    )", false,
    "\"\"\"\nOmniFlow Control Plane — portal module database access (Neon PostgreSQL).\n\nOwns the seven portal tables (see migrations/008_portal_connector.sql):\n  portal_whatsapp_status     — connector-reported WhatsApp state per client\n  portal_bot_configs         — customer's AI agent configuration per client\n  portal_connector_commands  — command queue (portal -> laptop connector)\n  portal_profiles            — customer business profile (JSONB doc)\n  portal_api_keys            — customer portal API keys (ofk_..., SHA-256 stored)\n  portal_conversations       — inbound/outbound conversations per contact\n  portal_messages            — messages inside a conversation\n\nTables are created lazily and idempotently (IF NOT EXISTS) on first use, so\ndeploying this module needs NO manual migration step. The SQL file remains\navailable for explicit application in the Neon SQL editor.\n\"\"\"\n\nimport logging\nimport os\nimport threading\nfrom typing import Any, Dict, List\n\n\nlogger = logging.getLogger(\"omniflow.portal-db\")\n\nSTATUS_TABLE = os.environ.get(\"OF_WA_STATUS_TABLE\", \"portal_whatsapp_status\")\nBOT_TABLE = os.environ.get(\"OF_BOT_TABLE\", \"portal_bot_configs\")\nCMD_TABLE = os.environ.get(\"OF_CMD_TABLE\", \"portal_connector_commands\")\nPROFILE_TABLE = os.environ.get(\"OF_PROFILE_TABLE\", \"portal_profiles\")\nAPIKEY_TABLE = os.environ.get(\"OF_APIKEY_TABLE\", \"portal_api_keys\")\nCONV_TABLE = os.environ.get(\"OF_CONV_TABLE\", \"portal_conversations\")\nMSGS_TABLE = os.environ.get(\"OF_MSGS_TABLE\", \"portal_messages\")\nUSERS_TABLE = os.environ.get(\"OF_USERS_TABLE\", \"platform_users\")\nUSER_EMAIL_COL = os.environ.get(\"OF_USER_EMAIL_COL\", \"email\")\nNOTES_TABLE = os.environ.get(\"OF_NOTES_TABLE\", \"portal_conversation_notes\")\nBROADCASTS_TABLE = os.environ.get(\"OF_BROADCASTS_TABLE\", \"portal_broadcasts\")\nGAPS_TABLE = os.environ.get(\"OF_GAPS_TABLE\", \"portal_kb_gaps\")\nCSAT_TABLE = os.environ.get(\"OF_CSAT_TABLE\", \"portal_csat_requests\")\nSAVED_REPLIES_TABLE = os.environ.get(\"OF_SAVED_REPLIES_TABLE\", \"portal_saved_replies\")\n\n_ensure_lock = threading.Lock()\n_ensured = False\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_whatsapp_status (\n  client_id BIGINT PRIMARY KEY,\n  state TEXT NOT NULL DEFAULT 'disconnected',\n  phone TEXT,\n  account_name TEXT,\n  last_seen_at TIMESTAMPTZ,\n  reported_by BIGINT,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE TABLE IF NOT EXISTS portal_bot_configs (\n  client_id BIGINT PRIMARY KEY,\n  agent_name TEXT NOT NULL DEFAULT 'OmniFlow Assistant',\n  tone TEXT NOT NULL DEFAULT 'friendly',\n  greeting TEXT NOT NULL DEFAULT '',\n  fallback TEXT NOT NULL DEFAULT '',\n  working_hours_enabled BOOLEAN NOT NULL DEFAULT FALSE,\n  working_hours_start TEXT NOT NULL DEFAULT '09:00',\n  working_hours_end TEXT NOT NULL DEFAULT '18:00',\n  human_handoff_enabled BOOLEAN NOT NULL DEFAULT FALSE,\n  updated_by BIGINT,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE TABLE IF NOT EXISTS portal_connector_commands (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  channel TEXT NOT NULL DEFAULT 'whatsapp',\n  action TEXT NOT NULL,\n  payload JSONB NOT NULL DEFAULT '{}'::jsonb,\n  status TEXT NOT NULL DEFAULT 'pending',\n  requested_by BIGINT,\n  result_note TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_cmds_pending\n  ON portal_connector_commands (client_id, status, id);\nCREATE TABLE IF NOT EXISTS portal_profiles (\n  client_id BIGINT PRIMARY KEY,\n  profile JSONB NOT NULL DEFAULT '{}'::jsonb,\n  updated_by BIGINT,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE TABLE IF NOT EXISTS portal_api_keys (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  token_hash TEXT NOT NULL,\n  key_prefix TEXT NOT NULL,\n  key_last4 TEXT NOT NULL,\n  revoked_at TIMESTAMPTZ,\n  created_by BIGINT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  last_used_at TIMESTAMPTZ\n);\nCREATE INDEX IF NOT EXISTS idx_portal_api_keys_hash\n  ON portal_api_keys (token_hash);\nCREATE INDEX IF NOT EXISTS idx_portal_api_keys_client\n  ON portal_api_keys (client_id);\nCREATE TABLE IF NOT EXISTS portal_conversations (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  channel TEXT NOT NULL DEFAULT 'whatsapp',\n  contact_id TEXT NOT NULL,\n  contact_name TEXT,\n  status TEXT NOT NULL DEFAULT 'open',\n  last_message_preview TEXT,\n  last_message_at TIMESTAMPTZ,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  CONSTRAINT uq_portal_conversation UNIQUE (client_id, channel, contact_id)\n);\nCREATE INDEX IF NOT EXISTS idx_portal_conversations_list\n  ON portal_conversations (client_id, last_message_at DESC);\nCREATE TABLE IF NOT EXISTS portal_messages (\n  id BIGSERIAL PRIMARY KEY,\n  conversation_id BIGINT NOT NULL,\n  client_id BIGINT NOT NULL,\n  direction TEXT NOT NULL,\n  body TEXT NOT NULL DEFAULT '',\n  sender_name TEXT,\n  status TEXT NOT NULL DEFAULT 'received',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_messages_conv\n  ON portal_messages (conversation_id, id);\nCREATE TABLE IF NOT EXISTS portal_conversation_notes (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  conversation_id BIGINT NOT NULL,\n  author_email TEXT,\n  body TEXT NOT NULL DEFAULT '',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_conv_notes\n  ON portal_conversation_notes (conversation_id, id DESC);\nCREATE TABLE IF NOT EXISTS portal_broadcasts (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  audience TEXT NOT NULL DEFAULT 'all',\n  body TEXT NOT NULL,\n  recipient_count INT NOT NULL DEFAULT 0,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_broadcasts\n  ON portal_broadcasts (client_id, id DESC);\nCREATE TABLE IF NOT EXISTS portal_kb_gaps (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  conversation_id BIGINT NOT NULL,\n  question TEXT NOT NULL DEFAULT '',\n  intent TEXT NOT NULL DEFAULT 'general',\n  resolved INT NOT NULL DEFAULT 0,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  resolved_at TIMESTAMPTZ\n);\nCREATE INDEX IF NOT EXISTS idx_portal_kb_gaps\n  ON portal_kb_gaps (client_id, resolved, id DESC);\nCREATE TABLE IF NOT EXISTS portal_csat_requests (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  conversation_id BIGINT NOT NULL UNIQUE,\n  contact_id TEXT NOT NULL,\n  contact_name TEXT,\n  score INT,\n  requested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  answered_at TIMESTAMPTZ\n);\nCREATE INDEX IF NOT EXISTS idx_portal_csat_requests\n  ON portal_csat_requests (client_id, requested_at DESC);\n\"\"\"\n\n\ndef _q(ident: str) -> str:\n    \"\"\"Quote a dynamic identifier (config values, never user input).\"\"\"\n    return '\"' + ident.replace('\"', '\"\"') + '\"'\n\n\ndef _conn():\n    import psycopg2\n\n    return psycopg2.connect(\n        host=os.environ[\"DB_HOST\"],\n        port=int(os.environ.get(\"DB_PORT\", \"5432\")),\n        dbname=os.environ[\"DB_NAME\"],\n        user=os.environ[\"DB_USER\"],\n        password=os.environ[\"DB_PASSWORD\"],\n        sslmode=os.environ.get(\"PGSSLMODE\", \"require\"),\n        connect_timeout=15,\n    )\n\n\ndef ensure_tables() -> None:\n    \"\"\"Idempotent, runs at most once per instance on success.\"\"\"\n    global _ensured\n    if _ensured:\n        return\n    with _ensure_lock:\n        if _ensured:\n            return\n        conn = _conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(_DDL)\n            conn.commit()\n            _ensured = True\n            logger.info(\n                \"portal tables ensured (%s/%s/%s + profiles/apikeys/conversations)\",\n                STATUS_TABLE, BOT_TABLE, CMD_TABLE,\n            )\n        finally:\n            conn.close()\n\n\ndef rows(cur) -> List[Dict[str, Any]]:\n    \"\"\"Cursor rows as plain dicts keyed by column name.\n\n    Defensive: some drivers expose description=None for zero-row\n    non-SELECT statements — treat that as an empty result.\n    \"\"\"\n    if cur.description is None:\n        return []\n    cols = [d[0] for d in cur.description]\n    return [dict(zip(cols, row)) for row in cur.fetchall()]\n\n\ndef portal_unavailable(error: Exception, context: str) -> Any:\n    \"\"\"Log + return the 503 response used by every portal/connector route.\"\"\"\n    logger.exception(\"portal storage failure: %s\", context)\n    return (\n        {\"error\": {\"code\": \"portal_unavailable\",\n                   \"message\": \"Storage is temporarily unavailable, try again shortly.\"}},\n        503,\n    )\n\nTEAM_TABLE = os.environ.get(\"OF_TEAM_TABLE\", \"portal_team_members\")\nCONV_TAGS_TABLE = os.environ.get(\"OF_CONV_TAGS_TABLE\", \"portal_conversation_tags\")\n\n\ndef log_action(cur, client_id, action, actor_kind=\"customer_user\",\n               actor_user_id=None, conversation_id=None, note=\"\"):\n    \"\"\"Append one row to the action audit log (portal_action_log).\"\"\"\n    cur.execute(\n        \"INSERT INTO \" + _q(\"portal_action_log\") +\n        \" (client_id, action, actor_kind, actor_user_id, conversation_id,\"\n        \" note, created_at) VALUES (%s, %s, %s, %s, %s, %s, NOW())\",\n        (client_id, action, actor_kind, actor_user_id, conversation_id, note),\n    )\n");

writeNewRepair("tools/cp-testrig/README.md", "lied on\ntop, and npm dependencies. Run the suites from\n`/tmp/p13/OmniFlow-Control-Plane` with `OMNIFLOW_SERVICE_KEY=x`.", false,
    "# Control Plane test rig\n\nThe agent sandbox cannot clone the private OmniFlow-Control-Plane repo, so\nthis directory keeps a faithful conversations-only reconstruction of\n`portal_conversations.py` (regions verbatim from the shipped patchers) plus\nthe DB/auth modules from `omniflow-backend-patch/` and the Flask test suites.\n\n`sh tools/cp-testrig/rebuild.sh` recreates `/tmp/p13`: the website at\norigin/main, this Control Plane base, the Phase 36-42 patchers applied on\ntop, and npm dependencies. Run the suites from\n`/tmp/p13/OmniFlow-Control-Plane` with `OMNIFLOW_SERVICE_KEY=x`.\n");

writeNewRepair("tools/cp-testrig/rebuild_cp.sh", "test_perf.py >/dev/null 2>&1 || true\necho \"CP SANDBOX READY (run the sweep: for t in test_*.py; do python3 \\$t; done)\"", false,
    "#!/bin/sh\n# Assembles the Control Plane sandbox inside /tmp/p13 on top of rebuild.sh.\n# Run AFTER tools/cp-testrig/rebuild.sh, from the website repo root:\n#   sh tools/cp-testrig/rebuild.sh && sh tools/cp-testrig/rebuild_cp.sh\n# Then apply any NEW patcher: cd /tmp/p13 && node /path/to/tools/patchers/add_batch_XXX.mjs\nset -e\ncd \"$(dirname \"$0\")/../..\"\nCP=/tmp/p13/OmniFlow-Control-Plane\n\n# Base reference copies (older era; the chain below brings them current).\ncp omniflow-backend-patch/app.py omniflow-backend-patch/connector_api.py \"$CP/\"\n\n# Modules that only exist as NEW-file sections inside patchers.\nnode --input-type=module -e '\nimport fs from \"fs\";\nfunction extract(file, decl, out) {\n  const src = fs.readFileSync(file, \"utf8\");\n  const start = src.indexOf(decl) + decl.length;\n  const end = src.indexOf(\"`;\", start);\n  const body = src.slice(start, end).replace(/\\\\`/g, \"`\").replace(/\\\\\\$\\{/g, \"${}\");\n  fs.writeFileSync(out, body.replace(/\\r\\n/g, \"\\n\"));\n}\nextract(\"tools/patchers/add_growth_ops.mjs\", \"const PY_MODULE = `\", \"/tmp/p13/OmniFlow-Control-Plane/portal_growth.py\");\nextract(\"tools/patchers/add_knowledge_base.mjs\", \"const MODULE_FILE = `\", \"/tmp/p13/OmniFlow-Control-Plane/portal_kb.py\");\n'\npython3 -m py_compile \"$CP/portal_growth.py\" \"$CP/portal_kb.py\"\n\n# The rig portal_conversations.py predates the customers section: append it.\nnode --input-type=module -e '\nimport fs from \"fs\";\nconst src = fs.readFileSync(\"tools/patchers/add_customers_page.mjs\", \"utf8\");\nconst start = src.indexOf(\"const CP_CUSTOMERS_APPEND = `\") + \"const CP_CUSTOMERS_APPEND = `\".length;\nconst end = src.indexOf(\"`;\", start);\nconst append = src.slice(start, end).replace(/\\\\`/g, \"`\").replace(/\\\\\\$\\{/g, \"${}\");\nconst p = \"/tmp/p13/OmniFlow-Control-Plane/portal_conversations.py\";\nlet body = fs.readFileSync(p, \"utf8\").replace(/\\r\\n/g, \"\\n\");\nif (!body.includes(\"customers/import\")) {\n  fs.writeFileSync(p, body + \"\\n\\n\" + append.replace(/\\r\\n/g, \"\\n\") + \"\\n\");\n}\n'\n\n# Early-era saved replies: the rig reconstruction predates the section, and\n# batch 281-295 upgrades it (edit + usage stats), so the base must exist.\nnode --input-type=module -e '\nimport fs from \"fs\";\nconst src = fs.readFileSync(\"tools/patchers/add_saved_replies.mjs\", \"utf8\");\nconst start = src.indexOf(\"const CP_SAVED_REPLIES_APPEND = `\") + \"const CP_SAVED_REPLIES_APPEND = `\".length;\nconst end = src.indexOf(\"`;\", start);\nconst append = src.slice(start, end).replace(/\\\\`/g, \"`\").replace(/\\\\\\$\\{/g, \"${}\");\nconst p = \"/tmp/p13/OmniFlow-Control-Plane/portal_conversations.py\";\nlet body = fs.readFileSync(p, \"utf8\").replace(/\\r\\n/g, \"\\n\");\nif (!/^import re$/m.test(body)) {\n  body = body.replace(/^import io$/m, \"import io\\nimport re\");\n}\nif (!body.includes(\"saved-replies\")) {\n  fs.writeFileSync(p, body + append.replace(/\\r\\n/g, \"\\n\") + \"\\n\");\n}\n'\n\n# Rig portal_db.py predates the growth-era constants and lazy DDL.\npython3 - <<'PYEOF'\np = \"/tmp/p13/OmniFlow-Control-Plane/portal_db.py\"\ns = open(p).read()\nif \"BROADCASTS_TABLE\" not in s:\n    s = s.replace('USER_EMAIL_COL = os.environ.get(\"OF_USER_EMAIL_COL\", \"email\")',\n'''USER_EMAIL_COL = os.environ.get(\"OF_USER_EMAIL_COL\", \"email\")\nNOTES_TABLE = os.environ.get(\"OF_NOTES_TABLE\", \"portal_conversation_notes\")\nBROADCASTS_TABLE = os.environ.get(\"OF_BROADCASTS_TABLE\", \"portal_broadcasts\")\nGAPS_TABLE = os.environ.get(\"OF_GAPS_TABLE\", \"portal_kb_gaps\")\nCSAT_TABLE = os.environ.get(\"OF_CSAT_TABLE\", \"portal_csat_requests\")\nSAVED_REPLIES_TABLE = os.environ.get(\"OF_SAVED_REPLIES_TABLE\", \"portal_saved_replies\")''')\n    ddl_anchor = '''CREATE INDEX IF NOT EXISTS idx_portal_messages_conv\n  ON portal_messages (conversation_id, id);\n\"\"\"'''\n    ddl_new = '''CREATE INDEX IF NOT EXISTS idx_portal_messages_conv\n  ON portal_messages (conversation_id, id);\nCREATE TABLE IF NOT EXISTS portal_conversation_notes (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  conversation_id BIGINT NOT NULL,\n  author_email TEXT,\n  body TEXT NOT NULL DEFAULT '',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_conv_notes\n  ON portal_conversation_notes (conversation_id, id DESC);\nCREATE TABLE IF NOT EXISTS portal_broadcasts (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  audience TEXT NOT NULL DEFAULT 'all',\n  body TEXT NOT NULL,\n  recipient_count INT NOT NULL DEFAULT 0,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_broadcasts\n  ON portal_broadcasts (client_id, id DESC);\nCREATE TABLE IF NOT EXISTS portal_kb_gaps (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  conversation_id BIGINT NOT NULL,\n  question TEXT NOT NULL DEFAULT '',\n  intent TEXT NOT NULL DEFAULT 'general',\n  resolved INT NOT NULL DEFAULT 0,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  resolved_at TIMESTAMPTZ\n);\nCREATE INDEX IF NOT EXISTS idx_portal_kb_gaps\n  ON portal_kb_gaps (client_id, resolved, id DESC);\nCREATE TABLE IF NOT EXISTS portal_csat_requests (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  conversation_id BIGINT NOT NULL UNIQUE,\n  contact_id TEXT NOT NULL,\n  contact_name TEXT,\n  score INT,\n  requested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  answered_at TIMESTAMPTZ\n);\nCREATE INDEX IF NOT EXISTS idx_portal_csat_requests\n  ON portal_csat_requests (client_id, requested_at DESC);\n\"\"\"'''\n    assert ddl_anchor in s\n    s = s.replace(ddl_anchor, ddl_new)\n    open(p, \"w\").write(s)\n    print(\"portal_db consts + DDL added\")\nPYEOF\n\n# The reference app.py predates the growth registration the chain anchors on.\npython3 - <<'PYEOF'\np = \"/tmp/p13/OmniFlow-Control-Plane/app.py\"\ns = open(p).read()\nif \"portal_growth_bp\" not in s:\n    s = s.replace(\n        \"from portal_conversations import bp as portal_conversations_bp  # noqa: E402\",\n        \"from portal_conversations import bp as portal_conversations_bp  # noqa: E402\\nfrom portal_growth import bp as portal_growth_bp  # noqa: E402\")\n    s = s.replace(\n        \"aux_app.register_blueprint(portal_conversations_bp)\",\n        \"aux_app.register_blueprint(portal_conversations_bp)\\naux_app.register_blueprint(portal_growth_bp)\")\n    open(p, \"w\").write(s)\n    print(\"app.py growth lines added\")\nPYEOF\npython3 -m py_compile \"$CP/app.py\" \"$CP/portal_db.py\" \"$CP/portal_conversations.py\"\n\n# Laptop bridge simulation (only its shape is asserted by the tests).\nmkdir -p /tmp/p13/src\ncat > /tmp/p13/src/control_plane_bridge.py <<'EOF'\n\"\"\"Laptop bridge simulation: polls the control plane and drives WhatsApp.\"\"\"\n\nfrom prefect_gmail_types import OutboundMessage\n\n\nclass ControlPlaneBridge:\n    def process_due_followups(self, adapter):\n        pass\n\n    def process_due_away(self, adapter):\n        for away_id, note in self.due_away:\n            self.send_outbound(adapter, note)\n            self.acknowledge_away(away_id, success, note)\n\n    def send_outbound(self, adapter, to, body):\n        message = OutboundMessage(to=to, body=body)\n        adapter.send(message)\n        self.ingest_outbound(message)\n\n    def ingest_outbound(self, message):\n        self.store.append(direction=\"out\", body=message.body)\n\n    def acknowledge_away(self, away_id, success, note):\n        pass\n\n    def acknowledge_followup(self, followup_id, success, note):\n        pass\n\n    def run_due_commands(\n        self,\n    ):\n        pass\n\n    def poll_once(self, adapter):\n        self.process_due_followups(adapter)\n        self.process_due_away(adapter)\n        self.run_due_commands(adapter)\nEOF\n\n# Era chain: each patcher is idempotent, run them all in delivery order.\ncd /tmp/p13\nfor b in add_batch_101_105 add_batch_111_114 add_batch_115_116 \\\n         add_batch_121_125 add_batch_126_130 add_batch_136_140 \\\n         add_batch_141_145 add_batch_146_150 add_batch_151_155; do\n  echo \"== $b\"\n  node /home/user/Omniflow/$b.mjs 2>&1 | tail -1\ndone\nif [ -f /home/user/Omniflow/add_batch_156_160.mjs ]; then\n  echo \"== add_batch_156_160\"\n  node /home/user/Omniflow/add_batch_156_160.mjs 2>&1 | tail -1\nfi\n\ncd /tmp/p13/OmniFlow-Control-Plane\nexport OMNIFLOW_SERVICE_KEY=x\npython3 test_perf.py >/dev/null 2>&1 || true\necho \"CP SANDBOX READY (run the sweep: for t in test_*.py; do python3 \\$t; done)\"\n");

writeNewRepair("tools/cp-testrig/rebuild.sh", "Website build deps.\ncd /tmp/p13/Omniflow\nnpm ci --silent\nnpm i --no-save esbuild@0.25.10 --silent\necho \"SANDBOX READY\"", false,
    "#!/bin/sh\n# Rebuilds the /tmp/p13 sandbox from the persisted test rig.\n# Usage: sh tools/cp-testrig/rebuild.sh   (from the website repo root)\nset -e\ncd \"$(dirname \"$0\")/../..\"\nrm -rf /tmp/p13\nmkdir -p /tmp/p13/OmniFlow-Control-Plane /tmp/p13/Omniflow\n\n# Website: the last state pushed from the laptop (through Phase 35).\ngit archive origin/main | tar -x -C /tmp/p13/Omniflow\n\n# Control Plane: the conversations-region reconstruction (base through Phase 35).\ncp tools/cp-testrig/portal_conversations.py \\\n   tools/cp-testrig/portal_db.py \\\n   tools/cp-testrig/portal_auth.py \\\n   tools/cp-testrig/test_*.py /tmp/p13/OmniFlow-Control-Plane/\ncp tools/cp-testrig/cp_gitignore /tmp/p13/OmniFlow-Control-Plane/.gitignore\n\n# The website archive already carries every phase pushed from the laptop and\n# the rig portal_conversations.py is baked through Phase 46, so no patchers\n# run here. Future batches: apply their patchers manually after this script.\n\n# Python test deps (sandbox wipes them on every rebuild).\npip install --break-system-packages --quiet flask psycopg2-binary 2>/dev/null ||   pip install --quiet flask psycopg2-binary\n\n# Website build deps.\ncd /tmp/p13/Omniflow\nnpm ci --silent\nnpm i --no-save esbuild@0.25.10 --silent\necho \"SANDBOX READY\"\n");

writeNewRepair("tools/cp-testrig/smoke971.sh", "\"$A/courier/track/route.ts\"           \"$S/bff_courier_track.ts\"\n\necho \"smoke971 repopulated: $(ls \"$S\" | wc -l) files\"", false,
    "#!/bin/sh\n# Repopulates the /tmp/smoke971 era-snapshot the rig pins read from.\n# The pins assert \"the deployed file contains X\" - the deployed era is\n# the current workspace tree, so every snapshot copy is simply the\n# current source file. Run from the website repo root after a sandbox\n# wipe:   sh tools/cp-testrig/smoke971.sh\nset -e\ncd \"$(dirname \"$0\")/../..\"\nS=/tmp/smoke971\nW=app/dashboard/\\(portal\\)\nrm -rf \"$S\"\nmkdir -p \"$S\"\n\n# Control Plane modules (era = omniflow-backend-patch).\nfor f in app.py connector_api.py portal_changes.py portal_checkout.py \\\n         portal_cod.py portal_coupons.py portal_events.py portal_intents.py \\\n         portal_kb.py portal_llm.py portal_payments.py portal_ratelimit.py; do\n  cp \"omniflow-backend-patch/$f\" \"$S/$f\"\ndone\n\n# Dashboard pages + cards (era = current workspace tree).\ncp app/dashboard/components/DashSidebar.tsx            \"$S/sidebar.tsx\"\ncp app/dashboard/components/CommandPalette.tsx         \"$S/palette.tsx\"\ncp app/dashboard/components/RecoveryCard.tsx           \"$S/recovery_card.tsx\"\ncp \"$W/page.tsx\"                                       \"$S/overview_page.tsx\"\ncp \"$W/settings/page.tsx\"                              \"$S/settings_page.tsx\"\ncp \"$W/courier/page.tsx\"                               \"$S/courier_page.tsx\"\ncp \"$W/media/page.tsx\"                                 \"$S/media_page.tsx\"\ncp \"$W/broadcasts/page.tsx\"                            \"$S/broadcasts_page.tsx\"\ncp \"$W/cod/page.tsx\"                                   \"$S/cod_page.tsx\"\ncp \"$W/cod/RiskCard.tsx\"                               \"$S/risk_card.tsx\"\ncp \"$W/cod/AddressCard.tsx\"                            \"$S/address_card.tsx\"\ncp \"$W/broadcasts/CopyGenCard.tsx\"                     \"$S/copygen_card.tsx\"\ncp \"$W/settings/NegotiationCard.tsx\"                   \"$S/negotiation_card.tsx\"\ncp \"$W/settings/PerfCard.tsx\"                          \"$S/perf_card.tsx\"\ncp \"$W/customers/profile/CustomerMemoryCard.tsx\"       \"$S/memory_card.tsx\"\ncp \"$W/customers/profile/CustomerJourneyCard.tsx\"      \"$S/journey_card.tsx\"\ncp \"$W/customers/profile/ProfileClient.tsx\"            \"$S/profile_client.tsx\"\n\n# BFF route snapshots (the rig's bff_<name>.ts pins).\nA=app/api/omniflow/portal\ncp \"$A/perf/route.ts\"                    \"$S/bff_perf.ts\"\ncp \"$A/media/route.ts\"                   \"$S/bff_media.ts\"\ncp \"$A/media/delete/route.ts\"            \"$S/bff_media_delete.ts\"\ncp \"$A/media/send/route.ts\"              \"$S/bff_media_send.ts\"\ncp \"$A/media/transcribe/route.ts\"        \"$S/bff_media_transcribe.ts\"\ncp \"$A/memory/route.ts\"                  \"$S/bff_memory.ts\"\ncp \"$A/memory/[id]/route.ts\"             \"$S/bff_id_memory_id.ts\"\ncp \"$A/journey/route.ts\"                 \"$S/bff_journey.ts\"\ncp \"$A/journey/stages/route.ts\"          \"$S/bff_journey_stages.ts\"\ncp \"$A/journey/stages/[id]/route.ts\"     \"$S/bff_id_stage_id.ts\"\ncp \"$A/explain/route.ts\"                 \"$S/bff_explain.ts\"\ncp \"$A/media/[id]/download/route.ts\"     \"$S/bff_media_download.ts\"\ncp \"$A/recovery/route.ts\"                \"$S/bff_recovery.ts\"\ncp \"$A/recovery/followup/route.ts\"       \"$S/bff_recovery_followup.ts\"\ncp \"$A/recovery/dismiss/route.ts\"        \"$S/bff_recovery_dismiss.ts\"\ncp \"$A/recovery/settings/route.ts\"       \"$S/bff_recovery_settings.ts\"\ncp \"$A/negotiation/bounds/route.ts\"      \"$S/bff_negotiation_bounds.ts\"\ncp \"$A/negotiation/decide/route.ts\"      \"$S/bff_negotiation_decide.ts\"\ncp \"$A/copygen/broadcast/route.ts\"       \"$S/bff_copygen_broadcast.ts\"\ncp \"$A/risk/score/route.ts\"              \"$S/bff_risk_score.ts\"\ncp \"$A/risk/settings/route.ts\"           \"$S/bff_risk_settings.ts\"\ncp \"$A/risk/tasks/route.ts\"              \"$S/bff_risk_tasks.ts\"\ncp \"$A/address/normalize/route.ts\"       \"$S/bff_address_normalize.ts\"\ncp \"$A/courier/settings/route.ts\"        \"$S/bff_courier_settings.ts\"\ncp \"$A/courier/test/route.ts\"            \"$S/bff_courier_test.ts\"\ncp \"$A/courier/book/route.ts\"            \"$S/bff_courier_book.ts\"\ncp \"$A/courier/bookings/route.ts\"        \"$S/bff_courier_bookings.ts\"\ncp \"$A/courier/track/route.ts\"           \"$S/bff_courier_track.ts\"\n\necho \"smoke971 repopulated: $(ls \"$S\" | wc -l) files\"\n");

writeNewRepair("tools/cp-testrig/test_811_890_ui.py", "CARD)):\n    ok = all(ch not in body for ch in BAD)\n    check(\"no raw emoji \" + label, ok, label)\n\nsummary(\"811_890_ui\")", false,
    "\"\"\"UI/contract tests for batches 811-890: money guard, payment gateway,\nanalytics depth, data safety. Reads the website tree and pins clients,\nBFF depths and the new UI strings.\"\"\"\nimport os\nimport sys\n\nimport test_lib\nfrom test_lib import check, summary\n\nSITE = \"/tmp/p13/Omniflow/\"\n\n\ndef read(rel):\n    return open(SITE + rel, encoding=\"utf8\").read()\n\n\nPORTAL = read(\"lib/omniflow/portal.ts\")\nGROWTH = read(\"app/dashboard/(portal)/growth/page.tsx\")\nPUBLIC = read(\"app/c/[token]/page.tsx\")\nPAYGATE = read(\"app/c/[token]/PayGate.tsx\")\nSETTINGS = read(\"app/dashboard/(portal)/settings/page.tsx\")\nPAY_CARD = read(\"app/dashboard/(portal)/settings/PaymentsCard.tsx\")\nSAFE_CARD = read(\"app/dashboard/(portal)/settings/DataSafetyCard.tsx\")\n\nprint(\"== portal.ts clients (811-890) ==\")\nfor name in (\"getPaymentSettings\", \"savePaymentSettings\", \"getPublicPayInfo\",\n             \"fetchPublicPayHtml\", \"getCustomerAnalytics\",\n             \"getProductAnalytics\", \"getRetention\", \"saveRetention\",\n             \"runRetention\", \"fetchDataExport\"):\n    check(\"client \" + name, \"export async function \" + name in PORTAL, name)\nfor name in (\"PaymentSettings\", \"CustomerAnalyticsEntry\",\n             \"ProductAnalyticsEntry\", \"RetentionSettings\"):\n    check(\"type \" + name, (\"export interface \" + name in PORTAL)\n          or (\"export type \" + name in PORTAL), name)\ncheck(\"advance forbidden status\", 'if (response.status === 403) return \"forbidden\";'\n      in PORTAL, \"403 map\")\ncheck(\"advance union forbidden\", '| \"forbidden\"' in PORTAL, \"union\")\n\nprint(\"== BFF depths ==\")\nBFF6 = [\n    \"app/api/omniflow/portal/payments/settings/route.ts\",\n    \"app/api/omniflow/portal/insights/customer-analytics/route.ts\",\n    \"app/api/omniflow/portal/insights/product-analytics/route.ts\",\n    \"app/api/omniflow/portal/data/retention/route.ts\",\n    \"app/api/omniflow/portal/data/export/route.ts\",\n]\nfor rel in BFF6:\n    body = read(rel)\n    check(\"bff 6-up \" + rel.rsplit(\"/\", 2)[-2], \"../../../../../../lib/\" in body, rel)\nPAY_STREAM = read(\"app/api/omniflow/public/checkout/[token]/pay/route.ts\")\ncheck(\"pay stream 7-up\", \"../../../../../../../lib/\" in PAY_STREAM, \"pay\")\nRUN_ROUTE = read(\"app/api/omniflow/portal/data/retention/run/route.ts\")\ncheck(\"run route 7-up\", \"../../../../../../../lib/\" in RUN_ROUTE, \"run\")\n\nprint(\"== page pins ==\")\ncheck(\"growth insights card\", 'title=\"Customer insights\"' in GROWTH, \"card\")\ncheck(\"growth products card\", 'title=\"Top products\"' in GROWTH, \"card\")\ncheck(\"growth advance note\", \"advanceNote\" in GROWTH, \"note\")\ncheck(\"public pay button\",\n      \"/api/omniflow/public/checkout/\" in PAYGATE\n      and \"online\" in PAYGATE, \"button\")\ncheck(\"settings payments card\", 'import PaymentsCard from \"./PaymentsCard\";'\n      in SETTINGS and \"PaymentsCard\" in SETTINGS, \"card\")\ncheck(\"settings datasafety card\",\n      'import DataSafetyCard from \"./DataSafetyCard\";' in SETTINGS\n      and \"DataSafetyCard\" in SETTINGS, \"card\")\ncheck(\"pay card configured readout\", \"Configured\" in PAY_CARD, \"mask\")\ncheck(\"safe card download\", \"Download backup (JSON)\" in SAFE_CARD, \"export\")\n\nprint(\"== icon law (text-presentation only) ==\")\nBAD = [\"\\u260e\", \"\\u2733\", \"\\u2709\", \"\\u263a\", \"\\u26a1\", \"\\u2696\"]\nfor label, body in ((\"portal\", PORTAL), (\"growth\", GROWTH),\n                    (\"public\", PUBLIC), (\"settings\", SETTINGS),\n                    (\"paycard\", PAY_CARD), (\"safecard\", SAFE_CARD)):\n    ok = all(ch not in body for ch in BAD)\n    check(\"no raw emoji \" + label, ok, label)\n\nsummary(\"811_890_ui\")\n");

writeNewRepair("tools/cp-testrig/test_actions.py", "blueprint(portal_approvals_bp)\")\n      < APP.index(\"register_blueprint(portal_actions_bp)\"), \"app\")\n\nsummary(\"actions\")", false,
    "\"\"\"Master-upgrade engine 7: the Action Engine v1.\n\nCovers portal_actions: the declared registry (risk levels, required\nargs), execute() for LOW/MEDIUM actions (direct run + audit), the\nHIGH-risk approval gate (approval created, nothing executed), the\napproval resolution loop (approved = real run + action-request done;\nrejected = customer hold message), and the portal API (catalog,\nexecute 200/400/401/503) plus the web pins (app registrations,\napprovals.decide -> resolve seam).\n\"\"\"\nimport json\n\nfrom flask import Flask\n\nimport portal_actions\nimport portal_approvals\nfrom test_lib import install_db_stub\nfrom test_lib import check, summary\nfrom test_lib import PrincipalStub\n\n\nclass Principal:\n    def __init__(self, module, principal=None, exc=None):\n        self.stub = PrincipalStub(module, principal, exc)\n\n    def __enter__(self):\n        return self\n\n    def __exit__(self, *args):\n        self.stub.restore()\n        return False\n\n\nPRINCIPAL = {\n    \"session_id\": \"s\", \"user_id\": 11, \"client_id\": 1, \"role\": \"owner\",\n    \"email\": \"ahmed@example.com\", \"display_name\": \"Ahmed\",\n    \"via_api_key\": False,\n}\n\napp = Flask(__name__)\napp.register_blueprint(portal_actions.bp)\nclient = app.test_client()\n\nCONFIG_ROW = [{\"approval_number\": \"9230012345678\",\n               \"auto_expire_hours\": 24}]\nSTATUS_ROW = [{\"phone\": \"92 300 999 8888\"}]\n\n\ndef share_stub(conn):\n    \"\"\"One FakeConn backing BOTH modules' portal_db (single slot stream).\"\"\"\n    conn = install_db_stub(portal_approvals, [])\n    portal_actions.portal_db = portal_approvals.portal_db\n    return conn\n\n\nprint(\"== registry ==\")\n\ncat = {item[\"action\"]: item for item in portal_actions.catalog()}\ncheck(\"catalog has 15 actions\", len(cat) == 15, len(cat))\ncheck(\"risks declared\",\n      cat[\"read_customer_memory\"][\"risk\"] == \"low\"\n      and cat[\"add_customer_note\"][\"risk\"] == \"medium\"\n      and cat[\"request_refund\"][\"risk\"] == \"high\", \"risk\")\ncheck(\"required args\", cat[\"create_checkout_link\"][\"required\"]\n      == [\"contact_id\", \"items\"], \"required\")\n\nprint(\"== execute: LOW/MEDIUM run directly ==\")\n\n_orig_memory = portal_actions.ACTIONS[\"read_customer_memory\"][\"run\"]\ntry:\n    portal_actions.ACTIONS[\"read_customer_memory\"][\"run\"] = (\n        lambda cur, cid, args: {\n            \"memory\": [{\"content\": \"Prefers black hoodie\"}]})\n    conn = install_db_stub(portal_actions, [\n        [],                                # audit INSERT\n    ])\n    out = portal_actions.execute(conn.cursor(), 1, \"owner@test\",\n                                 \"read_customer_memory\",\n                                 {\"contact_id\": \"x@c.us\"})\n    check(\"low executed\", out[\"status\"] == \"executed\"\n          and out[\"risk\"] == \"low\"\n          and out[\"result\"][\"memory\"][0][\"content\"].startswith(\"Prefers\"),\n          out)\n    check(\"audited\", any(\"portal_action_log\" in sql\n                         for sql, _p in conn.cur.executed), \"audit\")\nfinally:\n    portal_actions.ACTIONS[\"read_customer_memory\"][\"run\"] = _orig_memory\n\nconn = install_db_stub(portal_actions, [\n    [{\"token\": \"tok123\", \"total\": 150}],   # link INSERT RETURNING\n    [],                                    # audit\n])\nout = portal_actions.execute(conn.cursor(), 1, \"owner@test\",\n                             \"create_checkout_link\", {\n                                 \"contact_id\": \"x@c.us\",\n                                 \"items\": [{\"name\": \"Hoodie\",\n                                            \"qty\": 1, \"price\": 150}],\n                             })\ncheck(\"medium checkout executed\", out[\"status\"] == \"executed\"\n      and out[\"result\"][\"token\"] == \"tok123\", out)\ninsert = next((p for sql, p in conn.cur.executed\n               if \"portal_checkout_links\" in sql), None)\n# params carry the freshly generated token; the scripted stub returns\n# \"tok123\" as the row, so compare shape + the executed params.\ncheck(\"link inserted\", insert is not None\n      and out[\"result\"][\"token\"] == \"tok123\"\n      and len(str(insert[2])) > 10, insert)\n\nprint(\"== execute: HIGH -> approval, nothing runs ==\")\n\nconn = share_stub(install_db_stub(portal_actions, []))\nconn = install_db_stub(portal_approvals, [\n    [], [], [],                            # lazy DDL\n    [],                                    # dup pending SELECT\n    CONFIG_ROW,                            # config\n    [{\"id\": 91}],                          # INSERT approval RETURNING\n    CONFIG_ROW,                            # approver config\n    STATUS_ROW,                            # connector phone\n    [],                                    # owner WhatsApp queued\n    [],                                    # audit\n])\nportal_actions.portal_db = portal_approvals.portal_db\nout = portal_actions.execute(conn.cursor(), 1, \"ai-agent\", \"request_refund\",\n                             {\"conversation_id\": 77,\n                              \"contact_id\": \"923008887777@c.us\",\n                              \"customer_query\": \"refund chahiye\"})\ncheck(\"high gated\", out[\"status\"] == \"approval_required\"\n      and out[\"refCode\"].startswith(\"AP-\"), out)\ncheck(\"no action_request yet\",\n      not any(\"portal_action_requests\" in sql\n              for sql, _p in conn.cur.executed), \"deferred\")\n\nprint(\"== resolve_approval: approved runs, rejected holds ==\")\n\nconn = install_db_stub(portal_approvals, [\n    [{\"contact_id\": \"923008887777@c.us\"}],  # conversation contact SELECT\n    [{\"id\": 701}],                          # action_request INSERT RETURNING\n    [],                                     # done UPDATE\n    [],                                     # audit\n])\nportal_actions.portal_db = portal_approvals.portal_db\nportal_actions.resolve_approval(conn.cursor(), 1, {\n    \"context_json\": json.dumps({\n        \"action\": \"request_refund\",\n        \"args\": {\"conversation_id\": 77,\n                 \"contact_id\": \"923008887777@c.us\"},\n    }),\n}, approved=True)\ndone = next((p for sql, p in conn.cur.executed\n             if \"UPDATE portal_action_requests\" in sql), None)\ncheck(\"approved -> request done\", done is not None and done[0] == 701,\n      done)\n\nconn = install_db_stub(portal_approvals, [\n    [],                                    # hold message queued\n])\nportal_actions.portal_db = portal_approvals.portal_db\nportal_actions.resolve_approval(conn.cursor(), 1, {\n    \"context_json\": json.dumps({\n        \"action\": \"request_refund\",\n        \"args\": {\"contact_id\": \"923008887777@c.us\"},\n    }),\n}, approved=False)\nsend = next((p for sql, p in conn.cur.executed\n             if \"portal_connector_commands\" in sql), None)\ncheck(\"rejected -> hold message\", send is not None\n      and \"process nahi ho saki\" in json.loads(send[1])[\"body\"],\n      json.loads(send[1])[\"body\"] if send else None)\n\nprint(\"== portal API ==\")\n\nwith Principal(portal_actions, principal=None):\n    check(\"catalog 401\", client.get(\n        \"/api/v1/portal/actions\").status_code == 401, 401)\n    check(\"execute 401\", client.post(\n        \"/api/v1/portal/actions/execute\",\n        json={\"action\": \"read_customer_memory\",\n              \"args\": {\"contact_id\": \"x\"}}).status_code == 401, 401)\n\nwith Principal(portal_actions, PRINCIPAL):\n    r = client.get(\"/api/v1/portal/actions\")\n    check(\"catalog 200\", r.status_code == 200\n          and len(r.get_json()[\"actions\"]) == 15, r.get_json())\n\n    conn = install_db_stub(portal_actions, [])\n    r = client.post(\"/api/v1/portal/actions/execute\",\n                    json={\"action\": \"no_such_action\", \"args\": {}})\n    check(\"unknown 400\", r.status_code == 400, r.status_code)\n\n    conn = install_db_stub(portal_actions, [])\n    r = client.post(\"/api/v1/portal/actions/execute\",\n                    json={\"action\": \"add_customer_note\",\n                          \"args\": {\"contact_id\": \"x\"}})\n    check(\"missing args 400\", r.status_code == 400, r.status_code)\n\n    _orig = portal_actions.ACTIONS[\"add_customer_note\"][\"run\"]\n    portal_actions.ACTIONS[\"add_customer_note\"][\"run\"] = (\n        lambda cur, cid, args: {\"memoryId\": 9})\n    try:\n        conn = install_db_stub(portal_actions, [\n            [],                            # audit\n        ])\n        r = client.post(\"/api/v1/portal/actions/execute\",\n                        json={\"action\": \"add_customer_note\",\n                              \"args\": {\"contact_id\": \"x@c.us\",\n                                       \"content\": \"Prefers COD\"}})\n        check(\"execute 200\", r.status_code == 200\n              and r.get_json()[\"status\"] == \"executed\", r.get_json())\n    finally:\n        portal_actions.ACTIONS[\"add_customer_note\"][\"run\"] = _orig\n\nportal_actions.PortalAuthUnavailable = Exception\nwith Principal(portal_actions, exc=Exception(\"db down\")):\n    r = client.get(\"/api/v1/portal/actions\")\n    check(\"auth down 503\", r.status_code == 503, r.status_code)\ndel portal_actions.PortalAuthUnavailable\n\nprint(\"== web pins ==\")\n\nRIG13 = \"/tmp/p13/Omniflow/\"\nAPPROVALS = open(RIG13 + \"omniflow-backend-patch/portal_approvals.py\",\n                 encoding=\"utf8\").read()\ncheck(\"decide -> resolve seam\",\n      \"portal_actions.resolve_approval\" in APPROVALS, \"seam\")\nAPP = open(RIG13 + \"omniflow-backend-patch/app.py\", encoding=\"utf8\").read()\ncheck(\"blueprints\", \"portal_actions_bp\" in APP\n      and APP.index(\"register_blueprint(portal_approvals_bp)\")\n      < APP.index(\"register_blueprint(portal_actions_bp)\"), \"app\")\n\nsummary(\"actions\")\n");

writeNewRepair("tools/cp-testrig/test_add_to_series.py", "cleaned\", \"enrollSequenceContacts(accessToken, sequenceId, cleaned)\" in\n      BFF, \"forward\")\n\nsummary(\"add_to_series\")", false,
    "\"\"\"216-220: \"Add to series\" from the conversation thread (website-only; reuses the\nexisting enrollments POST endpoint).\"\"\"\nimport os\n\nos.environ.setdefault(\"OMNIFLOW_SERVICE_KEY\", \"x\")\n\nfrom flask import Flask\n\nimport portal_sequences, test_lib\nfrom test_lib import check, human_principal, install_db_stub, summary, PrincipalStub\n\nPAGE = open(\n    \"/tmp/p13/Omniflow/app/dashboard/(portal)/conversations/[id]/AddToSequenceCard.tsx\",\n    encoding=\"utf8\",\n).read()\nTHREAD = open(\n    \"/tmp/p13/Omniflow/app/dashboard/(portal)/conversations/[id]/ThreadClient.tsx\",\n    encoding=\"utf8\",\n).read()\nBFF = open(\n    \"/tmp/p13/Omniflow/app/api/omniflow/portal/sequences/[id]/enrollments/route.ts\",\n    encoding=\"utf8\",\n).read()\nSRC = open(\"portal_sequences.py\", encoding=\"utf8\").read()\n\nDDL = [[], [], [], [], [], [], [], [], [], []]  # 4 CREATE + ALTER tk + settings + ALTER por + ALTER oii + step_log + idx\n\n\ndef fresh(script):\n    portal_sequences._SEQ_DDL_READY = False\n    conn = install_db_stub(portal_sequences, DDL + script)\n    portal_sequences.portal_db.CMD_TABLE = \"portal_connector_commands\"\n    return conn\n\n\napp = Flask(__name__)\napp.register_blueprint(portal_sequences.bp)\nclient = app.test_client()\nhuman = human_principal(client_id=1, user_id=11, email=\"ahmed@example.com\")\nPrincipalStub(portal_sequences, principal=human)\n\nprint(\"== reused enroll endpoint contract ==\")\n\nconn = fresh([[{\"contact_name\": \"Ali\", \"contact_id\": \"92300@c.us\"}],\n              [{\"contact_id\": \"92300@c.us\"}], []])\nresponse = client.post(\n    \"/api/v1/portal/sequences/5/enrollments\",\n    json={\"contacts\": [\"92300@c.us\"]},\n)\ncheck(\"single jid enrolls\", response.status_code == 200\n      and response.get_json().get(\"enrolled\") == 1, response.get_json())\ninsert = next(e for e in conn.cur.executed\n              if \"INSERT INTO\" in e[0] and \"portal_sequence_enrollments\" in e[0])\ncheck(\"name rides conv join\", \"c.contact_name\" in insert[0], \"join\")\ncheck(\"jid carried\", insert[1][4] == [\"92300@c.us\"], insert[1])\ncheck(\"dedupe protected\", \"NOT EXISTS\" in insert[0], \"dedupe\")\n\nconn = fresh([[]])\nresponse = client.post(\"/api/v1/portal/sequences/5/enrollments\",\n                       json={\"contacts\": [\"92300@c.us\"]})\ncheck(\"404 unknown sequence\", response.status_code == 404, response.status_code)\n\nconn = fresh([[{\"id\": 5}]])\nresponse = client.post(\"/api/v1/portal/sequences/5/enrollments\",\n                       json={\"contacts\": []})\ncheck(\"400 no contacts\", response.status_code == 400, response.status_code)\n\nprint(\"== card component ==\")\n\ncheck(\"client component\", PAGE.startswith('\"use client\"'), \"header\")\ncheck(\"props\", \"{ contactId }: { contactId: string | null }\" in PAGE, \"props\")\ncheck(\"loads sequences\", '\"/api/omniflow/portal/sequences\"' in PAGE, \"fetch\")\ncheck(\"enabled filter\", \"row.enabled === true\" in PAGE, \"filter\")\ncheck(\"hidden when none\", \"options.length === 0) return null\" in PAGE, \"hidden\")\ncheck(\"enrolls via BFF\", \"/enrollments\" in PAGE and \"method: \\\"POST\\\"\" in PAGE, \"post\")\ncheck(\"sends bare jid\", \"contacts: [contactId]\" in PAGE, \"body\")\ncheck(\"duplicate note\", \"Already in a series\" in PAGE, \"note\")\ncheck(\"success note\", \"Step 1 lands per the series' first delay.\" in PAGE, \"success\")\ncheck(\"disabled hint\", \"is the series turned on?\" in PAGE, \"400 note\")\ncheck(\"busy label\", \"Adding...\" in PAGE, \"busy\")\ncheck(\"alive guard\", \"let alive = true\" in PAGE, \"stale guard\")\n\nprint(\"== thread integration ==\")\n\ncheck(\"dynamic import\", 'dynamic(() => import(\"./AddToSequenceCard\"))' in THREAD, \"import\")\ncheck(\"rendered after CustomerCard\", THREAD.index(\"<CustomerCard\")\n      < THREAD.index(\"<AddToSequenceCard\"), \"order\")\ncheck(\"guarded like siblings\", \"!expired && !notFound && (\\n        <AddToSequenceCard\" in\n      THREAD, \"guard\")\ncheck(\"passes contact id\", \"contactId={conversation?.contactId ?? null}\" in\n      THREAD, \"props\")\n\nprint(\"== BFF passthrough intact ==\")\n\ncheck(\"enrollments POST exists\", \"export async function POST(\" in BFF, \"post\")\ncheck(\"forwards cleaned\", \"enrollSequenceContacts(accessToken, sequenceId, cleaned)\" in\n      BFF, \"forward\")\n\nsummary(\"add_to_series\")\n");

writeNewRepair("tools/cp-testrig/test_admin_keys.py", "leNotFoundError:\n    check(\"ui stt card\", False, \"ui\")\n    check(\"ui stt groupkey\", False, \"ui\")\n\nsummary(\"admin_keys\")", false,
    "\"\"\"Admin API keys panel (D2): every external key editable in Admin >\nIntegrations, DB-backed, live without redeploy.\n\nCovers: the platform_settings stt group registry (admin PUT whitelist is\nGROUP_KEYS-driven), stt_config DB-first with env fallback,\nportal_media._stt_config layering (defaults applied here, None when\nunconfigured -> the route answers 409 stt_not_configured), the portal_llm\n_runtime panel-overrides-env pin (saving a key goes live instantly), and\nthe admin Integrations UI carrying the Speech-to-Text inputs (vs the\n/tmp/p13 mirror).\n\"\"\"\nimport os\n\nimport portal_llm\nimport portal_media\nimport platform_settings\nfrom test_lib import check, summary\n\nRIG13 = \"/tmp/p13/Omniflow/\"\n\n# --- registry: the stt group exists; the PUT whitelist + masking are\n# driven by GROUP_KEYS / SECRET_HINTS respectively.\ncheck(\"stt group registered\",\n      platform_settings.GROUP_KEYS.get(\"stt\")\n      == [\"api_key\", \"base_url\", \"model\"], \"registry\")\ncheck(\"stt key masked\", \"api_key\" in platform_settings.SECRET_HINTS,\n      \"registry\")\n\n# --- stt_config: DB-first, env fallback, empty is fine\n_orig_group = platform_settings.get_group\ntry:\n    platform_settings.get_group = lambda g: {\n        \"api_key\": \"sk-db-1\", \"base_url\": \"https://db.example.com/v1\",\n        \"model\": \"db-whisper\"}\n    cfg = platform_settings.stt_config()\n    check(\"stt db-first\", cfg[\"api_key\"] == \"sk-db-1\"\n          and cfg[\"base_url\"] == \"https://db.example.com/v1\"\n          and cfg[\"model\"] == \"db-whisper\", \"stt_config\")\n\n    platform_settings.get_group = lambda g: {}\n    os.environ[\"OMNIFLOW_STT_API_KEY\"] = \"sk-env-1\"\n    cfg = platform_settings.stt_config()\n    check(\"stt env fallback\", cfg[\"api_key\"] == \"sk-env-1\", \"stt_config\")\n    os.environ.pop(\"OMNIFLOW_STT_API_KEY\")\n    cfg = platform_settings.stt_config()\n    check(\"stt unconfigured empty\", cfg[\"api_key\"] == \"\", \"stt_config\")\nfinally:\n    platform_settings.get_group = _orig_group\n\n# --- portal_media._stt_config: defaults layered here, None unconfigured\ntry:\n    platform_settings.get_group = lambda g: {\"api_key\": \"sk-db-1\"}\n    got = portal_media._stt_config()\n    check(\"media defaults applied\",\n          got == (portal_media.STT_BASE_DEFAULT, \"sk-db-1\",\n                  portal_media.STT_MODEL_DEFAULT), \"media_layering\")\n\n    platform_settings.get_group = lambda g: {\n        \"api_key\": \"k\", \"base_url\": \"https://x.example/v1/\", \"model\": \"m1\"}\n    got = portal_media._stt_config()\n    check(\"media custom values\", got == (\"https://x.example/v1\", \"k\", \"m1\"),\n          \"media_layering\")\n\n    platform_settings.get_group = lambda g: {}\n    _saved = {k: v for k, v in os.environ.items()\n              if k.startswith(\"OMNIFLOW_STT\")}\n    for k in _saved:\n        os.environ.pop(k)\n    check(\"media none unconfigured\", portal_media._stt_config() is None,\n          \"media_layering\")\n    os.environ[\"OMNIFLOW_STT_API_KEY\"] = \"env-only\"\n    got = portal_media._stt_config()\n    check(\"media env-only fallback\",\n          got == (portal_media.STT_BASE_DEFAULT, \"env-only\",\n                  portal_media.STT_MODEL_DEFAULT), \"media_layering\")\n    os.environ.pop(\"OMNIFLOW_STT_API_KEY\")\nfinally:\n    platform_settings.get_group = _orig_group\n\n# --- the LLM engine already goes live from the panel (no redeploy)\n_orig_group = platform_settings.get_group\ntry:\n    platform_settings.get_group = lambda g: (\n        {\"api_key\": \"sk-panel\", \"base_url\": \"https://panel/v1\",\n         \"model\": \"panel-model\"} if g == \"llm\" else {})\n    rt = portal_llm._runtime()\n    check(\"llm panel overrides env\", rt.get(\"api_key\") == \"sk-panel\"\n          and rt.get(\"model\") == \"panel-model\" and rt.get(\"enabled\"), \"llm\")\nfinally:\n    platform_settings.get_group = _orig_group\n\n# --- admin Integrations UI carries the Speech-to-Text card\ntry:\n    src = open(RIG13 + \"app/admin/(panel)/integrations/\"\n               \"IntegrationsClient.tsx\", encoding=\"utf8\").read()\n    check(\"ui stt card\", 'id: \"stt\"' in src and \"whisper-1\" in src\n          and \"no redeploy needed\" in src, \"ui\")\n    check(\"ui stt groupkey\", '| \"stt\"' in src, \"ui\")\nexcept FileNotFoundError:\n    check(\"ui stt card\", False, \"ui\")\n    check(\"ui stt groupkey\", False, \"ui\")\n\nsummary(\"admin_keys\")\n");

writeNewRepair("tools/cp-testrig/test_agent_assist.py", ".get(URL)\ncheck(\"401 unauth\", status(response) == 401, status(response))\n\nsys.exit(1 if summary(\"agent_assist\") else 0)", false,
    "\"\"\"Tests for agent assist v0 (deterministic KB suggestions + hints).\"\"\"\nimport sys\n\nfrom flask import Flask\n\nimport portal_conversations\nimport test_lib\nfrom test_lib import check, install_db_stub, PrincipalStub, status, summary\n\napp = Flask(__name__)\napp.register_blueprint(portal_conversations.bp)\nclient = app.test_client()\n\nhuman = {\n    \"session_id\": \"s\", \"user_id\": 11, \"client_id\": 1, \"role\": \"owner\",\n    \"email\": \"ahmed@example.com\", \"display_name\": \"Ahmed\", \"via_api_key\": False,\n}\nPrincipalStub(portal_conversations, principal=human)\n\nURL = \"/api/v1/portal/conversations/42/assist\"\n\nprint(\"== tokens ==\")\n\ntokens = portal_conversations._assist_tokens(\"What is the refund status?\")\ncheck(\"stopwords removed\", \"what\" not in tokens and \"the\" not in tokens, tokens)\ncheck(\"content kept\", {\"refund\", \"status\"} <= tokens, tokens)\ncheck(\"short words dropped\", \"is\" not in tokens, tokens)\n\nprint(\"== assist endpoint ==\")\n\nconn = install_db_stub(portal_conversations, [[]])\nportal_conversations.portal_db.CONV_TABLE = \"portal_conversations\"\nportal_conversations.portal_db.MSGS_TABLE = \"portal_messages\"\nresponse = client.get(URL)\ncheck(\"404 unknown conversation\", status(response) == 404, status(response))\n\nPROBE = [{\"oid\": \"portal_kb_entries\"}]\nconn = install_db_stub(portal_conversations, [\n    [{\"contact_id\": \"92300@c.us\"}],\n    [{\"body\": \"order #123 kab aay\"}, {\"body\": \"refund chahiye\"}],\n    PROBE,\n    [\n        {\"id\": 5, \"question\": \"refund policy kya hai\",\n         \"answer\": \"7 din ke andar refund ho jata hai.\"},\n        {\"id\": 6, \"question\": \"delivery time kitna hai\",\n         \"answer\": \"2-3 din.\"},\n    ],\n    PROBE,\n    [{\"lang\": \"roman\"}],\n    PROBE,\n    [{\"contact_id\": \"tg:999\"}],\n])\nportal_conversations.portal_db.CONV_TABLE = \"portal_conversations\"\nportal_conversations.portal_db.MSGS_TABLE = \"portal_messages\"\nresponse = client.get(URL)\npayload = response.get_json()\ncheck(\"200 assist\", status(response) == 200, status(response))\ncheck(\"intent refund\", payload[\"intent\"] == \"refund\", payload[\"intent\"])\ncheck(\"language hint\", payload[\"language\"] == \"roman\", payload)\ncheck(\"linked hint\", payload[\"linked\"] == [\"tg:999\"], payload)\ncheck(\"suggestion top\", payload[\"suggestions\"][0][\"id\"] == 5\n      and \"refund\" in payload[\"suggestions\"][0][\"matched\"],\n      payload[\"suggestions\"])\ncheck(\"snippet trimmed\", len(payload[\"suggestions\"][0][\"snippet\"]) <= 160,\n      payload[\"suggestions\"][0][\"snippet\"])\ncheck(\"based_on chronological\", payload[\"based_on\"].endswith(\"order #123 kab aay\"),\n      payload[\"based_on\"])\ncheck(\"conversation scoped\", \"id = %s AND client_id = %s\"\n      in conn.cur.executed[0][0]\n      and conn.cur.executed[0][1] == (42, 1), conn.cur.executed[0][1])\ncheck(\"inbound only latest 3\", \"direction = 'in'\" in conn.cur.executed[1][0]\n      and \"LIMIT 3\" in conn.cur.executed[1][0], \"sql\")\ncheck(\"kb limited 200\", \"LIMIT 200\" in conn.cur.executed[3][0], \"sql\")\n\nconn = install_db_stub(portal_conversations, [\n    [{\"contact_id\": \"92300@c.us\"}],\n    [{\"body\": \"salam\"}],\n    [],\n    [],\n    [],\n])\nresponse = client.get(URL)\npayload = response.get_json()\ncheck(\"no kb table degrades\", status(response) == 200\n      and payload[\"suggestions\"] == [] and payload[\"language\"] is None, payload)\n\nconn = install_db_stub(portal_conversations, [\n    [{\"contact_id\": \"92300@c.us\"}],\n    [{\"body\": \"price kitna hai delivery kab hai payment kaise hai tracking kahan\"},\n     {\"body\": \"refund chahiye discount chahiye delivery kab hai\"}],\n    PROBE,\n    [\n        {\"id\": 1, \"question\": \"delivery time\", \"answer\": \"a\"},\n        {\"id\": 2, \"question\": \"delivery charges\", \"answer\": \"b\"},\n        {\"id\": 3, \"question\": \"delivery updates\", \"answer\": \"c\"},\n        {\"id\": 4, \"question\": \"refund policy\", \"answer\": \"d\"},\n    ],\n    [],\n    [],\n])\nresponse = client.get(URL)\npayload = response.get_json()\ncheck(\"suggestions capped at 2\", len(payload[\"suggestions\"]) == 2,\n      payload[\"suggestions\"])\ncheck(\"best first\", payload[\"suggestions\"][0][\"score\"]\n      >= payload[\"suggestions\"][1][\"score\"], payload[\"suggestions\"])\n\nconn = install_db_stub(portal_conversations, [\n    [{\"contact_id\": \"92300@c.us\"}],\n    [],\n    PROBE,\n    [{\"id\": 8, \"question\": \"nothing matching\", \"answer\": \"x\"}],\n    [],\n    [],\n])\nresponse = client.get(URL)\npayload = response.get_json()\ncheck(\"no overlap no suggestions\", payload[\"suggestions\"] == [], payload)\n\nPrincipalStub(portal_conversations, principal=None)\nresponse = client.get(URL)\ncheck(\"401 unauth\", status(response) == 401, status(response))\n\nsys.exit(1 if summary(\"agent_assist\") else 0)\n");

writeNewRepair("tools/cp-testrig/test_agents.py", "tf8\").read()\ncheck(\"team page mounts agents section\",\n      \"<AgentsAndRouting />\" in TEAM, \"mount\")\n\nsummary(\"agents\")", false,
    "\"\"\"Tests for Router+Agents upgrade: portal_agents (AI agent personas +\nversioning + soft archive, human-only API) + portal_routing agent targets\n+ portal_brain persona wiring + web pins (BFF, portal.ts, team UI).\"\"\"\nfrom flask import Flask\n\nimport portal_agents\nimport portal_routing\nimport portal_db\nfrom test_lib import install_db_stub\nfrom test_lib import check, summary\n\nPRINCIPAL = {\n    \"session_id\": \"s\", \"user_id\": 11, \"client_id\": 1, \"role\": \"owner\",\n    \"email\": \"ahmed@example.com\", \"display_name\": \"Ahmed\",\n    \"via_api_key\": False,\n}\n\nAGENT_ROW = {\"id\": 7, \"name\": \"Sales Aunty\", \"tone\": \"cheerful\",\n             \"instructions\": \"Upsell gently.\", \"escalation_user_id\": 9,\n             \"is_active\": True, \"updated_at\": \"u\"}\n\n\nclass PrincipalStub:\n    def __init__(self, module, principal):\n        self.module = module\n        self.principal = principal\n\n    def __enter__(self):\n        self.orig = self.module.authenticate_portal_request\n        self.module.authenticate_portal_request = lambda: self.principal\n        self.module.PortalAuthUnavailable = Exception\n        return self\n\n    def __exit__(self, *a):\n        self.module.authenticate_portal_request = self.orig\n\n\ndef fresh(script):\n    portal_agents._DDL_READY = True\n    return install_db_stub(portal_agents, script)\n\n\ndef run_api(script, method, path, json_body=None, principal=PRINCIPAL):\n    fresh(script)\n    app = Flask(\"agents-test\")\n    app.register_blueprint(portal_agents.bp)\n    with PrincipalStub(portal_agents, principal):\n        client = app.test_client()\n        if method == \"GET\":\n            return client.get(path)\n        if method == \"POST\":\n            return client.post(path, json=json_body)\n        if method == \"PUT\":\n            return client.put(path, json=json_body)\n        if method == \"DELETE\":\n            return client.delete(path)\n    return None\n\n\n# ---------- read helpers (fail-soft) ----------\n\nconn = fresh([[AGENT_ROW]])\nwith conn.cur as cur:\n    agent = portal_agents.load_agent(cur, 1, 7)\ncheck(\"load_agent shaped\", agent is not None and agent[\"name\"] == \"Sales Aunty\"\n      and agent[\"tone\"] == \"cheerful\", agent)\n\nconn = fresh([[]])\nwith conn.cur as cur:\n    check(\"load_agent missing -> None\",\n          portal_agents.load_agent(cur, 1, 7) is None, \"none\")\n\nconn = fresh([[AGENT_ROW]])\nwith conn.cur as cur:\n    got = portal_agents.agent_for_conversation(cur, 1, 55)\ncheck(\"agent_for_conversation\", got is not None\n      and got[\"id\"] == 7 and got[\"name\"] == \"Sales Aunty\", got)\n\nconn = fresh([])\nwith conn.cur as cur:\n    check(\"agent_for_conversation fail-soft\",\n          portal_agents.agent_for_conversation(cur, 1, 55) is None, \"soft\")\n\nconn = fresh([[]])\nwith conn.cur as cur:\n    portal_agents.assign_agent(cur, 1, 55, 7)\ncheck(\"assign_agent upsert\",\n      any(\"ON CONFLICT\" in s for s, p in conn.cur.executed), \"upsert\")\n\n\n# ---------- owner API ----------\n\nr = run_api([[AGENT_ROW], [{\"agent_id\": 7, \"versions\": 3}]], \"GET\",\n            \"/api/v1/portal/agents\")\ncheck(\"agents list 200\", r.status_code == 200, r.status_code)\nbody = r.get_json()\ncheck(\"agents list shape\", body[\"agents\"][0][\"id\"] == 7\n      and body[\"agents\"][0][\"name\"] == \"Sales Aunty\"\n      and body[\"agents\"][0][\"versions\"] == 3\n      and body[\"agents\"][0][\"escalation_user_id\"] == 9, body)\n\nr = run_api([[{\"total\": 0}], [{\"id\": 7}], [], []], \"POST\", \"/api/v1/portal/agents\",\n            json_body={\"name\": \"Support Pro\", \"tone\": \"formal\",\n                       \"instructions\": \"Policy strict.\", \"escalation_user_id\": 5})\ncheck(\"agents create 200\", r.status_code == 200\n      and r.get_json()[\"agent\"][\"id\"] == 7\n      and r.get_json()[\"agent\"][\"versions\"] == 1, r.get_json())\nsqls = [s for s, p in portal_agents.portal_db.conn.cur.executed]\ncheck(\"agents create versions snapshot\",\n      any(\"INSERT INTO portal_agent_versions\" in s for s in sqls), \"version\")\n\nr = run_api([[]], \"POST\", \"/api/v1/portal/agents\",\n            json_body={\"name\": \"\", \"tone\": \"\", \"instructions\": \"\"})\ncheck(\"agents create 400 empty name\", r.status_code == 400, r.status_code)\n\nr = run_api([[]], \"POST\", \"/api/v1/portal/agents\",\n            json_body={\"name\": \"X\", \"tone\": \"\", \"instructions\": \"\",\n                       \"escalation_user_id\": -3})\ncheck(\"agents create 400 bad escalation\", r.status_code == 400, r.status_code)\n\nr = run_api([[{\"total\": 10}]], \"POST\", \"/api/v1/portal/agents\",\n            json_body={\"name\": \"X\", \"tone\": \"\", \"instructions\": \"\"})\ncheck(\"agents create 400 max\", r.status_code == 400, r.status_code)\n\nr = run_api([[{\"id\": 7}], [], []], \"PUT\", \"/api/v1/portal/agents/7\",\n            json_body={\"name\": \"Support Pro v2\", \"tone\": \"formal\",\n                       \"instructions\": \"x\", \"escalation_user_id\": None,\n                       \"is_active\": False})\ncheck(\"agents update 200\", r.status_code == 200, r.status_code)\n\nr = run_api([[]], \"PUT\", \"/api/v1/portal/agents/999\",\n            json_body={\"name\": \"X\", \"tone\": \"\", \"instructions\": \"\"})\ncheck(\"agents update 404\", r.status_code == 404, r.status_code)\n\nr = run_api([[{\"id\": 7}], []], \"DELETE\", \"/api/v1/portal/agents/7\")\ncheck(\"agents archive 200 soft\", r.status_code == 200, r.status_code)\nsqls = [s for s, p in portal_agents.portal_db.conn.cur.executed]\ncheck(\"agents archive soft delete\",\n      any(\"SET is_active = FALSE\" in s for s in sqls), \"soft\")\n\nr = run_api([[]], \"DELETE\", \"/api/v1/portal/agents/999\")\ncheck(\"agents archive 404\", r.status_code == 404, r.status_code)\n\nr = run_api([[]], \"GET\", \"/api/v1/portal/agents\",\n            principal={\"via_api_key\": True, \"client_id\": 1, \"user_id\": 1})\ncheck(\"agents api key 403\", r.status_code == 403, r.status_code)\n\nr = run_api([[]], \"GET\", \"/api/v1/portal/agents\", principal=None)\ncheck(\"agents anon 401\", r.status_code == 401, r.status_code)\n\n\n# ---------- routing: agent targets ----------\n\ndef routing_fresh(script):\n    portal_routing._ROUTING_DDL_READY = True\n    conn = install_db_stub(portal_routing, script)\n    portal_routing.portal_db.CONV_TABLE = \"portal_conversations\"\n    return conn\n\n\nrouting_app = Flask(\"routing-test\")\nrouting_app.register_blueprint(portal_routing.bp)\n\n\ndef run_routing(script, method, path, json_body=None, principal=PRINCIPAL):\n    routing_fresh(script)\n    with PrincipalStub(portal_routing, principal):\n        client = routing_app.test_client()\n        if method == \"POST\":\n            return client.post(path, json=json_body)\n        if method == \"GET\":\n            return client.get(path)\n        if method == \"DELETE\":\n            return client.delete(path)\n    return None\n\n\nr = run_routing([[{\"total\": 0}], [AGENT_ROW], [{\"id\": 9}], []],\n                \"POST\", \"/api/v1/portal/routing/rules\",\n                json_body={\"match\": \"refund\", \"target_type\": \"agent\",\n                           \"agent_id\": 7, \"priority\": 5})\ncheck(\"agent rule 200\", r.status_code == 200\n      and r.get_json()[\"id\"] == 9, r.status_code)\nsqls = [s for s, p in portal_routing.portal_db.conn.cur.executed]\ncheck(\"agent rule insert has agent_id\",\n      any(\"target_type\" in s and \"agent_id\" in s for s in sqls), \"insert\")\n\nr = run_routing([[{\"total\": 0}], []], \"POST\", \"/api/v1/portal/routing/rules\",\n                json_body={\"match\": \"refund\", \"target_type\": \"agent\",\n                           \"agent_id\": 99, \"priority\": 5})\ncheck(\"agent rule 400 unknown agent\", r.status_code == 400, r.status_code)\n\nr = run_routing([[]], \"POST\", \"/api/v1/portal/routing/rules\",\n                json_body={\"match\": \"refund\", \"target_type\": \"agent\",\n                           \"agent_id\": 0})\ncheck(\"agent rule 400 bad agent id\", r.status_code == 400, r.status_code)\n\nr = run_routing([[]], \"POST\", \"/api/v1/portal/routing/rules\",\n                json_body={\"match\": \"refund\", \"target_type\": \"robot\",\n                           \"agent_id\": 7})\ncheck(\"agent rule 400 bad target type\", r.status_code == 400, r.status_code)\n\n# maybe_route assigns an agent (not a teammate) for agent rules\nAGENT_RULE = [{\"id\": 1, \"match_text\": \"refund\", \"user_id\": 0,\n               \"target_type\": \"agent\", \"agent_id\": 7}]\nconn = routing_fresh([AGENT_RULE, [], [], []])\nportal_routing.maybe_route(1, 42, \"92x\", \"REFUND chahiye\", conn)\nsqls = [s for s, p in conn.cur.executed]\ncheck(\"route assigns agent row\",\n      any(\"portal_conversation_agents\" in s and \"ON CONFLICT\" in s\n          for s in sqls), sqls)\ncheck(\"route no teammate assign\",\n      not any(\"UPDATE portal_conversations\" in s for s in sqls), \"no user\")\n\n# inactive agent rule is skipped (LEFT JOIN filter)\nconn = routing_fresh([[], []])\nportal_routing.maybe_route(1, 42, \"92x\", \"salam\", conn)\ncheck(\"no rule no assign\", len(conn.cur.executed) == 1, conn.cur.executed)\n\n\n# ---------- wiring pins ----------\n\nAPP = open(\"/tmp/smoke971/app.py\", encoding=\"utf8\").read()\ncheck(\"app.py registers agents bp\",\n      \"aux_app.register_blueprint(portal_agents_bp)\" in APP, \"bp\")\n\nBRAIN = open(\"portal_brain.py\", encoding=\"utf8\").read()\ncheck(\"brain resolves agent persona\",\n      \"agent_for_conversation(\" in BRAIN\n      and \"agent_persona\" in BRAIN, \"brain\")\n\nROUTING = open(\"portal_routing.py\", encoding=\"utf8\").read()\ncheck(\"routing target_type column\",\n      \"ADD COLUMN IF NOT EXISTS target_type\" in ROUTING\n      and \"ADD COLUMN IF NOT EXISTS agent_id\" in ROUTING, \"ddl\")\ncheck(\"routing assign_agent wired\",\n      \"portal_agents.assign_agent(\" in ROUTING, \"wire\")\n\nPORTAL = open(\"/tmp/p13/Omniflow/lib/omniflow/portal.ts\",\n              encoding=\"utf8\").read()\nfor fn in (\"listAgents\", \"createAgent\", \"updateAgent\", \"archiveAgent\"):\n    check(\"client \" + fn, \"export async function \" + fn in PORTAL, fn)\ncheck(\"client RoutingRule agent fields\",\n      \"targetType: RoutingTargetType;\" in PORTAL\n      and \"agentName: string | null;\" in PORTAL, \"type\")\n\nBFF_ROUTE = open(\"/tmp/smoke971/bff_routing_rules.ts\", encoding=\"utf8\").read()\ncheck(\"bff routing validates agent target\",\n      \"target_type\" in BFF_ROUTE and \"agent_id is required for agent targets\"\n      in BFF_ROUTE, \"bffroute\")\n\nBFF = open(\"/tmp/smoke971/bff_agents.ts\", encoding=\"utf8\").read()\ncheck(\"bff agents list/create\", \"listAgents\" in BFF\n      and \"createAgent\" in BFF, \"bff\")\nBFF_ID = open(\"/tmp/smoke971/bff_id_agent_id.ts\", encoding=\"utf8\").read()\ncheck(\"bff agents [id] update/archive\", \"updateAgent\" in BFF_ID\n      and \"archiveAgent\" in BFF_ID, \"bffid\")\ncheck(\"bff agents [id] awaits Next 16 params (Promise)\",\n      \"params: Promise<{ id: string }>\" in BFF_ID\n      and \"params: { id: string }\" not in BFF_ID, \"bffid-params\")\nUI = open(\"/tmp/smoke971/agents_routing.tsx\", encoding=\"utf8\").read()\ncheck(\"team UI agents + routing\",\n      \"Create agent\" in UI and \"Add rule\" in UI, \"ui\")\nTEAM = open(\"/tmp/smoke971/team_page.tsx\", encoding=\"utf8\").read()\ncheck(\"team page mounts agents section\",\n      \"<AgentsAndRouting />\" in TEAM, \"mount\")\n\nsummary(\"agents\")\n");

writeNewRepair("tools/cp-testrig/test_ai_ops.py", "n CARD and \"\\\\u25b6\" not in CARD\n      and \"\\\\u2714\" not in CARD, \"-\")\n\nraise SystemExit(1 if summary(\"ai_ops\") else 0)", false,
    "\"\"\"AI usage/cost ledger + unified AI audit (platform services): the\nportal_llm usage scope + recording hook, the ledger write paths (caller\ntransaction behind a SAVEPOINT / own connection / kill switch), the price\ntable + cost estimate, the usage report rollups, the audit categories,\ntimeline + overview read models with their SQL, API auth, and the wiring\npins (scopes at every LLM call site, admin price field, page cards).\"\"\"\nimport os\nimport time\n\nfrom flask import Flask\n\nimport portal_ai_audit as pa\nimport portal_ai_usage as pu\nimport portal_llm\nfrom test_lib import check, install_db_stub, summary\n\nPRINCIPAL = {\n    \"session_id\": \"s\", \"user_id\": 11, \"client_id\": 1, \"role\": \"owner\",\n    \"email\": \"ahmed@example.com\", \"display_name\": \"Ahmed\",\n    \"via_api_key\": False,\n}\nAPI_KEY_PRINCIPAL = dict(PRINCIPAL, via_api_key=True)\nPRICES = {\"gpt-4o-mini\": {\"input\": 0.15, \"output\": 0.60},\n          \"default\": {\"input\": 1.0, \"output\": 2.0}}\n\n\nclass PrincipalStub:\n    def __init__(self, module, principal):\n        self.module = module\n        self.principal = principal\n\n    def __enter__(self):\n        self.orig = self.module.authenticate_portal_request\n        self.module.authenticate_portal_request = lambda: self.principal\n        self.module.PortalAuthUnavailable = Exception\n        return self\n\n    def __exit__(self, *a):\n        self.module.authenticate_portal_request = self.orig\n\n\ndef run_api(module, script, path, principal=PRINCIPAL):\n    pu._DDL_READY = True\n    install_db_stub(module, script)\n    app = Flask(\"ai-ops-test\")\n    app.register_blueprint(module.bp)\n    with PrincipalStub(module, principal):\n        return app.test_client().get(path)\n\n\n# ---------- llm scope + hook ----------\n\nprint(\"== llm scope ==\")\ncheck(\"no scope -> defaults\", portal_llm.current_scope() == (\"\", 0, None), \"-\")\nwith portal_llm.usage_scope(\"brain\", 7, \"CUR\"):\n    inner = portal_llm.current_scope()\n    with portal_llm.usage_scope(\"intent\", 7):\n        nested = portal_llm.current_scope()\n    after_inner = portal_llm.current_scope()\ncheck(\"scopes nest, innermost wins, and unwind\",\n      inner == (\"brain\", 7, \"CUR\") and nested == (\"intent\", 7, None)\n      and after_inner == inner and portal_llm.current_scope() == (\"\", 0, None),\n      (inner, nested, after_inner))\n\nrecorded = []\n_orig_record = pu.record\npu.record = lambda *a, **k: recorded.append((a, k)) or True\nwith portal_llm.usage_scope(\"brain\", 7, \"CUR\"):\n    portal_llm._record_usage(\"gpt-4o-mini\", {\"prompt_tokens\": 120,\n                                             \"completion_tokens\": 30},\n                             True, time.time() - 0.25)\ncheck(\"hook passes feature/client/model/tokens/latency/ok + the scope cursor\",\n      recorded and recorded[0][0][:5] == (7, \"brain\", \"gpt-4o-mini\", 120, 30)\n      and 200 <= recorded[0][0][5] <= 5000 and recorded[0][0][6] is True\n      and recorded[0][1] == {\"cur\": \"CUR\"}, recorded)\nrecorded[:] = []\nportal_llm._record_usage(\"m\", None, False, time.time())\ncheck(\"no usage block -> zero tokens, feature 'other', workspace 0\",\n      recorded[0][0][:4] == (0, \"other\", \"m\", 0) and recorded[0][0][6] is False,\n      recorded)\n\n# the real chat_json records through the hook (fake transport)\n_orig_post, _orig_runtime = portal_llm._http_post_json, portal_llm._runtime\nportal_llm._runtime = lambda: {\"base_url\": \"https://llm.test/v1\", \"api_key\": \"k\",\n                               \"model\": \"gpt-4o-mini\", \"enabled\": True}\nportal_llm._http_post_json = lambda url, headers, payload: {\n    \"choices\": [{\"message\": {\"content\": \"{\\\"reply\\\": \\\"ok\\\"}\"}}],\n    \"usage\": {\"prompt_tokens\": 11, \"completion_tokens\": 4, \"total_tokens\": 15}}\nrecorded[:] = []\nwith portal_llm.usage_scope(\"workflow\", 3):\n    out = portal_llm.chat_json(\"s\", \"u\")\ncheck(\"chat_json success -> parsed payload + one usage record (ok)\",\n      out == {\"reply\": \"ok\"} and len(recorded) == 1\n      and recorded[0][0][:5] == (3, \"workflow\", \"gpt-4o-mini\", 11, 4)\n      and recorded[0][0][6] is True, recorded)\nportal_llm._http_post_json = lambda url, headers, payload: None\nrecorded[:] = []\nout = portal_llm.chat_json(\"s\", \"u\")\ncheck(\"chat_json transport failure -> None + one failed record\",\n      out is None and len(recorded) == 1 and recorded[0][0][6] is False\n      and recorded[0][0][3:5] == (0, 0), recorded)\nportal_llm._http_post_json = lambda url, headers, payload: {\n    \"choices\": [{\"message\": {\"content\": \"not json\"}}],\n    \"usage\": {\"prompt_tokens\": 9, \"completion_tokens\": 1}}\nrecorded[:] = []\nout = portal_llm.chat_json(\"s\", \"u\")\ncheck(\"unparseable answer -> None, tokens still billed as failed\",\n      out is None and recorded[0][0][3:5] == (9, 1) and recorded[0][0][6] is False,\n      recorded)\nportal_llm._runtime = lambda: {\"enabled\": False, \"api_key\": \"\"}\nrecorded[:] = []\ncheck(\"engine disabled -> no call, no record\", portal_llm.chat_json(\"s\", \"u\") is None\n      and not recorded, \"-\")\nportal_llm._http_post_json, portal_llm._runtime = _orig_post, _orig_runtime\npu.record = _orig_record\n\n# ---------- ledger write paths ----------\n\nprint(\"== ledger ==\")\npu._DDL_READY = True\npu.ENABLED = True\nconn = install_db_stub(pu, [[], [], []])\nok = pu.record(1, \"brain\", \"gpt-4o-mini\", 100, 20, 850, True, cur=conn.cur)\nex = conn.cur.executed\ncheck(\"caller cursor: SAVEPOINT / INSERT / RELEASE (transaction-safe)\",\n      ok is True and ex[0][0] == \"SAVEPOINT of_ai_usage\"\n      and ex[1][0].startswith(\"INSERT INTO portal_ai_usage\")\n      and ex[1][1] == (1, \"brain\", \"gpt-4o-mini\", 100, 20, 850, True)\n      and ex[2][0] == \"RELEASE SAVEPOINT of_ai_usage\", ex)\nconn = install_db_stub(pu, [[], Exception(\"no table\"), []])\nok = pu.record(1, \"brain\", \"m\", 1, 1, 1, True, cur=conn.cur)\ncheck(\"insert failure -> ROLLBACK TO SAVEPOINT, caller's transaction survives\",\n      ok is False and conn.cur.executed[2][0] == \"ROLLBACK TO SAVEPOINT of_ai_usage\",\n      conn.cur.executed)\nconn = install_db_stub(pu, [[]])\nok = pu.record(2, \"bogus-feature\", \"m\", -5, 3, 10, False)\ncheck(\"own connection path: one INSERT, committed, feature normalised, negatives clamped\",\n      ok is True and conn.cur.executed[0][1] == (2, \"other\", \"m\", 0, 3, 10, False)\n      and conn.committed and conn.closed, conn.cur.executed)\npu.ENABLED = False\nconn = install_db_stub(pu, [])\ncheck(\"OF_AI_USAGE=0 -> nothing written\", pu.record(1, \"brain\", \"m\", 1, 1, 1, True) is False\n      and conn.cur.executed == [], \"-\")\npu.ENABLED = True\n\n# ---------- prices + cost ----------\n\nprint(\"== prices ==\")\ncheck(\"parse_prices: lower-cases models, drops junk + negatives\",\n      pu.parse_prices('{\"GPT-4o-mini\": {\"input\": 0.15, \"output\": 0.6}, \"x\": 1,'\n                      ' \"neg\": {\"input\": -1, \"output\": 1}}')\n      == {\"gpt-4o-mini\": {\"input\": 0.15, \"output\": 0.6}}, \"-\")\ncheck(\"parse_prices: bad JSON / non-object -> {}\", pu.parse_prices(\"nope\") == {}\n      and pu.parse_prices(\"[1]\") == {} and pu.parse_prices(None) == {}, \"-\")\ncheck(\"estimate_cost: per-million maths, default fallback, unknown -> None\",\n      pu.estimate_cost(\"gpt-4o-mini\", 1000000, 1000000, PRICES) == 0.75\n      and pu.estimate_cost(\"claude-x\", 1000000, 0, PRICES) == 1.0\n      and pu.estimate_cost(\"claude-x\", 1, 1, {\"gpt-4o-mini\": PRICES[\"gpt-4o-mini\"]}) is None\n      and pu.estimate_cost(\"m\", 1, 1, {}) is None, \"-\")\nimport platform_settings  # noqa: E402\n\n_orig_get = platform_settings.get_setting\nplatform_settings.get_setting = lambda key, default=None: (\n    '{\"gpt-4o-mini\": {\"input\": 0.15, \"output\": 0.6}}' if key == \"llm.prices_json\" else default)\ncheck(\"prices() reads the admin-saved llm.prices_json\", pu.prices()\n      == {\"gpt-4o-mini\": {\"input\": 0.15, \"output\": 0.6}}, pu.prices())\nplatform_settings.get_setting = lambda key, default=None: default\nos.environ[\"OF_AI_PRICES_JSON\"] = '{\"default\": {\"input\": 1, \"output\": 1}}'\ncheck(\"prices() falls back to OF_AI_PRICES_JSON\", pu.prices() == {\"default\": {\"input\": 1.0, \"output\": 1.0}},\n      pu.prices())\nos.environ.pop(\"OF_AI_PRICES_JSON\", None)\ncheck(\"prices() empty when nothing configured\", pu.prices() == {}, pu.prices())\nplatform_settings.get_setting = _orig_get\ncheck(\"admin panel accepts the price table on the AI engine group\",\n      \"prices_json\" in platform_settings.GROUP_KEYS[\"llm\"], platform_settings.GROUP_KEYS[\"llm\"])\n\n# ---------- usage report ----------\n\nprint(\"== usage report ==\")\nGROUPS = [\n    {\"feature\": \"brain\", \"model\": \"gpt-4o-mini\", \"ok\": True, \"calls\": 10,\n     \"prompt_tokens\": 5000, \"completion_tokens\": 1000, \"avg_latency_ms\": 900},\n    {\"feature\": \"brain\", \"model\": \"gpt-4o-mini\", \"ok\": False, \"calls\": 2,\n     \"prompt_tokens\": 0, \"completion_tokens\": 0, \"avg_latency_ms\": 6000},\n    {\"feature\": \"intent\", \"model\": \"gpt-4o-mini\", \"ok\": True, \"calls\": 30,\n     \"prompt_tokens\": 3000, \"completion_tokens\": 300, \"avg_latency_ms\": 400},\n]\nDAILY = [{\"day\": \"2026-09-27\", \"calls\": 20, \"tokens\": 5000},\n         {\"day\": \"2026-09-28\", \"calls\": 22, \"tokens\": 4300}]\n_orig_prices = pu.prices\npu.prices = lambda: PRICES\nconn = install_db_stub(pu, [GROUPS, DAILY])\nrep = pu.usage_report(conn.cur, 1, 7)\nsql, params = conn.cur.executed[0]\ncheck(\"report SQL: tenant + window, grouped by feature/model/ok\",\n      \"client_id = %s\" in sql and \"make_interval(days => %s)\" in sql\n      and params == (1, 7) and \"GROUP BY feature, model, ok\" in sql\n      and \"GROUP BY DATE(created_at)\" in conn.cur.executed[1][0], sql)\nt = rep[\"totals\"]\ncheck(\"totals: calls/failed/tokens/latency/cost\",\n      t[\"calls\"] == 42 and t[\"failed\"] == 2 and t[\"tokens\"] == 9300\n      and t[\"prompt_tokens\"] == 8000 and t[\"avg_latency_ms\"] == int((9000 + 12000 + 12000) / 42)\n      and t[\"cost_usd\"] == round((8000 * 0.15 + 1300 * 0.6) / 1e6, 4)\n      and t[\"priced\"] is True, t)\ncheck(\"by_feature sorted by calls with labels + cost\",\n      [f[\"feature\"] for f in rep[\"by_feature\"]] == [\"intent\", \"brain\"]\n      and rep[\"by_feature\"][1][\"label\"] == \"AI Brain answers & drafts\"\n      and rep[\"by_feature\"][1][\"failed\"] == 2\n      and rep[\"by_feature\"][0][\"cost_usd\"] == round((3000 * 0.15 + 300 * 0.6) / 1e6, 4),\n      rep[\"by_feature\"])\ncheck(\"by_model + by_day + registry\",\n      rep[\"by_model\"][0][\"model\"] == \"gpt-4o-mini\" and rep[\"by_model\"][0][\"calls\"] == 42\n      and rep[\"by_day\"] == DAILY and rep[\"prices_configured\"] is True\n      and [f[\"key\"] for f in rep[\"features\"]] == list(pu.FEATURE_LABELS), rep[\"by_day\"])\npu.prices = lambda: {}\nconn = install_db_stub(pu, [GROUPS, DAILY])\nrep = pu.usage_report(conn.cur, 1, 7)\ncheck(\"no price table -> cost None, unpriced count, flag false (never a made-up number)\",\n      rep[\"totals\"][\"cost_usd\"] is None and rep[\"totals\"][\"priced\"] is False\n      and rep[\"totals\"][\"unpriced_calls\"] == 42 and rep[\"prices_configured\"] is False\n      and rep[\"by_feature\"][0][\"cost_usd\"] is None, rep[\"totals\"])\npu.prices = lambda: {\"other-model\": {\"input\": 1, \"output\": 1}}\nconn = install_db_stub(pu, [GROUPS, DAILY])\nrep = pu.usage_report(conn.cur, 1, 7)\ncheck(\"partially priced -> totals cost withheld, unpriced calls reported\",\n      rep[\"totals\"][\"cost_usd\"] is None and rep[\"totals\"][\"unpriced_calls\"] == 42, rep[\"totals\"])\nconn = install_db_stub(pu, [[], []])\nrep = pu.usage_report(conn.cur, 1, 999)\ncheck(\"empty window + day clamp\", rep[\"totals\"][\"calls\"] == 0 and rep[\"days\"] == pu.MAX_DAYS\n      and rep[\"totals\"][\"avg_latency_ms\"] == 0, rep)\npu.prices = _orig_prices\n\nr = run_api(pu, [[], []], \"/api/v1/portal/ai/usage?days=30\")\ncheck(\"GET ai/usage 200\", r.status_code == 200 and r.get_json()[\"days\"] == 30, r.get_json())\nr = run_api(pu, [[], []], \"/api/v1/portal/ai/usage\", principal=API_KEY_PRINCIPAL)\ncheck(\"GET ai/usage readable by API keys\", r.status_code == 200, r.status_code)\nr = run_api(pu, [], \"/api/v1/portal/ai/usage\", principal=None)\ncheck(\"GET ai/usage 401\", r.status_code == 401, r.status_code)\n\n# ---------- audit read model ----------\n\nprint(\"== audit ==\")\nfor action, expected in ((\"escalation.opened\", \"handoffs\"), (\"workflow.handoff\", \"handoffs\"),\n                         (\"bot.escalated\", \"handoffs\"), (\"approval.created\", \"approvals\"),\n                         (\"action.create_order\", \"actions\"), (\"workflow.saved\", \"workflows\"),\n                         (\"ai.answer\", \"answers\"), (\"kb.auto_reply\", \"answers\"),\n                         (\"ai.draft\", \"drafts\"), (\"rule_fired\", \"rules\"),\n                         (\"kb.source_ingested\", \"knowledge\"), (\"identity.merged\", \"memory\"),\n                         (\"notifications.settings\", \"notifications\"),\n                         (\"ai.settings\", \"settings\"), (\"message.sent\", \"other\")):\n    check(\"categorize \" + action + \" -> \" + expected, pa.categorize(action) == expected,\n          pa.categorize(action))\ncheck(\"patterns come from the registry (LIKE prefixes)\",\n      \"escalation.%\" in pa._patterns() and \"ai.answer%\" in pa._patterns()\n      and len(pa._patterns()) == sum(len(p) for _k, _l, p in pa.CATEGORIES), \"-\")\n\nLOG = [\n    {\"id\": 9, \"action\": \"ai.answer\", \"actor_kind\": \"automation\", \"actor_user_id\": None,\n     \"conversation_id\": 42, \"note\": \"Brain answered\", \"created_at\": None},\n    {\"id\": 8, \"action\": \"escalation.opened\", \"actor_kind\": \"workflow\", \"actor_user_id\": None,\n     \"conversation_id\": 42, \"note\": \"Workflow handoff\", \"created_at\": None},\n    {\"id\": 7, \"action\": \"kb.source_published\", \"actor_kind\": \"customer_user\",\n     \"actor_user_id\": 11, \"conversation_id\": None, \"note\": \"Published\", \"created_at\": None},\n]\nconn = install_db_stub(pa, [LOG])\nitems = pa.timeline(conn.cur, 1, 7, \"\", 50)\nsql, params = conn.cur.executed[0]\ncheck(\"timeline SQL: tenant + window + (AI actor kinds OR known prefixes), newest first\",\n      \"client_id = %s\" in sql and \"actor_kind = ANY(%s)\" in sql\n      and \"action LIKE ANY(%s)\" in sql and \"ORDER BY id DESC\" in sql\n      and params[0] == 1 and params[1] == 7 and params[2] == list(pa.AI_ACTOR_KINDS)\n      and params[4] == 50, (sql, params))\ncheck(\"timeline items tagged with categories\",\n      [i[\"category\"] for i in items] == [\"answers\", \"handoffs\", \"knowledge\"]\n      and items[2][\"actor_user_id\"] == 11 and items[0][\"conversation_id\"] == 42, items)\nconn = install_db_stub(pa, [LOG])\nitems = pa.timeline(conn.cur, 1, 7, \"handoffs\", 50)\ncheck(\"category filter narrows in Python over a wider fetch\",\n      [i[\"id\"] for i in items] == [8] and conn.cur.executed[0][1][4] == pa.LIST_LIMIT, items)\n\nCOUNTS = [{\"action\": \"ai.answer\", \"actor_kind\": \"automation\", \"n\": 12},\n          {\"action\": \"escalation.opened\", \"actor_kind\": \"automation\", \"n\": 3},\n          {\"action\": \"workflow.completed\", \"actor_kind\": \"workflow\", \"n\": 5},\n          {\"action\": \"zzz.unknown\", \"actor_kind\": \"bot\", \"n\": 1}]\nSUMMARY_ROWS = [{\"open_now\": 2, \"open_high\": 1, \"opened_7d\": 3, \"resolved_7d\": 1,\n                 \"avg_resolve_seconds\": 60.0}]\nimport portal_escalation  # noqa: E402\n\nportal_escalation._DDL_READY = True\npu.prices = lambda: {}\nconn = install_db_stub(pa, [COUNTS,\n                            [], [{\"n\": 4}], [],          # approvals block\n                            [], SUMMARY_ROWS, [], [],    # escalations block\n                            [], [], [], []])             # usage block\nov = pa.overview(conn.cur, 1, 7)\nex = conn.cur.executed\ncats = {c[\"key\"]: c[\"count\"] for c in ov[\"by_category\"]}\ncheck(\"overview counts per category + actor\",\n      ov[\"total\"] == 21 and cats[\"answers\"] == 12 and cats[\"handoffs\"] == 3\n      and cats[\"workflows\"] == 5 and cats[\"other\"] == 1\n      and ov[\"by_actor\"] == {\"automation\": 15, \"workflow\": 5, \"bot\": 1}, ov)\ncheck(\"overview: approvals pending + escalation queue + usage totals (savepoint-guarded)\",\n      ov[\"approvals_pending\"] == 4 and ov[\"escalations\"][\"open\"] == 2\n      and ov[\"usage\"][\"totals\"][\"calls\"] == 0 and ov[\"usage\"][\"prices_configured\"] is False\n      and ex[1][0] == \"SAVEPOINT of_ai_audit\" and ex[3][0] == \"RELEASE SAVEPOINT of_ai_audit\"\n      and \"status = 'pending'\" in ex[2][0], ex)\nconn = install_db_stub(pa, [COUNTS,\n                            [], Exception(\"no approvals table\"), [],\n                            [], SUMMARY_ROWS, [], [],\n                            [], [], [], []])\nov = pa.overview(conn.cur, 1, 7)\ncheck(\"a missing table blanks only its block (ROLLBACK TO SAVEPOINT)\",\n      ov[\"approvals_pending\"] is None and ov[\"escalations\"][\"open\"] == 2\n      and conn.cur.executed[3][0] == \"ROLLBACK TO SAVEPOINT of_ai_audit\", conn.cur.executed[:4])\npu.prices = _orig_prices\n\nr = run_api(pa, [LOG], \"/api/v1/portal/ai/audit?days=7&category=handoffs&limit=20\")\nbody = r.get_json()\ncheck(\"GET ai/audit 200 with categories registry\", r.status_code == 200\n      and body[\"category\"] == \"handoffs\" and [i[\"id\"] for i in body[\"items\"]] == [8]\n      and body[\"categories\"][0][\"key\"] == \"handoffs\", body)\nr = run_api(pa, [], \"/api/v1/portal/ai/audit?category=bogus\")\ncheck(\"GET ai/audit 400 unknown category\", r.status_code == 400, r.status_code)\nr = run_api(pa, [COUNTS, [], [{\"n\": 0}], [], [], SUMMARY_ROWS, [], [], [], [], [], []],\n            \"/api/v1/portal/ai/overview\", principal=API_KEY_PRINCIPAL)\ncheck(\"GET ai/overview 200 (API keys read-only ok)\", r.status_code == 200\n      and r.get_json()[\"total\"] == 21, r.status_code)\nr = run_api(pa, [], \"/api/v1/portal/ai/overview\", principal=None)\ncheck(\"GET ai/overview 401\", r.status_code == 401, r.status_code)\n\n# ---------- wiring pins ----------\n\nprint(\"== wiring pins ==\")\nHERE = os.path.dirname(os.path.abspath(__file__))\nCP = os.path.join(HERE, \"..\", \"..\", \"omniflow-backend-patch\")\nRIG13 = \"/tmp/p13/Omniflow/\"\n\n\ndef read(path):\n    return open(path, encoding=\"utf8\").read() if os.path.exists(path) else \"\"\n\n\nAPP = read(os.path.join(CP, \"app.py\"))\ncheck(\"blueprints registered\", \"aux_app.register_blueprint(portal_ai_usage_bp)\" in APP\n      and \"aux_app.register_blueprint(portal_ai_audit_bp)\" in APP, \"-\")\nfor module, feature in ((\"portal_brain.py\", '\"brain\", client_id, cur'),\n                        (\"portal_workflows.py\", '\"workflow\", client_id, cur'),\n                        (\"portal_recovery.py\", '\"negotiation\", client_id, cur'),\n                        (\"portal_recovery.py\", '\"copy\", client_id, cur'),\n                        (\"connector_api.py\", '\"intent\", tenant[\"client_id\"]'),\n                        (\"portal_insights.py\", '\"sentiment\"')):\n    check(\"usage scope at \" + module + \" \" + feature.split(\",\")[0],\n          \"portal_llm.usage_scope(\" in read(os.path.join(CP, module))\n          and feature in read(os.path.join(CP, module)), module)\nLLM = read(os.path.join(CP, \"portal_llm.py\"))\ncheck(\"chat_json signature unchanged (stubs keep working), hook inside\",\n      \"def chat_json(system: str, user: str,\\n              max_tokens: int = 120)\" in LLM\n      and \"_record_usage(model, last_usage, True, started)\" in LLM, \"-\")\ncheck(\"no hardcoded prices anywhere\", \"0.15\" not in read(pu.__file__).replace(\n    '\"gpt-4o-mini\": {\"input\": 0.15, \"output\": 0.60}', \"\"), \"-\")\n\nLIB = read(RIG13 + \"lib/omniflow/portal.ts\")\ncheck(\"portal.ts AI ops client\", all(t in LIB for t in (\n    \"export async function getAiUsage\", \"export async function getAiAudit\",\n    \"export async function getAiOverview\", '\"api/v1/portal/ai/usage?days=\"',\n    '\"api/v1/portal/ai/overview?days=\"')), \"-\")\nfor rel, fn in ((\"ai/usage/route.ts\", \"getAiUsage\"), (\"ai/audit/route.ts\", \"getAiAudit\"),\n                (\"ai/overview/route.ts\", \"getAiOverview\")):\n    src = read(RIG13 + \"app/api/omniflow/portal/\" + rel)\n    check(\"BFF \" + rel, bool(src) and fn in src and \"export async function GET\" in src\n          and ('\"' + \"../\" * 6 + 'lib/omniflow/portal\"') in src, rel)\nCARD = read(RIG13 + \"app/dashboard/(portal)/bot/AiOpsCard.tsx\")\ncheck(\"AI operations card: overview counts, usage by feature, cost honesty, audit timeline\",\n      all(t in CARD for t in (\"/api/omniflow/portal/ai/overview\", \"/api/omniflow/portal/ai/usage\",\n                              \"/api/omniflow/portal/ai/audit\", \"by_feature\", \"prices_configured\",\n                              \"not configured\", \"by_category\", \"approvals_pending\")), \"-\")\ncheck(\"AI operations card mounted on Configure AI\", \"<AiOpsCard />\" in read(\n    RIG13 + \"app/dashboard/(portal)/bot/page.tsx\"), \"-\")\nADMIN = read(RIG13 + \"app/admin/(panel)/integrations/IntegrationsClient.tsx\")\ncheck(\"admin AI engine group has the model-prices field\", 'key: \"prices_json\"' in ADMIN, \"-\")\ncheck(\"UI copy English + text glyphs\", \"karein\" not in CARD and \"\\\\u25b6\" not in CARD\n      and \"\\\\u2714\" not in CARD, \"-\")\n\nraise SystemExit(1 if summary(\"ai_ops\") else 0)\n");

writeNewRepair("tools/cp-testrig/test_alerts.py", "eck(\"app.py registers alerts bp\",\n      \"aux_app.register_blueprint(portal_alerts_bp)\" in APP, \"bp\")\n\nsummary(\"alerts\")", false,
    "\"\"\"Tests for B5: portal_alerts (raise/dedupe/dead-command/settings/API)\n+ portal_events wiring + web pins (bell, brief blocks, clients).\"\"\"\nimport json\n\nfrom flask import Flask\n\nimport portal_alerts\nimport portal_events\nimport portal_db\nfrom test_lib import install_db_stub\nfrom test_lib import check, summary\n\nPRINCIPAL = {\n    \"session_id\": \"s\", \"user_id\": 11, \"client_id\": 1, \"role\": \"owner\",\n    \"email\": \"ahmed@example.com\", \"display_name\": \"Ahmed\",\n    \"via_api_key\": False,\n}\n\n\nclass PrincipalStub:\n    def __init__(self, module, principal):\n        self.module = module\n        self.principal = principal\n\n    def __enter__(self):\n        self.orig = self.module.authenticate_portal_request\n        self.module.authenticate_portal_request = lambda: self.principal\n        self.module.PortalAuthUnavailable = Exception\n        return self\n\n    def __exit__(self, *a):\n        self.module.authenticate_portal_request = self.orig\n\n\ndef fresh(script, module=portal_alerts):\n    portal_alerts._DDL_READY = True\n    db = install_db_stub(module, script)\n    portal_alerts.portal_db.CMD_TABLE = \"portal_connector_commands\"\n    return db\n\n\ndef reset():\n    portal_alerts.ALERTS_ENABLED = True\n    portal_alerts._DDL_READY = True\n\n\n# ---------- raise_alert: insert, dedupe, kill switches ----------\n\nreset()\nconn = fresh([[{\"enabled\": True}], [], [{\"id\": 41}]])\nwith conn.cur as cur:\n    aid = portal_alerts.raise_alert(\n        cur, 1, \"delivery_dead\", \"Delivery failed: cod_confirm #7\",\n        \"gateway down\", \"revenue\", dedupe_key=\"cmd:7\")\nsqls = [s for s, p in conn.cur.executed]\ncheck(\"raise inserts alert\",\n      any(\"INSERT INTO portal_alerts\" in s for s in sqls) and aid == 41,\n      (aid, sqls[:1]))\ncheck(\"severity stored\", json.dumps(\n    [p for s, p in conn.cur.executed if \"INSERT\" in s][0]).count(\n    \"revenue\") == 1, \"severity param\")\n\nconn = fresh([[{\"enabled\": True}], [{\"id\": 9}]])\nwith conn.cur as cur:\n    aid = portal_alerts.raise_alert(\n        cur, 1, \"delivery_dead\", \"dup\", \"\", \"normal\", dedupe_key=\"cmd:7\")\ncheck(\"dedupe suppresses unread duplicate\", aid is None, aid)\n\nconn = fresh([[{\"enabled\": True}], [], [{\"id\": 42}]])\nwith conn.cur as cur:\n    aid = portal_alerts.raise_alert(\n        cur, 1, \"delivery_dead\", \"again\", \"\", \"normal\", dedupe_key=\"cmd:7\")\ncheck(\"after read, same key alerts again\", aid == 42, aid)\n\nportal_alerts.ALERTS_ENABLED = False\nconn = fresh([])\nwith conn.cur as cur:\n    aid = portal_alerts.raise_alert(cur, 1, \"k\", \"t\")\ncheck(\"env kill switch silences\", aid is None, aid)\nportal_alerts.ALERTS_ENABLED = True\n\n# per-tenant toggle: enabled row FALSE suppresses; missing row = on\nconn = fresh([[{\"enabled\": False}]])\nwith conn.cur as cur:\n    check(\"tenant off -> alerts_on False\",\n          portal_alerts.alerts_on(cur, 1) is False, \"off\")\nconn = fresh([[]])\nwith conn.cur as cur:\n    check(\"missing settings row -> on\",\n          portal_alerts.alerts_on(cur, 1) is True, \"on\")\nconn = fresh([[{\"enabled\": True}], [{\"id\": 43}]])\nwith conn.cur as cur:\n    check(\"tenant on -> alert raised\",\n          portal_alerts.raise_alert(cur, 1, \"k\", \"t\") == 43, \"43\")\n\n# fail-silent: db error -> None, never raises\nconn = fresh([RuntimeError(\"db down\")])\nwith conn.cur as cur:\n    check(\"raise fails silent\",\n          portal_alerts.raise_alert(cur, 1, \"k\", \"t\") is None, \"None\")\n\n# ---------- alert_dead_command: dead-only + severity by action ----------\n\nDEAD_REVENUE = {\"action\": \"cod_confirm\", \"status\": \"dead\",\n                \"error_message\": \"max_attempts\"}\nDEAD_PLAIN = {\"action\": \"send_message\", \"status\": \"dead\",\n              \"error_message\": \"no route\"}\nRETRYING = {\"action\": \"cod_confirm\", \"status\": \"failed\",\n            \"error_message\": \"gateway 500\"}\n\nconn = fresh([[DEAD_REVENUE], [{\"enabled\": True}], [], [{\"id\": 50}]])\nconn.CMD_TABLE = \"portal_connector_commands\"\nwith conn.cur as cur:\n    aid = portal_alerts.alert_dead_command(cur, 1, 7, \"gateway down\")\ncheck(\"dead revenue command alerts\", aid == 50, aid)\nins_params = [p for s, p in conn.cur.executed if \"INSERT\" in s][0]\ncheck(\"revenue severity for cod action\", \"revenue\" in str(ins_params),\n      ins_params)\n\nconn = fresh([[DEAD_PLAIN], [{\"enabled\": True}], [], [{\"id\": 51}]])\nconn.CMD_TABLE = \"portal_connector_commands\"\nwith conn.cur as cur:\n    aid = portal_alerts.alert_dead_command(cur, 1, 8, \"\")\ncheck(\"plain action alerts too\", aid == 51, aid)\nins_params = [p for s, p in conn.cur.executed if \"INSERT\" in s][0]\ncheck(\"normal severity for plain action\", \"revenue\" not in str(ins_params),\n      ins_params)\n\nconn = fresh([[RETRYING]])\nconn.CMD_TABLE = \"portal_connector_commands\"\nwith conn.cur as cur:\n    aid = portal_alerts.alert_dead_command(cur, 1, 9, \"\")\ncheck(\"retrying failure does not alert\", aid is None, aid)\n\n# ---------- unread_count ----------\n\nconn = fresh([[{\"n\": 4}]])\nwith conn.cur as cur:\n    check(\"unread count\", portal_alerts.unread_count(cur, 1) == 4, 4)\nconn = fresh([RuntimeError(\"x\")])\nwith conn.cur as cur:\n    check(\"unread fails to 0\", portal_alerts.unread_count(cur, 1) == 0, 0)\n\n# ---------- owner API ----------\n\napp = Flask(\"alerts-test\")\napp.register_blueprint(portal_alerts.bp)\nclient = app.test_client()\n\nALERT_ROW = {\"id\": 60, \"kind\": \"delivery_dead\", \"dedupe_key\": \"cmd:3\",\n             \"severity\": \"revenue\", \"title\": \"Delivery failed\",\n             \"detail\": \"gateway down\", \"is_read\": False,\n             \"created_at\": None}\nconn = fresh([[ALERT_ROW], [{\"n\": 1}]])\nwith PrincipalStub(portal_alerts, PRINCIPAL):\n    r = client.get(\"/api/v1/portal/alerts\")\ncheck(\"list 200\", r.status_code == 200, r.status_code)\ncheck(\"list payload\", r.get_json()[\"alerts\"][0][\"id\"] == 60\n      and r.get_json()[\"unread\"] == 1, r.get_json())\ncheck(\"iso tolerant of None\", r.get_json()[\"alerts\"][0][\"created_at\"]\n      is None, \"null ok\")\n\nwith PrincipalStub(portal_alerts, {\"via_api_key\": True}):\n    r = client.get(\"/api/v1/portal/alerts\")\ncheck(\"api key forbidden\", r.status_code == 403, r.status_code)\nwith PrincipalStub(portal_alerts, None):\n    r = client.get(\"/api/v1/portal/alerts\")\ncheck(\"anon 401\", r.status_code == 401, r.status_code)\n\nconn = fresh([[]])\nwith PrincipalStub(portal_alerts, PRINCIPAL):\n    r_all = client.post(\"/api/omniflow/portal/alerts/read\".replace(\n        \"/api/omniflow\", \"/api/v1\"), json={\"all\": True})\ncheck(\"mark all read 200\", r_all.status_code == 200, r_all.status_code)\ncheck(\"mark all sql\", any(\"SET is_read = TRUE\" in s\n                          and \"is_read = FALSE\" in s\n                          for s, p in conn.cur.executed), \"bulk\")\n\nconn = fresh([[{\"id\": 61}]])\nwith PrincipalStub(portal_alerts, PRINCIPAL):\n    r_one = client.post(\"/api/v1/portal/alerts/read\", json={\"id\": 61})\ncheck(\"mark one 200\", r_one.status_code == 200, r_one.status_code)\nwith PrincipalStub(portal_alerts, PRINCIPAL):\n    r_bad = client.post(\"/api/v1/portal/alerts/read\", json={})\ncheck(\"mark read 400 without id/all\", r_bad.status_code == 400,\n      r_bad.status_code)\n\nconn = fresh([[]])\nwith PrincipalStub(portal_alerts, PRINCIPAL):\n    r_set = client.put(\"/api/v1/portal/alerts/settings\",\n                       json={\"enabled\": False})\ncheck(\"settings put 200\", r_set.status_code == 200, r_set.status_code)\ncheck(\"settings upsert sql\", any(\"ON CONFLICT (client_id)\" in s\n                                 for s, p in conn.cur.executed), \"upsert\")\nwith PrincipalStub(portal_alerts, PRINCIPAL):\n    r_bad = client.put(\"/api/v1/portal/alerts/settings\", json={})\ncheck(\"settings 400 without bool\", r_bad.status_code == 400,\n      r_bad.status_code)\nconn = fresh([[{\"enabled\": True}]])\nwith PrincipalStub(portal_alerts, PRINCIPAL):\n    r_get = client.get(\"/api/v1/portal/alerts/settings\")\ncheck(\"settings get 200 default true\",\n      r_get.get_json()[\"settings\"][\"enabled\"] is True, r_get.get_json())\n\n# ---------- portal_events wiring ----------\n\nEV = open(\"/tmp/smoke971/portal_events.py\", encoding=\"utf8\").read()\ncheck(\"events raises dead alerts\",\n      \"portal_alerts.alert_dead_command(\" in EV\n      and \"import portal_alerts\" in EV, \"wire\")\ncheck(\"events alert call after dead-marking\",\n      EV.index(\"portal_alerts.alert_dead_command(\")\n      > EV.index(\"MAX_ATTEMPTS, note, MAX_ATTEMPTS, MAX_ATTEMPTS,\"))\n\n# ---------- web pins ----------\n\nPORTAL = open(\"/tmp/p13/Omniflow/lib/omniflow/portal.ts\",\n              encoding=\"utf8\").read()\nfor fn in (\"listAlerts\", \"markAlertsRead\", \"putAlertSettings\"):\n    check(\"client \" + fn, \"export async function \" + fn in PORTAL, fn)\nBELL = open(\"/tmp/p13/Omniflow/app/dashboard/components/AlertsBell.tsx\",\n            encoding=\"utf8\").read()\ncheck(\"bell fetches alerts\",\n      '\"/api/omniflow/portal/alerts\"' in BELL\n      and \"unread\" in BELL, \"bell\")\ncheck(\"bell settings toggle\", \"alerts/settings\" in BELL, \"toggle\")\nSIDEBAR = open(\"/tmp/p13/Omniflow/app/dashboard/components/DashSidebar.tsx\",\n               encoding=\"utf8\").read()\ncheck(\"sidebar mounts bell\", '<AlertsBell />' in SIDEBAR, \"mount\")\nBRIEF = open(\"/tmp/p13/Omniflow/app/dashboard/(portal)/DailyBrief.tsx\",\n             encoding=\"utf8\").read()\ncheck(\"brief needs-attention block\", \"Needs attention\" in BRIEF, \"block\")\ncheck(\"brief recommended block\", \"Recommended:\" in BRIEF, \"block\")\ncheck(\"brief reads alerts+deliveries\",\n      '\"/api/omniflow/portal/alerts\"' in BRIEF\n      and '\"/api/omniflow/portal/deliveries\"' in BRIEF, \"sources\")\nfor route in (\"app/api/omniflow/portal/alerts/route.ts\",\n              \"app/api/omniflow/portal/alerts/read/route.ts\",\n              \"app/api/omniflow/portal/alerts/settings/route.ts\"):\n    src = open(\"/tmp/p13/Omniflow/\" + route, encoding=\"utf8\").read()\n    check(\"bff \" + route.split(\"/\")[-2] + \"/\" + route.split(\"/\")[-1],\n          \"export async function\" in src, route)\nAPP = open(\"/tmp/smoke971/app.py\", encoding=\"utf8\").read()\ncheck(\"app.py registers alerts bp\",\n      \"aux_app.register_blueprint(portal_alerts_bp)\" in APP, \"bp\")\n\nsummary(\"alerts\")\n");

writeNewRepair("tools/cp-testrig/test_analytics.py", "s anon 401\", status(resp) == 401, status(resp))\nPrincipalStub(portal_analytics, principal=human)\n\nsummary(\"operations\")", false,
    "\"\"\"Tests for commerce analytics: per-customer orders/spend/tiers and\nproduct-wise aggregation over PAID links only.\"\"\"\nfrom datetime import datetime, timezone\n\nfrom flask import Flask\n\nimport portal_analytics\nimport portal_checkout\nimport test_lib\nfrom test_lib import check, install_db_stub, PrincipalStub, status, summary\n\napp = Flask(__name__)\napp.register_blueprint(portal_analytics.bp)\nclient = app.test_client()\n\nhuman = {\n    \"session_id\": \"s\", \"user_id\": 11, \"client_id\": 1, \"role\": \"owner\",\n    \"email\": \"ahmed@example.com\", \"display_name\": \"Ahmed\", \"via_api_key\": False,\n}\nPrincipalStub(portal_analytics, principal=human)\n\n\ndef fresh(rows):\n    portal_checkout._CHECKOUT_DDL_READY = True\n    db = install_db_stub(portal_analytics, [rows])\n    db.CONV_TABLE = \"portal_conversations\"\n    db.CMD_TABLE = \"portal_commands\"\n    return db\n\n\ndef fresh2(rows, lang_rows):\n    \"\"\"991-1010: customer-analytics runs a second (language) query.\"\"\"\n    portal_checkout._CHECKOUT_DDL_READY = True\n    db = install_db_stub(portal_analytics, [rows, lang_rows])\n    db.CONV_TABLE = \"portal_conversations\"\n    db.CMD_TABLE = \"portal_commands\"\n    return db\n\n\ndef link(contact, total, items, status=\"paid\",\n         created=datetime(2026, 9, 19, 10, 0, tzinfo=timezone.utc)):\n    return {\"id\": 1, \"contact_id\": contact, \"title\": \"T\", \"items\": items,\n            \"total\": total, \"paid_amount\": 0, \"discount\": 0,\n            \"status\": status, \"created_at\": created}\n\n\nprint(\"== tiers ==\")\n\n# 991-1010: customer-analytics gains a language-distribution query\n# (slot 2) - one row per detected language, count DESC.\nfresh2([link(\"92a\", 5000, [])],\n       [{\"lang\": \"ur\", \"n\": 12}, {\"lang\": \"roman\", \"n\": 7}])\nresponse = client.get(\"/api/v1/portal/insights/customer-analytics\")\npayload = response.get_json()\ncheck(\"200 customers\", status(response) == 200\n      and payload[\"customers\"][0][\"tier\"] == \"new\"\n      and payload[\"repeat_share\"] == 0, payload.get(\"tiers\"))\ncheck(\"languages payload\", payload[\"languages\"] == [\n      {\"lang\": \"ur\", \"count\": 12}, {\"lang\": \"roman\", \"count\": 7}],\n      payload.get(\"languages\"))\n\nfresh2([link(\"92a\", 5000, []), link(\"92a\", 7000, []),\n        link(\"92b\", 30000, []), link(\"92c\", 100, [])], [])\npayload = client.get(\"/api/v1/portal/insights/customer-analytics\").get_json()\nby = {c[\"contact_id\"]: c for c in payload[\"customers\"]}\ncheck(\"repeat tier\", by[\"92a\"][\"tier\"] == \"repeat\"\n      and by[\"92a\"][\"orders\"] == 2 and by[\"92a\"][\"spend\"] == 12000\n      and by[\"92a\"][\"avg_order\"] == 6000, by.get(\"92a\"))\ncheck(\"vip by spend\", by[\"92b\"][\"tier\"] == \"vip\", by.get(\"92b\"))\ncheck(\"vip by orders\", by[\"92c\"][\"tier\"] == \"new\", by.get(\"92c\"))\ncheck(\"tiers summary\", payload[\"tiers\"] == {\"new\": 1, \"repeat\": 1, \"vip\": 1},\n      payload[\"tiers\"])\ncheck(\"repeat share\", payload[\"repeat_share\"] == 0.67,\n      payload[\"repeat_share\"])\ncheck(\"sorted by spend\", payload[\"customers\"][0][\"contact_id\"] == \"92b\",\n      payload[\"customers\"][0])\n\nfresh2([link(\"92a\", 5000, [], created=datetime(\n            2026, 9, 1, 10, 0, tzinfo=timezone.utc)),\n        link(\"92a\", 7000, [], created=datetime(\n            2026, 9, 19, 10, 0, tzinfo=timezone.utc))], [])\npayload = client.get(\"/api/v1/portal/insights/customer-analytics\").get_json()\ncheck(\"last order max\", payload[\"customers\"][0][\"last_order\"].startswith(\n      \"2026-09-19\"), payload[\"customers\"][0][\"last_order\"])\n\nfresh([])\npayload = client.get(\"/api/v1/portal/insights/customer-analytics\").get_json()\ncheck(\"paid only\", payload[\"customers\"] == [], payload[\"customers\"])\n\nprint(\"== products ==\")\n\nITEMS_A = [{\"name\": \"Kurti\", \"qty\": 2, \"price\": 1000},\n           {\"name\": \"Shawl\", \"qty\": 1, \"price\": 1500}]\nITEMS_B = [{\"name\": \"Kurti\", \"qty\": 1, \"price\": 1000}]\nfresh([link(\"92a\", 3500, ITEMS_A), link(\"92b\", 1000, ITEMS_B)])\npayload = client.get(\"/api/v1/portal/insights/product-analytics\").get_json()\nprods = {p[\"name\"]: p for p in payload[\"products\"]}\ncheck(\"product agg\", prods[\"Kurti\"][\"qty_sold\"] == 3\n      and prods[\"Kurti\"][\"revenue\"] == 3000 and prods[\"Kurti\"][\"orders\"] == 2,\n      prods.get(\"Kurti\"))\ncheck(\"product single\", prods[\"Shawl\"][\"revenue\"] == 1500\n      and prods[\"Shawl\"][\"orders\"] == 1, prods.get(\"Shawl\"))\ncheck(\"sorted by revenue\", payload[\"products\"][0][\"name\"] == \"Kurti\",\n      payload[\"products\"][0])\n\nprint(\"== params + errors ==\")\n\nfresh([])\npayload = client.get(\n    \"/api/v1/portal/insights/customer-analytics?days=90\").get_json()\ncheck(\"days parsed\", payload[\"days\"] == 90, payload.get(\"days\"))\nfresh([])\npayload = client.get(\n    \"/api/v1/portal/insights/customer-analytics?days=bogus\").get_json()\ncheck(\"days default 30\", payload[\"days\"] == 30, payload.get(\"days\"))\n\nfresh([RuntimeError(\"db down\")])\nresponse = client.get(\"/api/v1/portal/insights/customer-analytics\")\ncheck(\"503 on failure\", status(response) == 503, status(response))\n\nsummary(\"analytics\")\n\n\nprint(\"== operations aggregate (B14) ==\")\n\n# 11 scripted result sets, in query order: chats.new, chats.open,\n# chats.total, messages.received, messages.sent, orders(n+revenue),\n# deliveries.bookings, by_status, recovery.open, recovery.resolved,\n# csat(avg+n).\n_ops = install_db_stub(portal_analytics, [\n    [{\"n\": 5}],            # chats new\n    [{\"n\": 2}],            # chats open\n    [{\"n\": 9}],            # chats total\n    [{\"n\": 40}],           # messages received\n    [{\"n\": 33}],           # messages sent\n    [{\"n\": 3, \"revenue\": 7500.5}],   # paid orders\n    [{\"n\": 3}],            # bookings\n    [{\"status\": \"booked\", \"n\": 2}, {\"status\": \"delivered\", \"n\": 1}],\n    [{\"n\": 1}],            # recovery open\n    [{\"n\": 4}],            # recovery resolved\n    [{\"avg_score\": 4.456, \"n\": 6}],  # csat\n])\n_ops.CONV_TABLE = \"portal_conversations\"\n_ops.MSGS_TABLE = \"portal_messages\"\n_ops.CSAT_TABLE = \"portal_csat_requests\"\npayload = client.get(\"/api/v1/portal/insights/operations\").get_json()\nops = payload.get(\"operations\", {})\ncheck(\"operations chats\", ops.get(\"chats\") == {\"new\": 5, \"open\": 2,\n                                               \"total\": 9}, ops.get(\"chats\"))\ncheck(\"operations messages\", ops.get(\"messages\")\n      == {\"received\": 40, \"sent\": 33}, ops.get(\"messages\"))\ncheck(\"operations orders\", ops.get(\"orders\") == {\"paid\": 3,\n                                                 \"revenue\": 7500.5},\n      ops.get(\"orders\"))\ncheck(\"operations deliveries\", ops.get(\"deliveries\", {}).get(\"bookings\")\n      == 3 and ops.get(\"deliveries\", {}).get(\"by_status\", {})\n      .get(\"delivered\") == 1, ops.get(\"deliveries\"))\ncheck(\"operations recovery\", ops.get(\"recovery\") == {\"open\": 1,\n                                                     \"resolved\": 4},\n      ops.get(\"recovery\"))\ncheck(\"operations csat rounded\", ops.get(\"csat\") == {\"answers\": 6,\n                                                     \"avg_score\": 4.46},\n      ops.get(\"csat\"))\ncheck(\"operations days default\", payload.get(\"days\") == 30,\n      payload.get(\"days\"))\ncheck(\"operations queried bookings+csat tables\", any(\n    \"portal_courier_bookings\" in e[0] for e in _ops.cur.executed)\n    and any(\"portal_csat_requests\" in e[0]\n            for e in _ops.cur.executed), \"tables\")\n\n# days clamp: bogus -> 30, huge -> 365\n_zero = [[{\"n\": 0}], [{\"n\": 0}], [{\"n\": 0}], [{\"n\": 0}], [{\"n\": 0}],\n         [{\"n\": 0, \"revenue\": 0}], [{\"n\": 0}], [], [{\"n\": 0}],\n         [{\"n\": 0}], [{\"avg_score\": None, \"n\": 0}]]\n_ops2 = install_db_stub(portal_analytics, list(_zero))\n_ops2.CONV_TABLE = \"portal_conversations\"\n_ops2.MSGS_TABLE = \"portal_messages\"\n_ops2.CSAT_TABLE = \"portal_csat_requests\"\np2 = client.get(\"/api/v1/portal/insights/operations?days=bogus\").get_json()\ncheck(\"operations days bogus\", p2.get(\"days\") == 30, p2.get(\"days\"))\n_ops3 = install_db_stub(portal_analytics, list(_zero))\n_ops3.CONV_TABLE = \"portal_conversations\"\n_ops3.MSGS_TABLE = \"portal_messages\"\n_ops3.CSAT_TABLE = \"portal_csat_requests\"\np3 = client.get(\"/api/v1/portal/insights/operations?days=9999\").get_json()\ncheck(\"operations days clamp\", p3.get(\"days\") == 365, p3.get(\"days\"))\ncheck(\"operations empty csat\", p3.get(\"operations\", {}).get(\"csat\")\n      == {\"answers\": 0, \"avg_score\": None},\n      p3.get(\"operations\", {}).get(\"csat\"))\n\n# api-key principals read analytics like the other insight endpoints\nPrincipalStub(portal_analytics, principal=dict(human, via_api_key=True))\n_ops4 = install_db_stub(portal_analytics, list(_zero))\n_ops4.CONV_TABLE = \"portal_conversations\"\n_ops4.MSGS_TABLE = \"portal_messages\"\n_ops4.CSAT_TABLE = \"portal_csat_requests\"\nresp = client.get(\"/api/v1/portal/insights/operations\")\ncheck(\"operations api key 200\", status(resp) == 200, status(resp))\nPrincipalStub(portal_analytics, principal=None)\nresp = client.get(\"/api/v1/portal/insights/operations\")\ncheck(\"operations anon 401\", status(resp) == 401, status(resp))\nPrincipalStub(portal_analytics, principal=human)\n\nsummary(\"operations\")\n");

writeNewRepair("tools/cp-testrig/test_approvals.py", "deApproval\" in PORTAL\n      and \"export async function saveApprovalsConfig\" in PORTAL, \"helpers\")\n\nsummary(\"approvals\")", false,
    "\"\"\"Master-upgrade D3: the approvals engine.\n\nCovers portal_approvals end to end on stubs: create_approval (dup\nguard, ref code, owner WhatsApp command queued with the 1/0 instructions),\nmaybe_request keyword detection (refund / cancel / discount, in only),\nmaybe_decide (owner-only 1/0, single-pending decide, code pick with\nmultiple pending, hint message, rowcount guard, wrong sender ignored),\nthe portal APIs (list with lazy expiry, decide 200/401/404, config\nGET/PUT with the owner-role check) and the web surface pins (connector\nhook order, BFF routes, portal.ts helpers, sidebar + page).\n\"\"\"\nimport json\n\nfrom flask import Flask\n\nimport portal_approvals\nfrom test_lib import FakeConn, FakeCur\nfrom test_lib import install_db_stub\nfrom test_lib import check, summary\nfrom test_lib import PrincipalStub\n\n\nclass Principal:\n    \"\"\"CM wrapper — test_lib's PrincipalStub has no __enter__.\"\"\"\n\n    def __init__(self, module, principal=None, exc=None):\n        self.stub = PrincipalStub(module, principal, exc)\n\n    def __enter__(self):\n        return self\n\n    def __exit__(self, *args):\n        self.stub.restore()\n        return False\n\n\nPRINCIPAL = {\n    \"session_id\": \"s\", \"user_id\": 11, \"client_id\": 1, \"role\": \"owner\",\n    \"email\": \"ahmed@example.com\", \"display_name\": \"Ahmed\",\n    \"via_api_key\": False,\n}\n\nCONFIG_ROW = [{\"approval_number\": \"9230012345678\",\n               \"auto_expire_hours\": 24}]\nSTATUS_ROW = [{\"phone\": \"92 300 999 8888\"}]\n\napp = Flask(__name__)\napp.register_blueprint(portal_approvals.bp)\nclient = app.test_client()\n\n\ndef _sender_queue_params(conn):\n    for sql, params in conn.cur.executed:\n        if \"portal_connector_commands\" in sql:\n            return params\n    return None\n\n\nprint(\"== create_approval: dup guard, ref, owner WhatsApp ==\")\n\nconn = install_db_stub(portal_approvals, [\n    [], [], [],                              # lazy DDL x3\n    [],                                      # dup pending SELECT -> none\n    CONFIG_ROW,                              # load config\n    [{\"id\": 55}],                            # INSERT approval RETURNING id\n    CONFIG_ROW,                              # approver: config again\n    STATUS_ROW,                              # approver: connector phone\n    [],                                      # queue owner WhatsApp send\n    [],                                      # audit\n])\nmade = portal_approvals.create_approval(\n    conn.cursor(), 1, 77, \"923008887777@c.us\", \"Ahmed Raza\",\n    \"refund\", \"Refund request — owner ki tasdeeq chahiye\",\n    \"Mera order kharab aya hai, refund chahiye\",\n    {\"detected_from\": \"inbound_message\"})\ncheck(\"create returns row\", made is not None and made[\"id\"] == 55\n      and made[\"ref_code\"].startswith(\"AP-\"), made)\nsend_params = _sender_queue_params(conn)\ncheck(\"owner whatsapp queued\", send_params is not None\n      and json.loads(send_params[1])[\"external_user_id\"]\n      == \"9230012345678@c.us\", send_params)\ncheck(\"whatsapp body has 1/0 + ref\",\n      \"1 = approve\" in json.loads(send_params[1])[\"body\"]\n      and made[\"ref_code\"] in json.loads(send_params[1])[\"body\"],\n      json.loads(send_params[1])[\"body\"])\ncheck(\"audit written\", any(\"portal_action_log\" in sql\n                           for sql, _p in conn.cur.executed), \"audit\")\n\nconn = install_db_stub(portal_approvals, [\n    [], [], [],                              # lazy DDL\n    [{\"id\": 9, \"ref_code\": \"AP-AAAA\"}],      # dup pending exists\n])\ndup = portal_approvals.create_approval(\n    conn.cursor(), 1, 77, \"923008887777@c.us\", \"Ahmed\", \"refund\",\n    \"dup\", \"x\", None)\ncheck(\"duplicate pending skipped\", dup is None, dup)\n\nprint(\"== maybe_request: keyword producer ==\")\n\nconn = install_db_stub(portal_approvals, [])\ncheck(\"plain message ignored\",\n      portal_approvals.maybe_request(\n          1, 77, \"923008887777@c.us\", \"Ahmed\",\n          \"Salam, ye hoodie kis size me hai?\", \"in\", conn) is False,\n      \"plain\")\nconn = install_db_stub(portal_approvals, [])\ncheck(\"outbound ignored\",\n      portal_approvals.maybe_request(\n          1, 77, \"923008887777@c.us\", \"Ahmed\", \"refund chahiye\",\n          \"out\", conn) is False, \"out\")\n\nconn = install_db_stub(portal_approvals, [\n    [], [], [],\n    [],\n    CONFIG_ROW,\n    [{\"id\": 56}],\n    CONFIG_ROW,\n    STATUS_ROW,\n    [],\n    [],\n])\ncheck(\"refund request creates approval\",\n      portal_approvals.maybe_request(\n          1, 77, \"923008887777@c.us\", \"Ahmed\",\n          \"Bhai mera order kharab aya hai refund chahiye\", \"in\",\n          conn) is True, \"refund\")\n\nprint(\"== maybe_decide: the WhatsApp 1/0 loop ==\")\n\nconn = install_db_stub(portal_approvals, [])\ncheck(\"non-decision ignored\",\n      portal_approvals.maybe_decide(\n          1, 77, \"9230012345678@c.us\", \"salam\", \"in\", conn) is False,\n      \"salam\")\n\nconn = install_db_stub(portal_approvals, [CONFIG_ROW, STATUS_ROW])\ncheck(\"stranger 1 ignored\",\n      portal_approvals.maybe_decide(\n          1, 77, \"923005555555@c.us\", \"1\", \"in\", conn) is False,\n      \"stranger\")\n\n# self-chat number also allowed\nconn = install_db_stub(portal_approvals, [\n    [{\"approval_number\": \"\", \"auto_expire_hours\": 24}],  # no configured owner\n    STATUS_ROW,                              # connector self number\n    [{\"id\": 55, \"ref_code\": \"AP-AB12\"}],     # one pending\n    1,                                       # UPDATE decided\n    [{\"id\": 55, \"ref_code\": \"AP-AB12\", \"context_json\": None}],  # resolve seam\n    [],                                      # audit\n    [],                                      # confirmation send\n])\ncheck(\"self-chat 1 approves\",\n      portal_approvals.maybe_decide(\n          1, 77, \"923009998888@c.us\", \"1\", \"in\", conn) is True,\n      \"self\")\nupdate = next((p for sql, p in conn.cur.executed\n               if \"UPDATE portal_approvals\" in sql), None)\ncheck(\"approve update params\", update is not None\n      and update[0] == \"approved\" and update[1] == \"923009998888\"\n      and update[2] == \"whatsapp\", update)\n\n# multiple pending, no code -> hint\nconn = install_db_stub(portal_approvals, [\n    CONFIG_ROW, STATUS_ROW,\n    [{\"id\": 55, \"ref_code\": \"AP-AB12\"},\n     {\"id\": 56, \"ref_code\": \"AP-CD34\"}],\n    [],                                      # hint send\n])\ncheck(\"multiple pending asks for code\",\n      portal_approvals.maybe_decide(\n          1, 77, \"9230012345678@c.us\", \"1\", \"in\", conn) is True,\n      \"hint\")\nhint_params = _sender_queue_params(conn)\ncheck(\"hint names the code\",\n      \"AP-AB12\" in json.loads(hint_params[1])[\"body\"],\n      json.loads(hint_params[1])[\"body\"])\n\n# code pick decides the right row\nconn = install_db_stub(portal_approvals, [\n    CONFIG_ROW, STATUS_ROW,\n    [{\"id\": 55, \"ref_code\": \"AP-AB12\"},\n     {\"id\": 56, \"ref_code\": \"AP-CD34\"}],\n    1,                                       # UPDATE decided\n    [{\"id\": 56, \"ref_code\": \"AP-CD34\", \"context_json\": None}],  # seam\n    [],                                      # audit\n    [],                                      # confirmation\n])\ncheck(\"code picks the row\",\n      portal_approvals.maybe_decide(\n          1, 77, \"9230012345678@c.us\", \"0 AP-CD34\", \"in\", conn) is True,\n      \"code\")\nupdate = next((p for sql, p in conn.cur.executed\n               if \"UPDATE portal_approvals\" in sql), None)\ncheck(\"coded reject hits id 56\", update is not None\n      and update[0] == \"rejected\" and update[3] == 56, update)\n\n# already decided / lost race -> claimed with a clear reply\nconn = install_db_stub(portal_approvals, [\n    CONFIG_ROW, STATUS_ROW,\n    [{\"id\": 55, \"ref_code\": \"AP-AB12\"}],\n    0,                                       # UPDATE hits nothing\n    [],                                      # \"already decide\" send\n])\ncheck(\"lost race still claimed\",\n      portal_approvals.maybe_decide(\n          1, 77, \"9230012345678@c.us\", \"1\", \"in\", conn) is True,\n      \"race\")\n\nprint(\"== portal API ==\")\n\nwith Principal(portal_approvals, principal=None):\n    check(\"list 401\", client.get(\n        \"/api/v1/portal/approvals\").status_code == 401, 401)\n\nwith Principal(portal_approvals, PRINCIPAL):\n    conn = install_db_stub(portal_approvals, [\n        [], [], [],              # DDL\n        [],                      # lazy expire UPDATE\n        [{\"id\": 55, \"conversation_id\": 77, \"contact_id\": \"923008887777@c.us\",\n          \"contact_name\": \"Ahmed Raza\", \"action\": \"refund\",\n          \"summary\": \"Refund request\", \"customer_query\": \"refund chahiye\",\n          \"context_json\": \"{}\", \"status\": \"pending\", \"source\": \"ai\",\n          \"ref_code\": \"AP-AB12\", \"decided_by\": None, \"decided_via\": None,\n          \"decided_at\": None, \"expires_at\": None,\n          \"created_at\": None}],\n    ])\n    r = client.get(\"/api/v1/portal/approvals\")\n    body = r.get_json()\n    check(\"list 200 + mapped\", r.status_code == 200\n          and body[\"approvals\"][0][\"refCode\"] == \"AP-AB12\"\n          and body[\"approvals\"][0][\"contactName\"] == \"Ahmed Raza\", body)\n\n    conn = install_db_stub(portal_approvals, [\n        [], [], [],              # DDL\n        [{\"id\": 55, \"ref_code\": \"AP-AB12\"}],\n        1,                       # UPDATE decided\n        [],                      # audit\n    ])\n    r = client.post(\"/api/v1/portal/approvals/55/decide\",\n                    json={\"decision\": \"approve\"})\n    check(\"decide 200\", r.status_code == 200\n          and r.get_json()[\"status\"] == \"approved\", r.get_json())\n\n    conn = install_db_stub(portal_approvals, [\n        [], [], [],\n        [],                      # pending SELECT -> none\n    ])\n    r = client.post(\"/api/v1/portal/approvals/99/decide\",\n                    json={\"decision\": \"approve\"})\n    check(\"decide unknown 404\", r.status_code == 404, r.status_code)\n\n    r = client.post(\"/api/v1/portal/approvals/55/decide\",\n                    json={\"decision\": \"maybe\"})\n    check(\"decide bad decision 400\", r.status_code == 400, r.status_code)\n\n    conn = install_db_stub(portal_approvals, [\n        [], [], [],\n        CONFIG_ROW,              # _load_config\n        CONFIG_ROW,              # _approver_digits config again\n        STATUS_ROW,              # connector phone\n    ])\n    r = client.get(\"/api/v1/portal/approvals/config\")\n    body = r.get_json()\n    check(\"config get\", r.status_code == 200\n          and body[\"selfChatAvailable\"] is True\n          and body[\"autoExpireHours\"] == 24, body)\n\n    conn = install_db_stub(portal_approvals, [\n        [], [], [],\n        [],                      # config upsert\n        [],                      # audit\n    ])\n    r = client.put(\"/api/v1/portal/approvals/config\",\n                   json={\"approvalNumber\": \"92300 123-4567\",\n                         \"autoExpireHours\": 48})\n    check(\"config put 200\", r.status_code == 200, r.get_json())\n    upsert = next((p for sql, p in conn.cur.executed\n                   if \"INSERT INTO portal_approvals_config\" in sql), None)\n    check(\"config digits normalized\", upsert is not None\n          and upsert[1] == \"923001234567\", upsert)\n\nTEAM = dict(PRINCIPAL, role=\"member\")\nwith Principal(portal_approvals, TEAM):\n    r = client.put(\"/api/v1/portal/approvals/config\",\n                   json={\"approvalNumber\": \"9230012345678\"})\n    check(\"config put member 403\", r.status_code == 403, r.status_code)\n\nportal_approvals.PortalAuthUnavailable = Exception\nwith Principal(portal_approvals, exc=Exception(\"db down\")):\n    r = client.get(\"/api/v1/portal/approvals\")\n    check(\"list auth down 503\", r.status_code == 503, r.status_code)\ndel portal_approvals.PortalAuthUnavailable\n\nprint(\"== web surface ==\")\n\nRIG13 = \"/tmp/p13/Omniflow/\"\n\nCONNECTOR = open(RIG13 + \"omniflow-backend-patch/connector_api.py\",\n                 encoding=\"utf8\").read()\ncheck(\"connector claims approvals first\",\n      CONNECTOR.index('claimed_by = \"approvals\"')\n      < CONNECTOR.index('claimed_by = \"away\"'), \"order\")\ncheck(\"connector side-effect hook\",\n      \"portal_approvals.maybe_request\" in CONNECTOR, \"hook\")\n\nSIDEBAR = open(RIG13 + \"app/dashboard/components/DashSidebar.tsx\",\n               encoding=\"utf8\").read()\ncheck(\"sidebar entry\", 'label: \"Approvals\"' in SIDEBAR\n      and \"/dashboard/approvals\" in SIDEBAR, \"sidebar\")\n\nimport os\ncheck(\"approvals page shipped\", os.path.exists(\n    RIG13 + \"app/dashboard/(portal)/approvals/page.tsx\"), \"page\")\ncheck(\"bff routes shipped\", all(os.path.exists(RIG13 + path) for path in (\n    \"app/api/omniflow/portal/approvals/route.ts\",\n    \"app/api/omniflow/portal/approvals/config/route.ts\",\n    \"app/api/omniflow/portal/approvals/[id]/decide/route.ts\")), \"bff\")\n\nPORTAL = open(RIG13 + \"lib/omniflow/portal.ts\", encoding=\"utf8\").read()\ncheck(\"portal.ts helpers\", \"export async function listApprovals\" in PORTAL\n      and \"export async function decideApproval\" in PORTAL\n      and \"export async function saveApprovalsConfig\" in PORTAL, \"helpers\")\n\nsummary(\"approvals\")\n");

